local embedded = {
    ["adapters/orbitui_ongoing_display"] = "-- Two presentations of the same ongoing-book card. The selected title is a\
-- preview; only opening it goes through KOReader's normal reading history.\
local Model = require(\"core/orbitui_dashboard\")\
local _ = require(\"core/orbitui_i18n\")\
local M = {}\
local floor, min, max = math.floor, math.min, math.max\
\
local function rect(x, y, w, h)\
    return { x = floor(x), y = floor(y), w = max(1, floor(w)), h = max(1, floor(h)) }\
end\
\
local function percent(book)\
    return floor(Model.fraction(book.data.percent) * 100 + .5)\
end\
\
-- Bounding box and inverse mapping shared by painting and hit testing.\
local function tilted(r, radians)\
    local c, s = math.cos(radians), math.sin(radians)\
    local w = math.ceil(math.abs(c) * r.w + math.abs(s) * r.h)\
    local h = math.ceil(math.abs(s) * r.w + math.abs(c) * r.h)\
    local area = rect(r.x + (r.w - w) / 2, r.y + (r.h - h) / 2, w, h)\
    local function source(x, y)\
        local dx, dy = x + .5 - w / 2, y + .5 - h / 2\
        return floor(r.w / 2 + dx*c + dy*s), floor(r.h / 2 - dx*s + dy*c)\
    end\
    area.contains = function(x, y)\
        local sx, sy = source(x, y)\
        return sx >= 0 and sx < r.w and sy >= 0 and sy < r.h\
    end\
    local function wrap(image)\
        local BB = require(\"ffi/blitbuffer\")\
        local view = require(\"ui/widget/widget\"):new{ dimen = require(\"ui/geometry\"):new{ w = w, h = h } }\
        function view:paintTo(bb, x, y)\
            if not self.rotated then\
                -- Use a private RGBA surface even on monochrome devices. The\
                -- source cover may be borrowed or a generated placeholder.\
                local src = BB.new(r.w, r.h, BB.TYPE_BBRGB32)\
                src:fill(BB.COLOR_WHITE)\
                image:paintTo(src, 0, 0)\
                local dst = BB.new(w, h, BB.TYPE_BBRGB32) -- zero alpha outside the cover\
                for yy = 0, h - 1 do\
                    local row = dst:getPixelP(0, yy)\
                    for xx = 0, w - 1 do\
                        local sx, sy = source(xx, yy)\
                        if sx >= 0 and sx < r.w and sy >= 0 and sy < r.h then\
                            row[xx] = src:getPixelP(sx, sy)[0]\
                            row[xx].alpha = 255\
                        end\
                    end\
                end\
                src:free()\
                self.rotated = dst\
            end\
            bb:alphablitFrom(self.rotated, x, y, 0, 0, w, h)\
        end\
        function view:free()\
            if self.rotated then self.rotated:free(); self.rotated = nil end\
            image:free()\
        end\
        return view\
    end\
    return area, wrap\
end\
\
function M.draw(v, r, data, selected, selectBook)\
    local books = data.featured\
    local px, text = v.px, v.text\
    local gap = px(6)\
    local left, right = r.x + v.pad, r.x + r.w - v.pad\
    local width = right - left\
    local top, bottom = r.y + v.pad, r.y + r.h - v.pad\
    local header_h = v.line(15, true) + gap\
    local see = text(_(\"See all\") .. \" ›\", left, top, width, 13, true)\
    local see_w = min(width, see:getSize().w + gap)\
    see.overlap_offset[1] = right - see:getSize().w\
    text(Model.heading(data.headings, \"hero\", _(\"Books in progress\")),\
        left, top, width - see_w - gap, 15, true)\
    v.action(rect(right - see_w, r.y, see_w + v.pad, top + header_h - r.y), v.seeAll)\
    v.rule(left, top + header_h, width)\
    top = top + header_h + gap\
    local pet = v.pet\
    if pet and bottom - top >= px(125) then\
        local foot_h = min(px(30), floor((bottom - top) * .14))\
        local y = bottom - foot_h\
        v.rule(left, y - gap, width)\
        v.sprite(pet, foot_h, left, y)\
        text(pet.name .. \"   \" .. pet.stage, left + foot_h + gap, y + max(0, floor((foot_h - v.line(13, true)) / 2)),\
            width - foot_h - gap, 13, true)\
        v.action(rect(left, y - gap, width, foot_h + gap), function() v.openPet(pet) end)\
        bottom = y - gap * 2\
    end\
    if #books == 0 then\
        text(_(\"Open a book to start reading.\"), left, top, width, 15, false, v.muted, 2)\
        return\
    end\
    local index = 1\
    for i, entry in ipairs(books) do if entry.file == selected then index = i; break end end\
    local book = books[index]\
    local function bookCover(i, area, angle)\
        local bounds, wrap = area, nil\
        if angle and angle ~= 0 then bounds, wrap = tilted(area, math.rad(angle)) end\
        local file = books[i].file\
        v.cover(file, area, bounds, wrap)\
        v.action(bounds, function()\
            if i == index then v.open(file) else selectBook(file) end\
        end, function(card) v.hold(file, card) end)\
    end\
    local fan = data.config.ongoing_style == \"fan\"\
    local h = bottom - top\
    if h < px(75) then\
        text(book.data.title, left, top, width, 17, true, nil, 1, true)\
        v.bookAction(rect(left, top, width, max(1, h)), book.file)\
        return\
    end\
    local copy_x, copy_y, copy_w = left, top, width\
    local title_size = fan and 21 or 23\
    local title_h = v.line(title_size, true)\
    local author_h, progress_h, button_h = v.line(14), v.line(14, true), max(px(31), v.line(15, true) + gap)\
    local copy_h = title_h + author_h + progress_h + button_h + px(4) + gap * 4\
    if h < title_h + progress_h + button_h + gap * 3 + px(4) then\
        text(book.data.title, left, top, width, 17, true)\
        text(string.format(_(\"%d%% read\"), percent(book)), left, top + v.line(17, true), width, 14, false)\
        v.bookAction(rect(left, top, width, h), book.file)\
        if #books > 1 then v.swipe(rect(left, top, width, h), function(delta)\
            selectBook(books[(index - 1 + delta) % #books + 1].file)\
        end) end\
        return\
    end\
    -- Shallow cards (notably landscape) put text alongside the fan.\
    local stacked = fan and h >= copy_h + px(76) and h >= width * .55\
    local art\
    if stacked then\
        art = rect(left, top, width, h - copy_h - gap)\
        copy_y = art.y + art.h + gap\
    else\
        local art_w = floor(width * (fan and .54 or .32))\
        art = rect(left, top, art_w, h)\
        copy_x, copy_w = left + art_w + gap * 2, width - art_w - gap * 2\
    end\
    local n = #books\
    if fan then\
        local layers, leftmost, rightmost = {}, 0, 0\
        for i = 1, n do\
            local offset = (i - index) % n\
            if offset > n / 2 then offset = offset - n end\
            local spread = n <= 3 and .78 or .58\
            local shift = offset * spread\
            -- With four books the lone jacket on one side can show more art.\
            if n == 4 and offset < 0 then shift = -.90 end\
            layers[#layers + 1] = { index = i, offset = offset, shift = shift }\
            leftmost, rightmost = min(leftmost, shift), max(rightmost, shift)\
        end\
        table.sort(layers, function(a, b) return math.abs(a.offset) > math.abs(b.offset) end)\
        local cw = max(1, floor(min(art.h / 1.64, art.w / (1.25 + rightmost - leftmost))))\
        local cy = art.y + art.h / 2\
        local cx = art.x + art.w / 2 - (leftmost + rightmost) * cw / 2\
        for _, layer in ipairs(layers) do\
            local offset = layer.offset\
            local w = max(1, floor(cw * (1 - .06 * math.abs(offset))))\
            local x = cx + layer.shift * cw - w / 2\
            bookCover(layer.index, rect(x, cy - .75*w + cw * .025 * math.abs(offset), w, 1.5*w), offset * 7)\
        end\
        if n > 1 then v.swipe(art, function(delta) selectBook(books[(index - 1 + delta) % n + 1].file) end) end\
    else\
        local cw = max(1, floor(min(art.h / 1.5, art.w)))\
        bookCover(index, rect(art.x + (art.w - cw) / 2, top + (h - cw * 1.5) / 2, cw, cw * 1.5))\
    end\
    local thumb_h = not fan and n > 1 and max(0, min(px(63), h - copy_h - v.line(12, true) - gap * 2)) or 0\
    local thumbs = thumb_h >= px(14)\
    local group_h = copy_h + (thumbs and thumb_h + v.line(12, true) + gap * 2 or 0)\
    if not stacked then copy_y = top + max(0, floor((h - group_h) / 2)) end\
    local align = stacked and \"center\" or \"left\"\
    local function label(value, size, bold, color)\
        text(value, copy_x, copy_y, copy_w, size, bold, color, 1, true, align)\
        copy_y = copy_y + v.line(size, bold)\
    end\
    label(book.data.title, title_size, true)\
    local author = require(\"infra/sui_text\").formatAuthors(book.data.authors)\
    if author and copy_y + author_h + progress_h + button_h + gap * 2 <= bottom then label(author, 14, false, v.muted) end\
    copy_y = copy_y + gap\
    local progress = string.format(_(\"%d%% read\"), percent(book))\
    if data.current and data.current.file == book.file and data.time_left then progress = progress .. \"  ·  \" .. data.time_left end\
    label(progress, 14, true)\
    local track_w = min(copy_w, px(stacked and 148 or 230))\
    v.bar(copy_x + (stacked and floor((copy_w - track_w) / 2) or 0), copy_y, track_w, book.data.percent, false, \"hero\")\
    copy_y = copy_y + px(4) + gap\
    local bw = min(copy_w, px(120))\
    local button = rect(copy_x + (stacked and floor((copy_w - bw) / 2) or 0), copy_y, bw, button_h)\
    v.button(button)\
    v.bookAction(button, book.file)\
    if thumbs then\
        local tw = min(floor(thumb_h / 1.5), floor((copy_w - (n - 2) * gap) / (n - 1)))\
        local tx, ty = copy_x, button.y + button.h + gap * 2\
        for i, entry in ipairs(books) do\
            if i ~= index and tw >= 1 then\
                local area = rect(tx, ty, tw, tw * 1.5)\
                local caption = data.config.cover_row_caption == \"title\" and entry.data.title or (percent(entry) .. \" %\")\
                bookCover(i, area)\
                text(caption, tx, ty + area.h, tw, 12, true, nil, 1, true, \"center\")\
                v.action(rect(tx, ty + area.h, tw, v.line(12, true)), function() selectBook(entry.file) end,\
                    function(card) v.hold(entry.file, card) end)\
                tx = tx + tw + gap\
            end\
        end\
    elseif not fan and n > 1 then\
        -- A very short card still lets the reader select every book.\
        v.swipe(art, function(delta) selectBook(books[(index - 1 + delta) % n + 1].file) end)\
    end\
end\
\
return M\
",
    ["adapters/orbitui_fingertips"] = "local M = {}\
local key = \"fingertips_enabled\"\
\
function M.attach(ui, loader)\
    if not (ui and ui.document and ui.highlight and ui.view and ui.view.registerViewModule)\
            or ui._orbitui_fingertips or ui.fingertips or ui.highlight._fingertips_wrapped then return end\
    local device = require(\"device\")\
    if not (device.isTouchDevice and device:isTouchDevice()) then return end\
    -- Reader plugins are instantiated in path order. The enabled class list\
    -- is complete even when the standalone instance has not been created yet.\
    for _, class in ipairs(loader.enabled_plugins or {}) do\
        if class.name == \"fingertips\" then return end\
    end\
    local instance = require(\"orbitui/fingertips/main\"):new{ ui = ui }\
    ui._orbitui_fingertips = instance\
    instance:onReaderReady()\
end\
\
function M.detach(ui)\
    local instance = ui and ui._orbitui_fingertips\
    if instance then\
        instance:detach()\
        ui._orbitui_fingertips = nil\
    end\
end\
\
function M.menuItems()\
    local _ = require(\"core/orbitui_i18n\")\
    local reader = package.loaded[\"apps/reader/readerui\"]\
    local ui = reader and reader.instance\
    local ft = ui and (ui._orbitui_fingertips or ui.fingertips)\
    local function enabled() return G_reader_settings:readSetting(key) ~= false end\
    return {\
        { text = _(\"FingerTips text selection\"), checked_func = enabled, keep_menu_open = true,\
            help_text = _(\"Show the text above your finger while selecting, then drag the handles to adjust it.\"),\
            callback = function()\
                local on = not enabled()\
                G_reader_settings:saveSetting(key, on)\
                if ft then\
                    ft.enabled = on\
                    if not on then ft:closeBar(); ft.phase = nil; ft:update() end\
                end\
            end },\
        { text = _(\"Show or hide selection actions\"), enabled_func = function()\
                return ft ~= nil and ft.enabled and ft.showArrange ~= nil\
            end,\
            callback = function() if ft and ft.enabled then ft:showArrange() end end },\
    }\
end\
\
return M\
",
    ["orbitui/fingertips/main"] = "-- Adapted from David Friedman's FingerTips v0.1.0 for OrbitUI on 2026-11-21.\
--[[\
FingerTips\
\
While you hold and drag to select text, your fingertip covers the words you\
are selecting. FingerTips:\
\
  * draws a copy of the selection a little above it (a 1:1 copy of the page,\
    not magnified), with a sliver of lighter context around it, in one panel\
    whose outline steps with the lines;\
  * shows handles at both ends of the selection from the moment you start;\
  * when you lift your finger, replaces KOReader's highlight popup with a\
    compact action bar above the selection, built from that same popup's\
    buttons, in the order you choose, a set at a time (More shows the next\
    set and wraps around);\
  * lets you drag either handle to adjust the selection: the bar steps aside\
    and the lifted copy comes back while you drag.\
\
How it hooks in:\
  * Drawing: a ReaderView \"view module\", painted after the page and its\
    highlights on every repaint.\
  * State: thin wrappers around this reader's ReaderHighlight instance\
    (onHold, onHoldPan, onHoldRelease, clear, onShowHighlightMenu). The\
    originals still do all the selecting; FingerTips only draws, and shows\
    its bar where KOReader would show its popup.\
]]\
\
local Device = require(\"device\")\
local Geom = require(\"ui/geometry\")\
local UIManager = require(\"ui/uimanager\")\
local WidgetContainer = require(\"ui/widget/container/widgetcontainer\")\
local logger = require(\"logger\")\
\
local Actions = require(\"orbitui/fingertips/actions\")\
local Bar = require(\"orbitui/fingertips/bar\")\
local Panel = require(\"orbitui/fingertips/panel\")\
\
local Screen = Device.screen\
\
-- How far the copy is lifted, in line heights (measured top to top).\
local LIFT = 2.25\
\
-- Line lock. During a drag, KOReader isn't told where the finger is, but\
-- where a pointer is that trails it, like a bead on a string. Distances are\
-- in line heights, from the pointer up to the finger:\
-- - Dragging down, the pointer stays LOCK_PULL above the finger, so a line\
--   is selected once your finger is about half a line below it.\
-- - Dragging back up, it stays LOCK_PUSH above the finger, so the line comes\
--   off again at about the same spot. The small gap between the two is the\
--   only slack: it stops a wobble from flickering a line on and off.\
-- The selection end stays on the middle of the pointer's line, so sliding\
-- left and right doesn't slip onto the next line.\
-- With the start handle it's the same, mirrored: the finger stays above.\
local LOCK_PULL = 1.65\
local LOCK_PUSH = 1.4\
-- Right after a long-press your finger is on the line itself, and going up\
-- takes moving half a line past its top edge: the pointer is then half a\
-- line below the finger.\
local LOCK_ON_UP = -0.5\
-- When a lock starts (a long-press, or grabbing a handle), the pointer\
-- starts at least this far inside its line, so a small wobble can't move it.\
local LOCK_EDGE = 0.3\
\
-- Outline thickness and corner radius of the copy, in KOReader's\
-- screen-scaled units (Screen:scaleBySize), so they look about the same\
-- size on any screen.\
local BORDER = 3\
local RADIUS = 9\
\
\
local FingerTips = WidgetContainer:extend{\
    name = \"fingertips\",\
    is_doc_only = true,\
}\
\
function FingerTips:init()\
    self.enabled = G_reader_settings:nilOrTrue(\"fingertips_enabled\")\
    self.lift = LIFT\
    self.finger = nil -- screen point of the finger (or the dragged handle)\
    self.loupe_line_y = nil -- top of the line the drag started on\
    self.loupe_hidden = false -- once the drag leaves that line, until the next one\
    self.border = BORDER\
    self.radius = RADIUS\
    -- nil: nothing shown; \"drag\": selecting (panel + handles);\
    -- \"bar\": action bar shown (handles); \"handle\": dragging a handle (panel + handles)\
    self.phase = nil\
    self.layout = nil -- what to draw\
    self.key = nil    -- fingerprint of the layout, to skip redundant refreshes\
    self.bar = nil\
end\
\
function FingerTips:onReaderReady()\
    self.ui.view:registerViewModule(\"fingertips\", self)\
    self:wrapHighlight()\
end\
\
function FingerTips:wrapHighlight()\
    local hl = self.ui.highlight\
    if not hl or hl._fingertips_wrapped then return end\
    hl._fingertips_wrapped = self\
    local hooks = {}\
    self.hooks = hooks\
    local function wrap(name, handler)\
        hooks[name] = { original = rawget(hl, name), handler = handler }\
        hl[name] = handler\
    end\
    local plugin = self\
\
    -- Wrapping the instance (not the class) keeps this local to the open\
    -- book, and the touch zones call hl:onHold() etc., so they reach us.\
    local orig_onHold = hl.onHold\
    wrap(\"onHold\", function(this, arg, ges, ...)\
        if not plugin.enabled then return orig_onHold(this, arg, ges, ...) end\
        local ret = orig_onHold(this, arg, ges, ...)\
        plugin:startLoupe(ges and ges.pos)\
        if this.hold_pos and this.selected_text then\
            plugin.phase = \"drag\"\
        end\
        plugin:update()\
        return ret\
    end)\
\
    local orig_onHoldPan = hl.onHoldPan\
    wrap(\"onHoldPan\", function(this, arg, ges, ...)\
        if not (plugin.enabled and ges and ges.pos and this.hold_pos) then\
            return orig_onHoldPan(this, arg, ges, ...)\
        end\
        -- KOReader gets the line-locked point instead of the finger's own.\
        local pos = plugin:lockedPoint(ges.pos)\
        local locked = {}\
        for k, v in pairs(ges) do locked[k] = v end\
        locked.pos = pos\
        local ret = orig_onHoldPan(this, arg, locked, ...)\
        plugin:relock()\
        -- The panel shows the line KOReader was given.\
        plugin.finger = { x = pos.x, y = pos.y }\
        plugin:update()\
        return ret\
    end)\
\
    local orig_onHoldRelease = hl.onHoldRelease\
    wrap(\"onHoldRelease\", function(this, ...)\
        -- Finger lifted: drop the panel before whatever comes next.\
        if plugin.phase == \"drag\" then\
            plugin.phase = nil\
            plugin:update()\
        end\
        return orig_onHoldRelease(this, ...)\
    end)\
\
    local orig_clear = hl.clear\
    wrap(\"clear\", function(this, ...)\
        if not plugin.enabled then return orig_clear(this, ...) end\
        local ret = orig_clear(this, ...)\
        plugin:closeBar()\
        plugin.phase = nil\
        plugin:update()\
        return ret\
    end)\
\
    -- Where KOReader would open its popup for a new selection, show the bar.\
    -- (With an index, it's the popup for an existing highlight: left alone.)\
    local orig_onShowHighlightMenu = hl.onShowHighlightMenu\
    wrap(\"onShowHighlightMenu\", function(this, index, ...)\
        if index == nil and plugin.enabled and this.selected_text and this.hold_pos then\
            local ok, shown = pcall(plugin.showBar, plugin)\
            if ok and shown then return true end\
            if not ok then\
                logger.warn(\"FingerTips: could not show the action bar:\", shown)\
                plugin:closeBar()\
                plugin.phase = nil\
                plugin:update()\
            end\
        end\
        return orig_onShowHighlightMenu(this, index, ...)\
    end)\
end\
\
-- Screen rectangles of the current selection, one per line, top to bottom.\
function FingerTips:getLineBoxes()\
    local hl = self.ui.highlight\
    local sel = hl.selected_text\
    if not (hl.hold_pos and sel and sel.sboxes and #sel.sboxes > 0) then\
        return nil\
    end\
    local sboxes = sel.sboxes\
    -- A long-pressed word comes with a single box, which for a word that\
    -- wraps (Some-|where) covers both lines and the space between: ask\
    -- crengine for that word's boxes line by line instead.\
    if #sboxes == 1 and self.ui.rolling and type(sel.pos0) == \"string\" and type(sel.pos1) == \"string\" then\
        local doc = self.ui.document\
        local ok, per_line = pcall(doc.getScreenBoxesFromPositions, doc, sel.pos0, sel.pos1, true)\
        if ok and per_line and #per_line > 0 then sboxes = per_line end\
    end\
    local boxes = {}\
    for i = 1, #sboxes do\
        -- sboxes are already screen boxes with crengine (EPUB...), and page\
        -- boxes with PDF/DjVu; this converts the latter and passes the former.\
        local r = self.ui.view:pageToScreenTransform(hl.hold_pos.page, sboxes[i])\
        if r and r.w > 0 and r.h > 0 then\
            table.insert(boxes, Geom:new{ x = r.x, y = r.y, w = r.w, h = r.h })\
        end\
    end\
    if #boxes == 0 then return nil end\
\
    -- A line can come back as several segments (inline styles, links...):\
    -- merge segments that share a line into one box.\
    table.sort(boxes, function(a, b)\
        if a.y ~= b.y then return a.y < b.y end\
        return a.x < b.x\
    end)\
    local lines = {}\
    for i = 1, #boxes do\
        local b = boxes[i]\
        local last = lines[#lines]\
        local b_mid = b.y + b.h / 2\
        if last and b_mid > last.y and b_mid < last.y + last.h then\
            lines[#lines] = last:combine(b)\
        else\
            table.insert(lines, b)\
        end\
    end\
    return lines\
end\
\
-- A new gesture (a long-press, or grabbing a handle) brings the loupe back.\
function FingerTips:startLoupe(pos, side)\
    self.finger = pos and { x = pos.x, y = pos.y } or nil\
    self.lock_side = side or \"on\"\
    self.loupe_line_y = nil\
    self.loupe_hidden = false\
    self.lock = nil\
    self.relock_y = nil\
end\
\
-- The selection's line under the finger, or the nearest one. Using the line\
-- (not crengine's word box) keeps a word that wraps onto the next line from\
-- stretching the loupe over both lines.\
local function fingerLine(lines, finger)\
    if not finger then return lines[#lines] end\
    local best, best_d\
    for _, l in ipairs(lines) do\
        if finger.y >= l.y and finger.y < l.y + l.h then return l end\
        local d = math.abs(finger.y - (l.y + l.h / 2))\
        if not best_d or d < best_d then best, best_d = l, d end\
    end\
    return best\
end\
\
-- The \"One line\" panel: the selection on the line where the drag started,\
-- growing as it grows. Nil once the drag has reached another line (like\
-- iOS, it stays away until the next gesture).\
function FingerTips:loupeLine(lines)\
    if self.loupe_hidden then return nil end\
    local line = fingerLine(lines, self.finger)\
    if not self.loupe_line_y then\
        self.loupe_line_y = line.y\
    elseif math.abs(line.y - self.loupe_line_y) > line.h / 2 then\
        self.loupe_hidden = true\
        return nil\
    end\
    return line\
end\
\
-- The pointer's allowed distance above the finger for each kind of drag\
-- (lowest, highest), and where it starts when a lock begins.\
local function lockWindow(side)\
    local slack = LOCK_PULL - LOCK_PUSH\
    if side == \"below\" then return LOCK_PUSH, LOCK_PULL, LOCK_PUSH end\
    if side == \"above\" then return -LOCK_PULL, -LOCK_PUSH, -LOCK_PUSH end\
    if side == \"lead\" then return LOCK_ON_UP, LOCK_ON_UP + slack, LOCK_ON_UP end\
    return LOCK_ON_UP, LOCK_PULL, 0 -- \"on\": just after a long-press\
end\
\
-- Starts the line lock on a line, with the finger touching at touch_y.\
function FingerTips:initLock(l, touch_y)\
    local h = l.h\
    local lo, hi, start = lockWindow(self.lock_side)\
    local m = LOCK_EDGE * h\
    local ptr = math.max(l.y + m, math.min(l.y + l.h - m, touch_y - start * h))\
    local off = (touch_y - ptr) / h\
    -- If the pointer had to start closer to the finger than usual, the\
    -- window widens to fit, and narrows back as the finger moves.\
    self.lock = { ptr = ptr, h = h, top = l.y, bottom = l.y + l.h,\
        lo = math.min(lo, off), hi = math.max(hi, off) }\
end\
\
-- Where to tell KOReader the finger is during a drag: the same left-right,\
-- and up-down the middle of the pointer's line (see LOCK_PULL, LOCK_PUSH).\
function FingerTips:lockedPoint(pos)\
    local sw, sh = Screen:getWidth(), Screen:getHeight()\
    -- KOReader's corners for selecting across pages: leave those alone.\
    if (pos.y < sh / 8 or pos.y > sh * 7 / 8) and (pos.x < sw / 8 or pos.x > sw * 7 / 8) then\
        self.lock = nil\
        return pos\
    end\
    if not self.lock then\
        local lines = self:getLineBoxes()\
        if not lines then return pos end\
        self:initLock(fingerLine(lines, self.finger or pos), pos.y)\
    end\
    local lk = self.lock\
    -- The finger drags the pointer along once it's out of its window.\
    local off = (pos.y - lk.ptr) / lk.h\
    if off > lk.hi then\
        lk.ptr = pos.y - lk.hi * lk.h\
    elseif off < lk.lo then\
        lk.ptr = pos.y - lk.lo * lk.h\
    end\
    local y\
    if lk.ptr >= lk.top and lk.ptr < lk.bottom then\
        y = (lk.top + lk.bottom) / 2\
    else\
        y = lk.ptr\
        self.relock_y = lk.ptr\
        -- Leaving the long-pressed line: from now on the finger trails\
        -- below the end going down, or stays on the text going up.\
        if self.lock_side == \"on\" then\
            self.lock_side = lk.ptr >= lk.bottom and \"below\" or \"lead\"\
        end\
    end\
    -- Narrow a widened window back as far as where the finger now is.\
    local lo, hi = lockWindow(self.lock_side)\
    off = (pos.y - lk.ptr) / lk.h\
    lk.lo = math.min(lo, math.max(lk.lo, off))\
    lk.hi = math.max(hi, math.min(lk.hi, off))\
    y = math.max(0, math.min(sh - 1, math.floor(y + 0.5)))\
    return Geom:new{ x = pos.x, y = y, w = 0, h = 0 }\
end\
\
-- After the pointer reached another line, lock onto that line's real\
-- position (paragraph gaps, headings...).\
function FingerTips:relock()\
    local y = self.relock_y\
    if not y then return end\
    self.relock_y = nil\
    local lk = self.lock\
    local lines = self:getLineBoxes()\
    if not (lk and lines) then return end\
    local l = fingerLine(lines, { x = 0, y = y })\
    lk.top, lk.bottom, lk.h = l.y, l.y + l.h, l.h\
end\
\
-- Recompute what to show for the current phase and selection, and ask for a\
-- refresh of the affected area only if something actually changed.\
function FingerTips:update()\
    local layout\
    if self.enabled and self.phase then\
        local lines = self:getLineBoxes()\
        if lines then\
            local panel_line\
            if self.phase == \"drag\" or self.phase == \"handle\" then\
                panel_line = self:loupeLine(lines)\
            end\
            layout = Panel.computeLayout(lines, {\
                lift = self.lift,\
                border = self.border,\
                radius = self.radius,\
                with_handles = true,\
                panel_line = panel_line,\
            })\
        end\
    end\
    if layout and self.layout and layout.key == self.key then return end\
    local old = self.layout\
    self.layout, self.key = layout, layout and layout.key\
    local dirty = layout and layout.region\
    if old then dirty = dirty and dirty:combine(old.region) or old.region end\
    if dirty then\
        UIManager:setDirty(self.ui.highlight.dialog, \"ui\", dirty)\
    end\
end\
\
-- Called by ReaderView after it has drawn the page and the highlights.\
function FingerTips:paintTo(bb, x, y)\
    if not self.layout then return end\
    local ok, err = pcall(Panel.paint, bb, x, y, self.layout)\
    if not ok then logger.warn(\"FingerTips: paint failed:\", err) end\
end\
\
---------------------------------------------------------------------------\
-- Action bar\
---------------------------------------------------------------------------\
\
function FingerTips:showBar()\
    local hl = self.ui.highlight\
    if not self:getLineBoxes() then return false end\
    local actions = Actions.forBar(hl)\
    if #actions == 0 then return false end\
    self:closeBar()\
    self.phase = \"bar\"\
    self:update()\
    local bar = Bar:new{\
        plugin = self,\
        hl = hl,\
        actions = actions,\
        rows = Actions.rows(),\
        border = self.border,\
        radius = self.radius,\
    }\
    self.bar = bar\
    hl.highlight_dialog = bar -- so KOReader's own actions close it when done\
    UIManager:show(bar, \"ui\", bar.bar_rect)\
    return true\
end\
\
function FingerTips:closeBar()\
    if self.bar then\
        UIManager:close(self.bar) -- onBarClosed() does the rest\
    end\
end\
\
function FingerTips:onBarClosed(bar)\
    if self.bar ~= bar then return end\
    self.bar = nil\
    local hl = self.ui.highlight\
    if hl.highlight_dialog == bar then hl.highlight_dialog = nil end\
    if self.phase == \"bar\" or self.phase == \"handle\" then\
        self.phase = nil\
        self:update()\
    end\
end\
\
-- Where the bar goes: above the selection, as far from it as the panel is;\
-- below it if there's no room above; centred over it, kept on screen.\
function FingerTips:barPosition(w, h)\
    local sw, sh = Screen:getWidth(), Screen:getHeight()\
    local margin = Screen:scaleBySize(6)\
    local lines = self:getLineBoxes()\
    if not lines then\
        return math.floor((sw - w) / 2), math.floor((sh - h) / 2)\
    end\
    local line_h = Panel.averageLineHeight(lines)\
    local hg = Panel.handleGeometry(lines)\
    local border = math.max(1, Screen:scaleBySize(self.border))\
    local gap = math.floor(line_h * (self.lift - 1 - Panel.CONTEXT_V) + 0.5) - border\
    gap = math.max(gap, 2 * hg.r + Screen:scaleBySize(4))\
    local top = lines[1].y\
    local bottom = lines[#lines].y + lines[#lines].h\
    local left, right = math.huge, -math.huge\
    for _, l in ipairs(lines) do\
        left = math.min(left, l.x)\
        right = math.max(right, l.x + l.w)\
    end\
    local y\
    if top - gap - h >= 0 then\
        y = top - gap - h\
    elseif bottom + gap + h <= sh then\
        y = bottom + gap\
    elseif top > sh - bottom then\
        y = 0\
    else\
        y = sh - h\
    end\
    local x = math.floor((left + right - w) / 2)\
    x = math.max(margin, math.min(sw - margin - w, x))\
    return x, math.floor(y)\
end\
\
---------------------------------------------------------------------------\
-- Handles\
---------------------------------------------------------------------------\
\
-- The handle under pos, if any: { which = \"start\"|\"stop\", dx, dy }, where\
-- (dx, dy) leads from pos to the selection edge that handle marks.\
function FingerTips:handleAt(pos)\
    local layout = self.layout\
    if not (layout and layout.handles and pos) then return nil end\
    local hg = layout.handles\
    local lines = self:getLineBoxes()\
    if not lines then return nil end\
    local reach = math.max(Screen:scaleBySize(28), Panel.averageLineHeight(lines))\
    local best, best_d\
    for _, which in ipairs({ \"start\", \"stop\" }) do\
        local hd = hg[which]\
        local y0 = math.min(hd.top, hd.knob_y - hg.r)\
        local y1 = math.max(hd.bottom, hd.knob_y + hg.r)\
        local ddx = pos.x - hd.x\
        local ddy = 0\
        if pos.y < y0 then ddy = y0 - pos.y elseif pos.y > y1 then ddy = pos.y - y1 end\
        local d = math.sqrt(ddx * ddx + ddy * ddy)\
        if d <= reach and (not best_d or d < best_d) then\
            best, best_d = which, d\
        end\
    end\
    if not best then return nil end\
    local hd = hg[best]\
    local ex = best == \"start\" and hd.x + 1 or hd.x - 1\
    local ey = math.floor((hd.top + hd.bottom) / 2)\
    return { which = best, dx = ex - pos.x, dy = ey - pos.y, touch_y = pos.y }\
end\
\
-- Dragging one handle means the other end stays put: make that end the\
-- point KOReader extends the selection from, as if the hold started there.\
function FingerTips:beginHandleDrag(which, touch_y)\
    local hl = self.ui.highlight\
    local lines = self:getLineBoxes()\
    if not lines then return end\
    local ax, ay\
    if which == \"stop\" then\
        local l = lines[1]\
        ax, ay = l.x + 1, l.y + l.h / 2\
    else\
        local l = lines[#lines]\
        ax, ay = l.x + l.w - 1, l.y + l.h / 2\
    end\
    local anchor = self.ui.view:screenToPageTransform(Geom:new{ x = math.floor(ax), y = math.floor(ay), w = 0, h = 0 })\
    if anchor then hl.hold_pos = anchor end\
    -- The one-line panel comes back, on the line of the end being dragged,\
    -- and the finger stays on the handle's side of it.\
    local l = which == \"stop\" and lines[#lines] or lines[1]\
    local ex = which == \"stop\" and l.x + l.w - 1 or l.x + 1\
    self:startLoupe({ x = math.floor(ex), y = math.floor(l.y + l.h / 2) },\
        which == \"stop\" and \"below\" or \"above\")\
    if touch_y then self:initLock(l, touch_y) end\
    self.phase = \"handle\"\
    self:update()\
end\
\
function FingerTips:moveHandle(pos)\
    self.ui.highlight:onHoldPan(nil, { ges = \"hold_pan\", pos = pos })\
end\
\
function FingerTips:endHandleDrag()\
    -- KOReader's long-hold timer is restarted by every selection change;\
    -- stop it, as a normal release would.\
    local hl = self.ui.highlight\
    if hl._resetHoldTimer then pcall(hl._resetHoldTimer, hl, true) end\
    self.phase = \"bar\"\
    self:update()\
end\
\
---------------------------------------------------------------------------\
-- Menu\
---------------------------------------------------------------------------\
\
function FingerTips:showArrange()\
    UIManager:show(require(\"orbitui/fingertips/arrange\"):new{ hl = self.ui.highlight }, \"flashui\")\
end\
\
function FingerTips:detach()\
    self.enabled = false\
    self:closeBar()\
    self.phase = nil\
    self:update()\
    local view, hl = self.ui.view, self.ui.highlight\
    if view.view_modules and view.view_modules.fingertips == self then\
        view.view_modules.fingertips = nil\
    end\
    for name, hook in pairs(self.hooks or {}) do\
        if hl[name] == hook.handler then hl[name] = hook.original end\
    end\
    if hl._fingertips_wrapped == self then hl._fingertips_wrapped = nil end\
    self.hooks = nil\
end\
\
return FingerTips\
",
    ["orbitui/fingertips/actions"] = "-- Adapted from David Friedman's FingerTips v0.1.0 for OrbitUI on 2026-11-21.\
--[[\
FingerTips: the actions offered in the action bar.\
\
They are exactly the buttons of KOReader's own highlight popup, including the\
ones other plugins add to it. FingerTips only stores which of them are on the\
bar and in what order (by the popup's own button ids, e.g. \"03_copy\").\
]]\
\
local ffiUtil = require(\"ffi/util\")\
local logger = require(\"logger\")\
local _ = require(\"core/orbitui_i18n\")\
\
local Actions = {}\
\
local ORDER_KEY = \"fingertips_bar_order\"\
local HIDDEN_KEY = \"fingertips_bar_hidden\"\
local ROWS_KEY = \"fingertips_bar_rows\"\
\
local function makeButton(hl, id)\
    local fn = hl._highlight_buttons and hl._highlight_buttons[id]\
    if type(fn) ~= \"function\" then return nil end\
    local ok, button = pcall(fn, hl, nil)\
    if ok and type(button) == \"table\" then return button end\
    if not ok then logger.warn(\"FingerTips: popup button\", id, \"failed:\", button) end\
end\
\
local function labelOf(button, id)\
    if button.text then return button.text end\
    if button.text_func then\
        local ok, text = pcall(button.text_func)\
        if ok and text then return text end\
    end\
    return id\
end\
\
-- Every popup button: { id, label, conditional }, in KOReader's own order.\
-- conditional: it only shows up when it applies (a link, a single word...).\
function Actions.all(hl)\
    local list = {}\
    if type(hl._highlight_buttons) ~= \"table\" then return list end\
    for id in ffiUtil.orderedPairs(hl._highlight_buttons) do\
        local button = makeButton(hl, id)\
        if button then\
            table.insert(list, {\
                id = id,\
                label = labelOf(button, id),\
                conditional = button.show_in_highlight_dialog_func ~= nil,\
            })\
        end\
    end\
    return list\
end\
\
-- The saved arrangement applied to what exists now: shown ids in bar order,\
-- and hidden ids. Buttons FingerTips hasn't seen before go at the end of the\
-- shown ones, where they can be moved or unticked.\
function Actions.arrangement(hl)\
    local all = Actions.all(hl)\
    local exists = {}\
    for _, a in ipairs(all) do exists[a.id] = true end\
    local saved_order = G_reader_settings:readSetting(ORDER_KEY) or {}\
    local saved_hidden = G_reader_settings:readSetting(HIDDEN_KEY) or {}\
    local placed, shown, hidden = {}, {}, {}\
    for _, id in ipairs(saved_hidden) do\
        if exists[id] and not placed[id] then\
            placed[id] = true\
            table.insert(hidden, id)\
        end\
    end\
    for _, id in ipairs(saved_order) do\
        if exists[id] and not placed[id] then\
            placed[id] = true\
            table.insert(shown, id)\
        end\
    end\
    for _, a in ipairs(all) do\
        if not placed[a.id] then\
            placed[a.id] = true\
            table.insert(shown, a.id)\
        end\
    end\
    return shown, hidden, all\
end\
\
-- Saves an arrangement. Ids that aren't available right now (say, View HTML\
-- while a PDF is open) keep their saved place at the end of their list.\
function Actions.save(hl, shown, hidden)\
    local exists = {}\
    for _, a in ipairs(Actions.all(hl)) do exists[a.id] = true end\
    local function merge(list, key)\
        local out, seen = {}, {}\
        for _, id in ipairs(list) do\
            if not seen[id] then seen[id] = true; table.insert(out, id) end\
        end\
        for _, id in ipairs(G_reader_settings:readSetting(key) or {}) do\
            if not exists[id] and not seen[id] then\
                seen[id] = true\
                table.insert(out, id)\
            end\
        end\
        return out\
    end\
    G_reader_settings:saveSetting(ORDER_KEY, merge(shown, ORDER_KEY))\
    G_reader_settings:saveSetting(HIDDEN_KEY, merge(hidden, HIDDEN_KEY))\
end\
\
function Actions.rows()\
    return G_reader_settings:readSetting(ROWS_KEY, 1) == 2 and 2 or 1\
end\
\
-- How many actions each set holds, given how many there are in all: with\
-- room for everything, one set; otherwise every set saves a spot for More.\
function Actions.perSet(rows, count)\
    local slots = rows * 4\
    if count <= slots then return slots, false end\
    return slots - 1, true\
end\
\
-- The buttons to put on the bar right now, as KOReader would build them for\
-- its popup, in the user's order, leaving out those that don't apply.\
function Actions.forBar(hl)\
    local shown = Actions.arrangement(hl)\
    local list = {}\
    for _, id in ipairs(shown) do\
        local button = makeButton(hl, id)\
        if button then\
            local applies = true\
            if button.show_in_highlight_dialog_func then\
                local ok, res = pcall(button.show_in_highlight_dialog_func)\
                applies = ok and res and true or false\
            end\
            if applies then\
                table.insert(list, { id = id, button = button })\
            end\
        end\
    end\
    return list\
end\
\
Actions.MORE = _(\"More\")\
\
return Actions\
",
    ["orbitui/fingertips/arrange"] = "-- Adapted from David Friedman's FingerTips v0.1.0 for OrbitUI on 2026-11-21.\
--[[\
FingerTips: the \"Action bar\" settings screen.\
\
Tap a box to toggle an action. Select a row and use the arrows to change\
the order of the overflow actions. OrbitUI's shortcut editor orders the\
favorites on the first page.\
]]\
\
local Blitbuffer = require(\"ffi/blitbuffer\")\
local BottomContainer = require(\"ui/widget/container/bottomcontainer\")\
local ButtonTable = require(\"ui/widget/buttontable\")\
local CheckMark = require(\"ui/widget/checkmark\")\
local Device = require(\"device\")\
local Font = require(\"ui/font\")\
local FrameContainer = require(\"ui/widget/container/framecontainer\")\
local Geom = require(\"ui/geometry\")\
local GestureRange = require(\"ui/gesturerange\")\
local HorizontalGroup = require(\"ui/widget/horizontalgroup\")\
local HorizontalSpan = require(\"ui/widget/horizontalspan\")\
local InputContainer = require(\"ui/widget/container/inputcontainer\")\
local LeftContainer = require(\"ui/widget/container/leftcontainer\")\
local OverlapGroup = require(\"ui/widget/overlapgroup\")\
local TextBoxWidget = require(\"ui/widget/textboxwidget\")\
local TextWidget = require(\"ui/widget/textwidget\")\
local TitleBar = require(\"ui/widget/titlebar\")\
local UIManager = require(\"ui/uimanager\")\
local VerticalGroup = require(\"ui/widget/verticalgroup\")\
local VerticalSpan = require(\"ui/widget/verticalspan\")\
local Actions = require(\"orbitui/fingertips/actions\")\
local _ = require(\"core/orbitui_i18n\")\
local T = require(\"ffi/util\").template\
\
local Screen = Device.screen\
\
\
local Arrange = InputContainer:extend{\
    hl = nil,\
    covers_fullscreen = true,\
}\
\
function Arrange:init()\
    local sw, sh = Screen:getWidth(), Screen:getHeight()\
    self.dimen = Geom:new{ x = 0, y = 0, w = sw, h = sh }\
    self.ges_events = {\
        FtArrangeTap = { GestureRange:new{ ges = \"tap\", range = self.dimen } },\
    }\
    if Device:hasKeys() then\
        self.key_events = { FtArrangeClose = { { Device.input.group.Back } } }\
    end\
    self.shown, self.hidden, self.all = Actions.arrangement(self.hl)\
    self.info = {}\
    for _, a in ipairs(self.all) do self.info[a.id] = a end\
    self:build()\
end\
\
function Arrange:labelFor(id)\
    local a = self.info[id]\
    if not a then return id end\
    if a.conditional then\
        return T(_(\"%1 (only when it applies)\"), a.label)\
    end\
    return a.label\
end\
\
-- The list as it will be drawn: headings and actions, in order.\
function Arrange:entries()\
    local list = {}\
    if #self.shown > 0 then\
        table.insert(list, { heading = _(\"Visible actions\") })\
        for _, id in ipairs(self.shown) do table.insert(list, { id = id, checked = true }) end\
    end\
    if #self.hidden > 0 then\
        table.insert(list, { heading = _(\"Not in the popup\") })\
        for _, id in ipairs(self.hidden) do\
            table.insert(list, { id = id, checked = false })\
        end\
    end\
    return list\
end\
\
function Arrange:build()\
    local sw, sh = Screen:getWidth(), Screen:getHeight()\
    local pad = Screen:scaleBySize(16)\
    if self[1] then self[1]:free() end\
\
    local title = TitleBar:new{\
        width = sw,\
        fullscreen = true,\
        title = _(\"Selection actions\"),\
        with_bottom_line = true,\
        close_callback = function() self:onFtArrangeClose() end,\
        show_parent = self,\
    }\
    local hint = TextBoxWidget:new{\
        text = _(\"Tap a box to show or hide an action. Move actions to change their order under More.\"),\
        face = Font:getFace(\"cfont\", 16),\
        width = sw - 2 * pad,\
        fgcolor = Blitbuffer.COLOR_DARK_GRAY,\
    }\
    local selected = self.selected\
    local bottom = ButtonTable:new{\
        width = sw,\
        zero_sep = true,\
        buttons = {{\
            {\
                text = \"▲ \" .. _(\"Move up\"),\
                enabled = selected ~= nil,\
                callback = function() self:move(-1) end,\
            },\
            {\
                text = \"▼ \" .. _(\"Move down\"),\
                enabled = selected ~= nil,\
                callback = function() self:move(1) end,\
            },\
        }},\
        show_parent = self,\
    }\
\
    local head = VerticalGroup:new{\
        align = \"left\",\
        title,\
        VerticalSpan:new{ width = Screen:scaleBySize(8) },\
        LeftContainer:new{\
            dimen = Geom:new{ w = sw, h = hint:getSize().h },\
            HorizontalGroup:new{ HorizontalSpan:new{ width = pad }, hint },\
        },\
        VerticalSpan:new{ width = Screen:scaleBySize(6) },\
    }\
    local head_h = head:getSize().h\
\
    -- Fit the list in the space left, shrinking rows if there are many.\
    local entries = self:entries()\
    local n_items, n_heads = 0, 0\
    for _, e in ipairs(entries) do\
        if e.heading then n_heads = n_heads + 1 else n_items = n_items + 1 end\
    end\
    local avail = sh - head_h - bottom:getSize().h - Screen:scaleBySize(4)\
    local item_h = Screen:scaleBySize(46)\
    local head_h_each = math.floor(item_h * 0.65)\
    local need = n_items * item_h + n_heads * head_h_each\
    if need > avail then\
        local f = avail / need\
        item_h = math.floor(item_h * f)\
        head_h_each = math.floor(head_h_each * f)\
    end\
    local font_size = math.max(12, math.min(20, math.floor(20 * item_h / Screen:scaleBySize(46))))\
    local face = Font:getFace(\"cfont\", font_size)\
    local small = Font:getFace(\"cfont\", math.max(11, font_size - 4))\
\
    local list = VerticalGroup:new{ align = \"left\" }\
    self.hit = {}\
    local y = head_h\
    for _, e in ipairs(entries) do\
        if e.heading then\
            table.insert(list, LeftContainer:new{\
                dimen = Geom:new{ w = sw, h = head_h_each },\
                HorizontalGroup:new{\
                    HorizontalSpan:new{ width = pad },\
                    TextWidget:new{ text = e.heading, face = small, fgcolor = Blitbuffer.COLOR_DARK_GRAY },\
                },\
            })\
            y = y + head_h_each\
        else\
            local is_sel = e.id == selected\
            local check = CheckMark:new{ checked = e.checked, face = face }\
            local check_w = check:getSize().w\
            table.insert(list, FrameContainer:new{\
                bordersize = 0,\
                padding = 0,\
                margin = 0,\
                background = is_sel and Blitbuffer.COLOR_LIGHT_GRAY or nil,\
                LeftContainer:new{\
                    dimen = Geom:new{ w = sw, h = item_h },\
                    HorizontalGroup:new{\
                        HorizontalSpan:new{ width = pad },\
                        check,\
                        HorizontalSpan:new{ width = Screen:scaleBySize(10) },\
                        TextWidget:new{\
                            text = self:labelFor(e.id),\
                            face = face,\
                            bold = is_sel,\
                            max_width = sw - 2 * pad - check_w - Screen:scaleBySize(10),\
                        },\
                    },\
                },\
            })\
            table.insert(self.hit, {\
                id = e.id, y0 = y, y1 = y + item_h,\
                -- the box and a bit around it toggles; the rest picks the row\
                box_x1 = pad + check_w + Screen:scaleBySize(10),\
            })\
            y = y + item_h\
        end\
    end\
\
    self[1] = FrameContainer:new{\
        bordersize = 0,\
        padding = 0,\
        margin = 0,\
        background = Blitbuffer.COLOR_WHITE,\
        OverlapGroup:new{\
            dimen = Geom:new{ w = sw, h = sh },\
            VerticalGroup:new{ align = \"left\", head, list },\
            BottomContainer:new{\
                dimen = Geom:new{ w = sw, h = sh },\
                bottom,\
            },\
        },\
    }\
end\
\
function Arrange:refresh()\
    self:build()\
    UIManager:setDirty(self, \"ui\")\
end\
\
function Arrange:save()\
    Actions.save(self.hl, self.shown, self.hidden)\
end\
\
local function indexOf(list, id)\
    for i, v in ipairs(list) do\
        if v == id then return i end\
    end\
end\
\
function Arrange:toggle(id)\
    local i = indexOf(self.shown, id)\
    if i then\
        table.remove(self.shown, i)\
        table.insert(self.hidden, id)\
    else\
        i = indexOf(self.hidden, id)\
        if i then table.remove(self.hidden, i) end\
        table.insert(self.shown, id)\
    end\
    self:save()\
    self:refresh()\
end\
\
function Arrange:move(delta)\
    local id = self.selected\
    if not id then return end\
    for _, list in ipairs({ self.shown, self.hidden }) do\
        local i = indexOf(list, id)\
        if i then\
            local j = i + delta\
            if j >= 1 and j <= #list then\
                list[i], list[j] = list[j], list[i]\
                self:save()\
            end\
            break\
        end\
    end\
    UIManager:nextTick(function() self:refresh() end)\
end\
\
function Arrange:onFtArrangeTap(_, ges)\
    local pos = ges.pos\
    for _, h in ipairs(self.hit) do\
        if pos.y >= h.y0 and pos.y < h.y1 then\
            if pos.x < h.box_x1 then\
                self:toggle(h.id)\
            else\
                self.selected = (self.selected ~= h.id) and h.id or nil\
                self:refresh()\
            end\
            return true\
        end\
    end\
    return true\
end\
\
function Arrange:onFtArrangeClose()\
    UIManager:close(self, \"ui\")\
    return true\
end\
\
return Arrange\
",
    ["orbitui/fingertips/bar"] = "-- Adapted from David Friedman's FingerTips v0.1.0 for OrbitUI on 2026-11-21.\
--[[\
FingerTips: the action bar shown after you lift your finger.\
\
It sits above the selection (below it when there's no room), never over it.\
It shows one set of actions at a time; More swaps in the next set, and from\
the last set it wraps around to the first.\
\
The bar is shown as a transparent full-screen layer so it also sees touches\
outside itself: dragging a handle adjusts the selection (the bar hides and\
the lifted panel comes back meanwhile), a tap elsewhere closes the bar and\
clears the selection, and a long-press elsewhere starts a new selection.\
]]\
\
local Blitbuffer = require(\"ffi/blitbuffer\")\
local ButtonTable = require(\"ui/widget/buttontable\")\
local Device = require(\"device\")\
local FrameContainer = require(\"ui/widget/container/framecontainer\")\
local Geom = require(\"ui/geometry\")\
local GestureRange = require(\"ui/gesturerange\")\
local InputContainer = require(\"ui/widget/container/inputcontainer\")\
local UIManager = require(\"ui/uimanager\")\
local Actions = require(\"orbitui/fingertips/actions\")\
local _ = require(\"core/orbitui_i18n\")\
\
local Screen = Device.screen\
\
local Bar = InputContainer:extend{\
    plugin = nil,   -- the FingerTips plugin\
    hl = nil,       -- the reader's ReaderHighlight\
    actions = nil,  -- from Actions.forBar()\
    rows = 1,\
    border = 3,     -- screen-scaled units, like the panel's outline\
    radius = 9,\
}\
\
function Bar:init()\
    local sw, sh = Screen:getWidth(), Screen:getHeight()\
    self.dimen = Geom:new{ x = 0, y = 0, w = sw, h = sh }\
    local function on(ges) return { GestureRange:new{ ges = ges, range = self.dimen } } end\
    self.ges_events = {\
        FtTouch = on(\"touch\"),\
        FtTap = on(\"tap\"),\
        FtPan = on(\"pan\"),\
        FtPanRelease = on(\"pan_release\"),\
        FtSwipe = on(\"swipe\"),\
        FtHold = on(\"hold\"),\
        FtHoldPan = on(\"hold_pan\"),\
        FtHoldRelease = on(\"hold_release\"),\
    }\
    if Device:hasKeys() then\
        self.key_events = { FtClose = { { Device.input.group.Back } } }\
    end\
    self.visible = true\
    self.set_index = 1\
    self:makeSets()\
    self:build()\
end\
\
-- Splits the actions into sets; every set but a lone one ends with More.\
function Bar:makeSets()\
    local n = #self.actions\
    local per, need_more = Actions.perSet(self.rows, n)\
    self.cols = need_more and 4 or math.max(1, math.min(4, n))\
    self.sets = {}\
    local i = 1\
    while i <= n do\
        local set = {}\
        for j = i, math.min(n, i + per - 1) do\
            table.insert(set, self.actions[j].button)\
        end\
        i = i + per\
        if need_more then\
            table.insert(set, {\
                text = Actions.MORE,\
                callback = function()\
                    -- After the button has finished its own tap feedback.\
                    UIManager:nextTick(function() self:nextSet() end)\
                end,\
            })\
        end\
        table.insert(self.sets, set)\
    end\
end\
\
-- The rows of buttons for one set, padded with blank cells so every set\
-- has the same layout and More is always in the last cell.\
function Bar:tableRows(set)\
    local multi = #self.sets > 1\
    local count = multi and #set - 1 or #set\
    local list = {}\
    for i = 1, count do list[i] = set[i] end\
    local cells = multi and self.cols * self.rows or math.ceil(count / self.cols) * self.cols\
    local target = multi and cells - 1 or cells\
    while #list < target do\
        table.insert(list, { text = \"\", enabled = false, callback = function() end })\
    end\
    if multi then table.insert(list, set[#set]) end\
    local rows, r = {}, {}\
    for i = 1, #list do\
        table.insert(r, list[i])\
        if #r == self.cols then\
            table.insert(rows, r)\
            r = {}\
        end\
    end\
    if #r > 0 then table.insert(rows, r) end\
    return rows\
end\
\
local function copyButton(b)\
    return {\
        text = b.text,\
        text_func = b.text_func,\
        enabled = b.enabled,\
        enabled_func = b.enabled_func,\
        callback = b.callback,\
        hold_callback = b.hold_callback,\
        allow_hold_when_disabled = b.allow_hold_when_disabled,\
    }\
end\
\
function Bar:makeTable(rows, width, shrink)\
    local buttons = {}\
    for i, row in ipairs(rows) do\
        buttons[i] = {}\
        for j, b in ipairs(row) do buttons[i][j] = copyButton(b) end\
    end\
    return ButtonTable:new{\
        width = width,\
        shrink_unneeded_width = shrink,\
        buttons = buttons,\
        show_parent = self,\
    }\
end\
\
-- Builds the frame for the current set. All sets get the same width (the\
-- widest one needs), so More doesn't make the bar jump around.\
function Bar:build()\
    local border = math.max(1, Screen:scaleBySize(self.border))\
    local margin = Screen:scaleBySize(6)\
    local max_w = Screen:getWidth() - 2 * margin - 2 * border\
    if not self.table_w then\
        local w = 0\
        for _, set in ipairs(self.sets) do\
            local t = self:makeTable(self:tableRows(set), max_w, true)\
            w = math.max(w, t:getSize().w)\
            t:free()\
        end\
        self.table_w = math.min(max_w, w)\
    end\
    if self.frame then self.frame:free() end\
    self.frame = FrameContainer:new{\
        bordersize = border,\
        radius = Screen:scaleBySize(self.radius),\
        padding = 0,\
        margin = 0,\
        background = Blitbuffer.COLOR_WHITE,\
        self:makeTable(self:tableRows(self.sets[self.set_index]), self.table_w, false),\
    }\
    self[1] = self.frame\
    self:place()\
end\
\
function Bar:place()\
    local size = self.frame:getSize()\
    local x, y = self.plugin:barPosition(size.w, size.h)\
    self.bar_rect = Geom:new{ x = x, y = y, w = size.w, h = size.h }\
end\
\
function Bar:paintTo(bb, x, y)\
    if not self.visible then return end\
    self.frame:paintTo(bb, x + self.bar_rect.x, y + self.bar_rect.y)\
end\
\
-- Repaints the page (and this bar on top of it) over the given area.\
function Bar:refresh(region)\
    UIManager:setDirty(self.hl.dialog, \"ui\", region)\
end\
\
function Bar:nextSet()\
    if not self.sets or #self.sets < 2 then return end\
    local old = self.bar_rect\
    self.set_index = self.set_index % #self.sets + 1\
    self:build()\
    self:refresh(old:combine(self.bar_rect))\
end\
\
function Bar:insideBar(pos)\
    return self.visible and self.bar_rect and pos:intersectWith(self.bar_rect)\
end\
\
---------------------------------------------------------------------------\
-- Handle dragging\
---------------------------------------------------------------------------\
\
function Bar:startDrag(grab)\
    self.dragging = grab\
    self.visible = false\
    self:refresh(self.bar_rect)\
    self.plugin:beginHandleDrag(grab.which, grab.touch_y)\
end\
\
function Bar:moveDrag(pos)\
    local g = self.dragging\
    -- Sideways, the handle keeps its offset from the finger; up and down,\
    -- the plugin's line lock works from where the finger really is.\
    self.plugin:moveHandle(Geom:new{ x = pos.x + g.dx, y = pos.y, w = 0, h = 0 })\
end\
\
function Bar:endDrag()\
    self.dragging = nil\
    self.grab = nil\
    self.plugin:endHandleDrag()\
    local old = self.bar_rect\
    -- The selection changed, so which actions apply may have too (Follow\
    -- Link, Hyphenate...): rebuild, starting again from the first set.\
    local actions = Actions.forBar(self.hl)\
    if #actions > 0 then\
        self.actions = actions\
        self.set_index = 1\
        self.table_w = nil\
        self:makeSets()\
        self:build()\
    else\
        self:place()\
    end\
    self.visible = true\
    self:refresh(old:combine(self.bar_rect))\
end\
\
function Bar:onFtTouch(_, ges)\
    self.grab = nil\
    if self:insideBar(ges.pos) then return false end\
    self.grab = self.plugin:handleAt(ges.pos)\
    return true\
end\
\
function Bar:onFtPan(_, ges)\
    if not self.dragging then\
        local grab = self.grab or self.plugin:handleAt(ges.start_pos or ges.pos)\
        if not grab then return true end\
        self:startDrag(grab)\
    end\
    self:moveDrag(ges.pos)\
    return true\
end\
\
function Bar:onFtPanRelease(_, ges)\
    if self.dragging then\
        if ges and ges.pos then self:moveDrag(ges.pos) end\
        self:endDrag()\
    end\
    return true\
end\
\
function Bar:onFtSwipe(_, ges)\
    -- A quick flick on a handle: move it straight to where it ended.\
    local grab = self.plugin:handleAt(ges.pos)\
    if grab and ges.end_pos then\
        self:startDrag(grab)\
        self:moveDrag(ges.end_pos)\
        self:endDrag()\
    end\
    return true\
end\
\
function Bar:onFtHold(_, ges)\
    if self:insideBar(ges.pos) then return true end\
    local grab = self.plugin:handleAt(ges.pos)\
    if grab then\
        self:startDrag(grab)\
        return true\
    end\
    -- Long-press elsewhere: drop this selection and start a new one there.\
    local hl = self.hl\
    hl:onClose()\
    hl:onHold(nil, ges)\
    return true\
end\
\
function Bar:onFtHoldPan(_, ges)\
    if self.dragging then self:moveDrag(ges.pos) end\
    return true\
end\
\
function Bar:onFtHoldRelease(_, ges)\
    if self.dragging then\
        if ges and ges.pos then self:moveDrag(ges.pos) end\
        self:endDrag()\
    end\
    return true\
end\
\
function Bar:onFtTap(_, ges)\
    if self:insideBar(ges.pos) then return true end\
    if self.plugin:handleAt(ges.pos) then return true end\
    -- Like KOReader's popup: a tap elsewhere closes it and drops the selection.\
    self.hl:onClose()\
    return true\
end\
\
function Bar:onFtClose()\
    self.hl:onClose()\
    return true\
end\
\
function Bar:onCloseWidget()\
    local rect = self.bar_rect\
    if self.frame then self.frame:free() end\
    self.plugin:onBarClosed(self)\
    if rect then self:refresh(rect) end\
end\
\
return Bar\
",
    ["orbitui/fingertips/panel"] = "--[[\
FingerTips: geometry and drawing of the lifted panel and the selection handles.\
\
The panel is the page itself, shifted up by the lift and cut to a rounded\
box: the selected part of one line plus a margin of context (a little of the\
text around it). Inside, the selection keeps its shading and the context is\
drawn lighter.\
]]\
\
local Blitbuffer = require(\"ffi/blitbuffer\")\
local Device = require(\"device\")\
local Geom = require(\"ui/geometry\")\
local ffi = require(\"ffi\")\
local logger = require(\"logger\")\
\
local Screen = Device.screen\
\
local Panel = {}\
\
-- Context around the selection, in line heights.\
Panel.CONTEXT_SIDE = 1.0   -- about three letters left and right\
Panel.CONTEXT_V = 0.5      -- half a line above and below\
-- How dark the context stays: 1 = as on the page, 0 = invisible.\
local CONTEXT_INK = 0.33\
\
local ARC_STEPS = 8 -- segments per rounded corner\
\
local function sign(v)\
    if v > 0 then return 1 elseif v < 0 then return -1 end\
    return 0\
end\
\
-- Outline of a polygon with rounded corners, as a flat {x1, y1, x2, y2...}\
-- list. With inset > 0, the outline is pulled inward by that much: corners\
-- keep their arc centres, so convex radii shrink and concave ones grow,\
-- which keeps the band between the two outlines exactly `inset` wide.\
local function roundedPath(corners, radii, inset)\
    local n = #corners\
    local pts = {}\
    for i = 1, n do\
        local c = corners[i]\
        local p = corners[(i - 2) % n + 1]\
        local q = corners[i % n + 1]\
        local d1x, d1y = sign(c.x - p.x), sign(c.y - p.y) -- incoming direction\
        local d2x, d2y = sign(q.x - c.x), sign(q.y - c.y) -- outgoing direction\
        local convex = (d1x * d2y - d1y * d2x) > 0\
        -- sum of the inward normals of both edges (a diagonal, inward)\
        local nx, ny = -d1y - d2y, d1x + d2x\
        local vx, vy = c.x + inset * nx, c.y + inset * ny\
        local r = radii[i]\
        if inset > 0 then\
            r = convex and math.max(0, r - inset) or (r + inset)\
        end\
        if r <= 0 then\
            pts[#pts + 1] = vx\
            pts[#pts + 1] = vy\
        else\
            local s = convex and 1 or -1 -- convex centres inside, concave outside\
            local cx, cy = vx + s * r * nx, vy + s * r * ny\
            local a1 = math.atan2(vy - d1y * r - cy, vx - d1x * r - cx)\
            local a2 = math.atan2(vy + d2y * r - cy, vx + d2x * r - cx)\
            local da = a2 - a1\
            if da > math.pi then da = da - 2 * math.pi\
            elseif da < -math.pi then da = da + 2 * math.pi end\
            for k = 0, ARC_STEPS do\
                local a = a1 + da * k / ARC_STEPS\
                pts[#pts + 1] = cx + r * math.cos(a)\
                pts[#pts + 1] = cy + r * math.sin(a)\
            end\
        end\
    end\
    return pts\
end\
\
-- Sets mask bytes to `value` (default 1) for pixels whose centre is inside\
-- the closed path (even-odd rule). The mask covers the screen area\
-- (ox, oy, w, h).\
local function fillPath(mask, w, h, ox, oy, pts, value)\
    value = value or 1\
    local n = #pts / 2\
    local min_y, max_y = math.huge, -math.huge\
    for i = 2, #pts, 2 do\
        if pts[i] < min_y then min_y = pts[i] end\
        if pts[i] > max_y then max_y = pts[i] end\
    end\
    local row0 = math.max(0, math.floor(min_y - oy))\
    local row1 = math.min(h - 1, math.ceil(max_y - oy))\
    local xs = {}\
    for row = row0, row1 do\
        local y = oy + row + 0.5\
        local cnt = 0\
        for i = 0, n - 1 do\
            local j = (i + 1) % n\
            local y1, y2 = pts[2 * i + 2], pts[2 * j + 2]\
            if (y1 <= y and y2 > y) or (y2 <= y and y1 > y) then\
                local x1, x2 = pts[2 * i + 1], pts[2 * j + 1]\
                cnt = cnt + 1\
                xs[cnt] = x1 + (y - y1) * (x2 - x1) / (y2 - y1)\
            end\
        end\
        for k = 2, cnt do -- insertion sort, cnt is small\
            local v, m = xs[k], k - 1\
            while m >= 1 and xs[m] > v do\
                xs[m + 1] = xs[m]\
                m = m - 1\
            end\
            xs[m + 1] = v\
        end\
        local base = row * w\
        for k = 1, cnt - 1, 2 do\
            local xa = math.max(0, math.ceil(xs[k] - ox - 0.5))\
            local xb = math.min(w - 1, math.floor(xs[k + 1] - ox - 0.5))\
            for x = xa, xb do\
                mask[base + x] = value\
            end\
        end\
    end\
end\
\
-- Box blur of a w x h byte mask, in place (outside the mask counts as 0).\
-- Two passes give a soft, roughly Gaussian edge.\
local function averageLineHeight(lines)\
    local h = 0\
    for i = 1, #lines do h = h + lines[i].h end\
    return h / #lines\
end\
Panel.averageLineHeight = averageLineHeight\
\
-- The two handles: a thin bar along the selection's edge plus a round knob,\
-- above the start and below the end (as on phones).\
function Panel.handleGeometry(lines)\
    local first, last = lines[1], lines[#lines]\
    local line_h = averageLineHeight(lines)\
    local bar_w = math.max(2, Screen:scaleBySize(2))\
    local r = math.max(3, math.floor(line_h * 0.2 + 0.5))\
    local start = {\
        x = first.x, top = first.y, bottom = first.y + first.h,\
        knob_x = first.x, knob_y = first.y - r,\
    }\
    local stop = {\
        x = last.x + last.w, top = last.y, bottom = last.y + last.h,\
        knob_x = last.x + last.w, knob_y = last.y + last.h + r,\
    }\
    local function rect(hd)\
        return Geom:new{\
            x = hd.x - r - 1, y = math.min(hd.top, hd.knob_y - r) - 1,\
            w = 2 * r + 2, h = math.max(hd.bottom, hd.knob_y + r) - math.min(hd.top, hd.knob_y - r) + 2,\
        }\
    end\
    return {\
        start = start, stop = stop, r = r, bar_w = bar_w,\
        region = rect(start):combine(rect(stop)),\
    }\
end\
\
-- Draws the handles into bb, with (dx, dy) added to their positions.\
local function drawHandles(bb, hg, dx, dy)\
    for _, hd in ipairs({ hg.start, hg.stop }) do\
        local x = math.floor(hd.x + dx - hg.bar_w / 2 + 0.5)\
        bb:paintRect(x, math.floor(hd.top + dy), hg.bar_w, math.floor(hd.bottom - hd.top), Blitbuffer.COLOR_BLACK)\
        bb:paintCircle(math.floor(hd.knob_x + dx + 0.5), math.floor(hd.knob_y + dy + 0.5), hg.r, Blitbuffer.COLOR_BLACK)\
    end\
end\
\
--[[\
Works out what to draw. lines: screen boxes of the selected lines, top to\
bottom. opts: lift (line heights), border and radius (screen-scaled units),\
with_handles, and panel_line: the line box\
the panel copies (no panel without one). All the selected lines stay dark in\
the copy.\
Returns nil when there is nothing to draw.\
]]\
function Panel.computeLayout(lines, opts)\
    local screen_w, screen_h = Screen:getWidth(), Screen:getHeight()\
    local layout = { parts = {} }\
    local region\
\
    if opts.with_handles then\
        layout.handles = Panel.handleGeometry(lines)\
        region = layout.handles.region\
        local s, e = layout.handles.start, layout.handles.stop\
        table.insert(layout.parts, string.format(\"h%d,%d,%d,%d,%d,%d\", s.x, s.top, s.bottom, e.x, e.top, e.bottom))\
    end\
\
    if opts.panel_line then\
        local panel = Panel.computePanel(opts.panel_line, opts, screen_w, screen_h, lines)\
        if panel then\
            layout.panel = panel\
            region = region and region:combine(panel.region) or panel.region\
            table.insert(layout.parts, panel.key)\
        end\
    end\
\
    if not region then return nil end\
    layout.region = region:intersect(Geom:new{ x = 0, y = 0, w = screen_w, h = screen_h })\
    layout.key = table.concat(layout.parts, \";\")\
    return layout\
end\
\
-- line: the line box to copy; keep_lines: the selected lines (left dark).\
function Panel.computePanel(line, opts, screen_w, screen_h, keep_lines)\
    local border = math.max(1, Screen:scaleBySize(opts.border))\
    local radius = Screen:scaleBySize(opts.radius)\
\
    local line_h = line.h\
    local lift = math.floor(line_h * opts.lift + 0.5)\
    local ctx_side = math.floor(line_h * Panel.CONTEXT_SIDE + 0.5)\
    local ctx_v = math.floor(line_h * Panel.CONTEXT_V + 0.5)\
\
    -- Above the line; or, at the top of the screen where there's no room,\
    -- below the whole selection with the same gap.\
    local dy = -lift\
    if line.y + dy - ctx_v - border < 0 then\
        local last = keep_lines[#keep_lines]\
        dy = (last.y + last.h - line.y) + (lift - line_h)\
    end\
    dy = math.floor(dy + 0.5)\
\
    -- The line plus context on all four sides, plus the outline.\
    local x0 = math.max(0, line.x - ctx_side - border)\
    local x1 = math.min(screen_w, line.x + line.w + ctx_side + border)\
    local y0 = math.max(0, line.y + dy - ctx_v - border)\
    local y1 = math.min(screen_h, line.y + line.h + dy + ctx_v + border)\
    local corners = { { x = x0, y = y0 }, { x = x1, y = y0 }, { x = x1, y = y1 }, { x = x0, y = y1 } }\
    local r = math.min(radius, (x1 - x0) / 2, (y1 - y0) / 2)\
    local radii = { r, r, r, r }\
    local shapes = { {\
        outer = roundedPath(corners, radii, 0),\
        inner = roundedPath(corners, radii, border),\
        corners = corners,\
    } }\
    local bx0, by0, bx1, by1 = x0, y0, x1, y1\
\
    bx0, by0 = math.max(0, math.floor(bx0)), math.max(0, math.floor(by0))\
    bx1, by1 = math.min(screen_w, math.ceil(bx1)), math.min(screen_h, math.ceil(by1))\
    if bx1 <= bx0 or by1 <= by0 then return nil end\
\
    local parts = { \"p\" .. dy }\
    for i = 1, #shapes do\
        for _, c in ipairs(shapes[i].corners) do\
            parts[#parts + 1] = c.x .. \",\" .. c.y\
        end\
        parts[#parts + 1] = \"|\"\
    end\
    for i = 1, #keep_lines do\
        local l = keep_lines[i]\
        parts[#parts + 1] = string.format(\"%d,%d,%d,%d\", l.x, l.y, l.w, l.h)\
    end\
\
    return {\
        dy = dy,\
        lines = keep_lines, -- the selected parts stay dark in the copy\
        shapes = shapes,\
        region = Geom:new{ x = bx0, y = by0, w = bx1 - bx0, h = by1 - by0 },\
        key = table.concat(parts, \";\"),\
    }\
end\
\
-- Pixel layouts we edit directly: bytes per pixel, colour channels. Grey\
-- e-ink Kobos draw in 8-bit grey, colour ones (and the desktop) in RGB32.\
-- Anything else is handled in 8-bit grey.\
local function pixelFormat(bbtype)\
    if bbtype == Blitbuffer.TYPE_BB8 then return 1, 1 end\
    if bbtype == Blitbuffer.TYPE_BBRGB32 then return 4, 3 end -- R, G, B, alpha\
end\
\
local function newBuffer(w, h, bbtype)\
    local ok, bb = pcall(Blitbuffer.new, w, h, bbtype)\
    if ok then return bb end\
    logger.warn(\"FingerTips: could not allocate a\", w, \"x\", h, \"buffer\")\
end\
\
local LIGHTEN = ffi.new(\"uint8_t[256]\")\
for v = 0, 255 do\
    LIGHTEN[v] = 255 - math.floor((255 - v) * CONTEXT_INK + 0.5)\
end\
\
-- Draws the layout onto bb (the screen-sized page buffer at x, y), after the\
-- page and its highlights are already there.\
function Panel.paint(bb, x, y, layout)\
    x, y = x or 0, y or 0\
    local panel = layout.panel\
    if not panel then\
        if layout.handles then drawHandles(bb, layout.handles, x, y) end\
        return\
    end\
\
    local t0 = os.clock()\
    local reg = panel.region\
    local w, h = reg.w, reg.h\
    local bbtype = bb:getType()\
    local bpp, nch = pixelFormat(bbtype)\
    if not bpp then\
        bbtype = Blitbuffer.TYPE_BB8\
        bpp, nch = pixelFormat(bbtype)\
    end\
    local content = newBuffer(w, h, bbtype)\
    local canvas = newBuffer(w, h, bbtype)\
    if not (content and canvas) then\
        if content then content:free() end\
        if canvas then canvas:free() end\
        if layout.handles then drawHandles(bb, layout.handles, x, y) end\
        return\
    end\
\
    -- 1. The panel's contents: the page shifted by the lift, taken before\
    --    anything else is drawn on top of it.\
    content:fill(Blitbuffer.COLOR_WHITE)\
    local sx0, sy0 = reg.x, reg.y - panel.dy -- where the contents come from\
    local cx0, cy0 = math.max(0, sx0), math.max(0, sy0)\
    local cx1 = math.min(bb:getWidth() - x, sx0 + w)\
    local cy1 = math.min(bb:getHeight() - y, sy0 + h)\
    if cx1 > cx0 and cy1 > cy0 then\
        content:blitFrom(bb, cx0 - sx0, cy0 - sy0, x + cx0, y + cy0, cx1 - cx0, cy1 - cy0)\
    end\
\
    -- 2. Lighten the context: everything but the selected lines.\
    local keep = ffi.new(\"uint8_t[?]\", w * h)\
    for _, l in ipairs(panel.lines) do\
        local kx0 = math.max(0, math.floor(l.x - reg.x))\
        local kx1 = math.min(w, math.ceil(l.x + l.w - reg.x))\
        local ky0 = math.max(0, math.floor(l.y + panel.dy - reg.y))\
        local ky1 = math.min(h, math.ceil(l.y + l.h + panel.dy - reg.y))\
        for row = ky0, ky1 - 1 do\
            local base = row * w\
            for col = kx0, kx1 - 1 do keep[base + col] = 1 end\
        end\
    end\
    do\
        local px = ffi.cast(\"uint8_t*\", content.data)\
        local stride = tonumber(content.stride)\
        for row = 0, h - 1 do\
            local m, base = row * w, row * stride\
            for col = 0, w - 1 do\
                if keep[m + col] == 0 then\
                    local o = base + col * bpp\
                    for k = 0, nch - 1 do px[o + k] = LIGHTEN[px[o + k]] end\
                end\
            end\
        end\
    end\
\
    -- 3. The handles, in the copy too.\
    if layout.handles then\
        drawHandles(content, layout.handles, -reg.x, panel.dy - reg.y)\
    end\
\
    -- 4. What's on the page where the panel goes (kept outside the outline),\
    --    with the page's own handles on it.\
    if layout.handles then drawHandles(bb, layout.handles, x, y) end\
    canvas:blitFrom(bb, 0, 0, x + reg.x, y + reg.y, w, h)\
\
    -- 5. Which pixels are outline and which are inside it.\
    local outer = ffi.new(\"uint8_t[?]\", w * h)\
    local inner = ffi.new(\"uint8_t[?]\", w * h)\
    for _, shape in ipairs(panel.shapes) do\
        fillPath(outer, w, h, reg.x, reg.y, shape.outer)\
        fillPath(inner, w, h, reg.x, reg.y, shape.inner)\
    end\
\
    -- 6. Combine: inside -> contents, outline band -> black, else page.\
    local cstride, tstride = tonumber(canvas.stride), tonumber(content.stride)\
    if bpp == 4 then\
        local cpx = ffi.cast(\"uint32_t*\", canvas.data)\
        local tpx = ffi.cast(\"uint32_t*\", content.data)\
        local black = 0xFF000000 -- opaque black: alpha 0xFF, RGB 0\
        cstride, tstride = cstride / 4, tstride / 4\
        for row = 0, h - 1 do\
            local m, c, t = row * w, row * cstride, row * tstride\
            for col = 0, w - 1 do\
                if inner[m + col] == 1 then\
                    cpx[c + col] = tpx[t + col]\
                elseif outer[m + col] == 1 then\
                    cpx[c + col] = black\
                end\
            end\
        end\
    else\
        local cpx = ffi.cast(\"uint8_t*\", canvas.data)\
        local tpx = ffi.cast(\"uint8_t*\", content.data)\
        for row = 0, h - 1 do\
            local m, c, t = row * w, row * cstride, row * tstride\
            for col = 0, w - 1 do\
                if inner[m + col] == 1 then\
                    cpx[c + col] = tpx[t + col]\
                elseif outer[m + col] == 1 then\
                    cpx[c + col] = 0\
                end\
            end\
        end\
    end\
    bb:blitFrom(canvas, x + reg.x, y + reg.y, 0, 0, w, h)\
    content:free()\
    canvas:free()\
    logger.dbg(string.format(\"FingerTips: painted %d line(s) in %.1f ms\", #panel.lines, (os.clock() - t0) * 1000))\
end\
\
return Panel\
",
    ["infra/sui_compat_check"] = "-- Compatibility checks at plugin startup.\
-- Detects conflicting plugins and patches and verifies CoverBrowser.\
\
local _ = require(\"gettext\")\
\
-- ---------------------------------------------------------------------------\
-- Helpers\
-- ---------------------------------------------------------------------------\
\
local function get_dir_from_loaded(sentinel)\
    local mod = package.loaded[sentinel]\
    if not mod then return nil end\
    local src\
    if type(mod) == \"table\" then\
        for _k, v in pairs(mod) do\
            if type(v) == \"function\" then\
                local info = debug.getinfo(v, \"S\")\
                src = info and info.source\
                break\
            end\
        end\
    elseif type(mod) == \"function\" then\
        local info = debug.getinfo(mod, \"S\")\
        src = info and info.source\
    end\
    if src and src:sub(1, 1) == \"@\" then\
        local dir = src:sub(2):match(\"^(.*)/[^/]+%.lua$\")\
        return dir and (dir .. \"/\")\
    end\
end\
\
local function get_folder_key(dir)\
    if not dir then return nil end\
    return dir:match(\"^.*/([^/]+)%.koplugin/\")\
end\
\
local function plugin_folder_exists(folder_key)\
    local ok_lfs, lfs = pcall(require, \"libs/libkoreader-lfs\")\
    if not ok_lfs then return false end\
\
    local paths = { \"plugins\" }\
    local extra_paths = G_reader_settings and G_reader_settings:readSetting(\"extra_plugin_paths\")\
    if type(extra_paths) == \"string\" then extra_paths = { extra_paths } end\
    if type(extra_paths) == \"table\" then\
        for _i, path in ipairs(extra_paths) do\
            paths[#paths + 1] = path\
        end\
    end\
\
    for _i, path in ipairs(paths) do\
        if type(path) == \"string\" then\
            path = path:gsub(\"/+$\", \"\")\
            if lfs.attributes(path .. \"/\" .. folder_key .. \".koplugin\", \"mode\") == \"directory\" then\
                return true\
            end\
        end\
    end\
    return false\
end\
\
local function is_pt_detected()\
    return package.loaded[\"ptutil\"] ~= nil\
end\
\
-- Plugins that will be auto-disabled (plugins_disabled + restart).\
local AUTO_DISABLE = {\
    {\
        sentinel = \"common/zen_logger\",\
        label = \"ZenOS\",\
        fallback_key = \"zenos\",\
        folder_key = \"zenos\",\
    },\
    {\
        sentinel = \"burrow_util\",\
        label = \"Burrow\",\
        fallback_key = \"burrow\",\
        folder_key = \"burrow\",\
    },\
    {\
        sentinel = \"qui_utils\",\
        label = \"QuickUI\",\
        fallback_key = \"quickui\",\
        folder_key = \"quickui\",\
    },\
    {\
        sentinel = \"readermenuredesign_installer\",\
        label = \"Reader Menu Redesign\",\
        fallback_key = \"zzz-readermenuredesign\",\
        folder_key = \"zzz-readermenuredesign\",\
    },\
}\
\
-- Extra detection for ZenOS when its logger sentinel is not yet loaded.\
local function is_zenos_present()\
    if package.loaded[\"common/zen_logger\"] ~= nil then return true end\
    if package.loaded[\"common/plugin_root\"] ~= nil then return true end\
    if rawget(_G, \"__ZEN_UI_PLUGIN\") ~= nil then return true end\
    return plugin_folder_exists(\"zenos\")\
end\
\
local function schedule_coverbrowser_check()\
    local UIManager = require(\"ui/uimanager\")\
    UIManager:scheduleIn(1.0, function()\
        local ok_cm = pcall(require, \"covermenu\")\
        if ok_cm then return end\
\
        local disabled_list = {}\
        if G_reader_settings then\
            local dl = G_reader_settings:readSetting(\"plugins_disabled\")\
            if type(dl) == \"table\" then disabled_list = dl end\
        end\
        local plugin_available = disabled_list[\"coverbrowser\"] ~= nil\
\
        local function enable()\
            if G_reader_settings then\
                disabled_list[\"coverbrowser\"] = nil\
                G_reader_settings:saveSetting(\"plugins_disabled\", disabled_list)\
                G_reader_settings:flush()\
            end\
            local Event = require(\"ui/event\")\
            require(\"features/dialogs/sui_dialogs\").confirm{\
                text        = _(\"Please restart KOReader for the change to take effect.\"),\
                ok_text     = _(\"Restart now\"),\
                ok_callback = function()\
                    UIManager:broadcastEvent(Event:new(\"Restart\"))\
                end,\
            }\
        end\
\
        require(\"features/dialogs/sui_dialogs\").confirm{\
            text         = _(\"CoverBrowser plugin is not enabled, some features will not work correctly.\"),\
            ok_text      = _(\"Enable\"),\
            cancel_text  = _(\"OK\"),\
            no_ok_button = not plugin_available,\
            ok_callback  = enable,\
        }\
    end)\
end\
\
-- Returns true when startup should stop (manual block or restart required).\
local function apply_compat_check()\
    local logger\
    do\
        local ok, log = pcall(require, \"logger\")\
        logger = ok and log or { dbg = function() end, info = function() end, warn = function() end }\
    end\
\
    if is_pt_detected() then\
        logger.warn(\"simpleui: incompatible plugin detected (manual block)\")\
        local UIManager = require(\"ui/uimanager\")\
        UIManager:scheduleIn(0.5, function()\
            local InfoMessage = require(\"ui/widget/infomessage\")\
            UIManager:show(InfoMessage:new{\
                text = _(\"Project: Title is not compatible with Simple UI.\")\
                    .. \"\\n\\n\" .. _(\"Please delete the Project: Title plugin from your plugins folder and restart KOReader.\"),\
                show_icon = false,\
            })\
        end)\
        return true\
    end\
\
    if not G_reader_settings then\
        schedule_coverbrowser_check()\
        return false\
    end\
\
    local disabled_list = G_reader_settings:readSetting(\"plugins_disabled\")\
    if type(disabled_list) ~= \"table\" then disabled_list = {} end\
\
    local needs_restart = false\
    local disabled_labels = {}\
\
    -- ZenOS: folder or known runtime markers, even if sentinel not loaded yet.\
    if is_zenos_present() and disabled_list[\"zenos\"] == nil then\
        disabled_list[\"zenos\"] = true\
        disabled_labels[#disabled_labels + 1] = \"ZenOS\"\
        needs_restart = true\
    elseif disabled_list[\"zenos\"] ~= nil and is_zenos_present()\
            and package.loaded[\"common/zen_logger\"] ~= nil then\
        disabled_labels[#disabled_labels + 1] = \"ZenOS\"\
        needs_restart = true\
    end\
\
    for _i, entry in ipairs(AUTO_DISABLE) do\
        if entry.folder_key == \"zenos\" then\
            -- handled above\
        else\
            local sentinel_loaded = package.loaded[entry.sentinel] ~= nil\
            local folder_installed = entry.folder_key and plugin_folder_exists(entry.folder_key)\
            local folder_enabled = folder_installed and disabled_list[entry.folder_key] == nil\
            if sentinel_loaded or folder_enabled then\
                local dir = get_dir_from_loaded(entry.sentinel)\
                local folder_key = folder_enabled and entry.folder_key or get_folder_key(dir)\
                if entry.expected_folder_key and folder_key and folder_key ~= entry.expected_folder_key then\
                    -- skip false positive from a different plugin\
                else\
                    folder_key = folder_key or entry.folder_key or entry.fallback_key\
                    if disabled_list[folder_key] ~= nil and sentinel_loaded then\
                        disabled_labels[#disabled_labels + 1] = entry.label\
                        needs_restart = true\
                    elseif disabled_list[folder_key] == nil then\
                        disabled_list[folder_key] = true\
                        disabled_labels[#disabled_labels + 1] = entry.label\
                        needs_restart = true\
                    end\
                end\
            end\
        end\
    end\
\
    if needs_restart then\
        G_reader_settings:saveSetting(\"plugins_disabled\", disabled_list)\
        G_reader_settings:flush()\
        local UIManager = require(\"ui/uimanager\")\
        UIManager:scheduleIn(0.5, function()\
            local ConfirmBox = require(\"ui/widget/confirmbox\")\
            local Event = require(\"ui/event\")\
            UIManager:show(ConfirmBox:new{\
                text = _(\"Incompatible items have been disabled:\")\
                    .. \"\\n\" .. table.concat(disabled_labels, \"\\n\"),\
                dismissable = false,\
                no_ok_button = true,\
                cancel_text = _(\"Restart now\"),\
                cancel_callback = function()\
                    UIManager:broadcastEvent(Event:new(\"Restart\"))\
                end,\
            })\
        end)\
        return true\
    end\
\
    -- User patches that clash with Simple UI: offer to disable them and stop.\
    local ok_pc, PatchCompat = pcall(require, \"features/sui_patch_compat\")\
    if ok_pc and PatchCompat then\
        local ok_run, shown = pcall(PatchCompat.check)\
        if ok_run and shown then return true end\
        if not ok_run then\
            logger.warn(\"simpleui: patch compatibility check failed:\", tostring(shown))\
        end\
    end\
\
    schedule_coverbrowser_check()\
    return false\
end\
\
return apply_compat_check\
",
    ["infra/sui_updater"] = "-- sui_updater.lua — Simple UI OTA Updater\
--\
-- Two modes of operation:\
--   1. Silent automatic check on startup (24 h throttle via G_reader_settings).\
--      If an update is available, a banner appears at the top of the About menu.\
--   2. Manual check triggered by the user (\"Check for Updates\" menu item).\
--      Always hits the network, ignores the throttle.\
--\
-- Technical stack:\
--   • socketutil with timeouts (avoids hangs on unstable networks)\
--   • ltn12.sink.file for downloads (streams directly to disk, no ZIP in RAM)\
--   • Native KOReader json.decode; regex fallback if unavailable\
--   • Release notes shown before confirming install\
--   • Trapper:dismissableRunInSubprocess (non-blocking UI, cancellable)\
--   • State persisted in G_reader_settings (survives between sessions;\
--     the \"update available\" banner appears immediately on next startup)\
\
local UIManager   = require(\"ui/uimanager\")\
local logger      = require(\"logger\")\
local util        = require(\"util\")\
local _           = require(\"infra/sui_i18n\").translate\
local UI          = require(\"infra/sui_core\")\
local Text        = require(\"infra/sui_text\")\
\
local function Dialogs() return require(\"features/dialogs/sui_dialogs\") end\
\
-- ---------------------------------------------------------------------------\
-- Configuration\
-- ---------------------------------------------------------------------------\
local GITHUB_OWNER = \"komadorirobin\"\
local GITHUB_REPO  = \"simpleui.koplugin\"\
local ASSET_NAME   = \"simpleui.koplugin.zip\"\
local API_REPO_BASE = string.format(\
    \"https://api.github.com/repos/%s/%s\", GITHUB_OWNER, GITHUB_REPO)\
\
local AUTO_CHECK_INTERVAL = 24 * 3600  -- seconds between automatic checks\
\
-- G_reader_settings keys — prefixed with \"sui_upd_\" to avoid collisions.\
local GS_LAST_CHECK = \"sui_upd_last_check\"  -- number (timestamp)\
local GS_HAS_UPDATE = \"sui_upd_has_update\"  -- boolean\
local GS_LATEST_VER = \"sui_upd_latest_ver\"  -- string without \"v\"\
local GS_DL_URL     = \"sui_upd_dl_url\"      -- string URL\
local GS_BRANCH     = \"sui_upd_branch\"      -- selected channel; empty = release\
local GS_SOURCE     = \"sui_upd_install_source\" -- release | branch:<name>\
local GS_COMMIT     = \"sui_upd_install_commit\"\
\
local _API_URL = API_REPO_BASE .. \"/releases/latest\"\
\
-- ---------------------------------------------------------------------------\
-- Internals\
-- ---------------------------------------------------------------------------\
\
local M = {}\
\
-- In-memory cache for the current session.\
-- Initialised lazily by _load_persisted_state().\
local _state_loaded = false\
local _has_update   = false\
local _latest_ver   = nil  -- string without \"v\", or nil\
local _dl_url       = nil  -- URL for the asset ZIP, or nil\
\
-- Plugin directory — resolved once at module load time.\
local _plugin_dir = require(\"infra/sui_paths\").getPluginDirNoSlash()\
if not _plugin_dir or _plugin_dir == \"\" or _plugin_dir == \".\" then\
    _plugin_dir = \"/mnt/us/extensions/simpleui.koplugin\"\
end\
\
-- ---------------------------------------------------------------------------\
-- Helpers: version\
-- ---------------------------------------------------------------------------\
\
local function _currentVersion()\
    -- Use dofile with the absolute path to guarantee we read *this* plugin's\
    -- _meta.lua, not a stale cached entry from another plugin (require caches\
    -- by module name, so require(\"_meta\") may return the wrong table).\
    local ok, meta = pcall(dofile, _plugin_dir .. \"/_meta.lua\")\
    if ok and type(meta) == \"table\" and meta.name == \"simpleui\" and meta.version then return meta.version end\
    local rok, rmeta = pcall(require, \"_meta\")\
    if rok and type(rmeta) == \"table\" and rmeta.name == \"simpleui\" and rmeta.version then return rmeta.version end\
    return \"0.0.0\"\
end\
\
-- Returns true if version `a` is strictly greater than `b`.\
-- Supports \"v1.2.3\", \"1.2.3\", \"1.2.3-beta1\" (suffixes are ignored).\
local function _versionGt(a, b)\
    local function parts(v)\
        v = (v or \"\"):match(\"^v?(.-)[-+]\") or (v or \"\"):match(\"^v?(.+)$\") or \"\"\
        local t = {}\
        for n in (v .. \".\"):gmatch(\"(%d+)%.\") do t[#t + 1] = tonumber(n) or 0 end\
        while #t < 3 do t[#t + 1] = 0 end\
        return t\
    end\
    local pa, pb = parts(a), parts(b)\
    for i = 1, 3 do\
        if pa[i] > pb[i] then return true end\
        if pa[i] < pb[i] then return false end\
    end\
    return false\
end\
\
local function _isValidAssetUrl(url)\
    return type(url) == \"string\"\
        and url:find(\"/releases/download/\", 1, true) ~= nil\
end\
\
local function _encodeQueryValue(value)\
    return tostring(value or \"\"):gsub(\"[^%w%-_.~]\", function(c)\
        return string.format(\"%%%02X\", c:byte())\
    end)\
end\
\
local function _branchArchiveUrl(branch)\
    local encoded = tostring(branch or \"\"):gsub(\"[^%w%-_/.~]\", function(c)\
        return string.format(\"%%%02X\", c:byte())\
    end)\
    return API_REPO_BASE .. \"/zipball/\" .. encoded\
end\
\
local function _shortSha(sha)\
    return tostring(sha or \"\"):sub(1, 8)\
end\
\
-- ---------------------------------------------------------------------------\
-- G_reader_settings accessor — guarded for use outside KOReader (e.g. tests)\
-- ---------------------------------------------------------------------------\
\
local function _gs()\
    local ok, gs = pcall(function() return G_reader_settings end)\
    return ok and gs or nil\
end\
\
-- ---------------------------------------------------------------------------\
-- Persistence\
-- ---------------------------------------------------------------------------\
\
local function _load_persisted_state()\
    if _state_loaded then return end\
    _state_loaded = true\
\
    local gs = _gs()\
    if not gs then return end\
\
    _has_update = gs:readSetting(GS_HAS_UPDATE) == true\
    local ver   = gs:readSetting(GS_LATEST_VER)\
    _latest_ver = (type(ver) == \"string\" and ver ~= \"\") and ver or nil\
    local url   = gs:readSetting(GS_DL_URL)\
    _dl_url     = _isValidAssetUrl(url) and url or nil\
\
    -- Discard stale state (e.g. update already installed).\
    if _has_update and not _versionGt(_latest_ver or \"\", _currentVersion()) then\
        _has_update = false\
        _latest_ver = nil\
        _dl_url     = nil\
        gs:saveSetting(GS_HAS_UPDATE, false)\
        gs:saveSetting(GS_LATEST_VER, \"\")\
        gs:saveSetting(GS_DL_URL,     \"\")\
        pcall(gs.flush, gs)\
    end\
end\
\
local function _persist_state(now)\
    local gs = _gs()\
    if not gs then return end\
    if now then gs:saveSetting(GS_LAST_CHECK, now) end\
    gs:saveSetting(GS_HAS_UPDATE, _has_update)\
    gs:saveSetting(GS_LATEST_VER, _latest_ver or \"\")\
    gs:saveSetting(GS_DL_URL,     _dl_url     or \"\")\
    pcall(gs.flush, gs)\
end\
\
local function _clear_update_state()\
    _has_update = false\
    _latest_ver = nil\
    _dl_url     = nil\
    local gs = _gs()\
    if not gs then return end\
    gs:saveSetting(GS_HAS_UPDATE, false)\
    gs:saveSetting(GS_LATEST_VER, \"\")\
    gs:saveSetting(GS_DL_URL,     \"\")\
    pcall(gs.flush, gs)\
end\
\
-- ---------------------------------------------------------------------------\
-- HTTP\
-- ---------------------------------------------------------------------------\
\
local function _httpGet(url)\
    local ok_su, socketutil = pcall(require, \"socketutil\")\
    local http   = require(\"socket/http\")\
    local ltn12  = require(\"ltn12\")\
    local socket = require(\"socket\")\
\
    if ok_su then\
        socketutil:set_timeout(\
            socketutil.LARGE_BLOCK_TIMEOUT,\
            socketutil.LARGE_TOTAL_TIMEOUT\
        )\
    end\
\
    local chunks = {}\
    local code, headers, status = socket.skip(1, http.request({\
        url     = url,\
        method  = \"GET\",\
        headers = {\
            [\"User-Agent\"] = \"KOReader-SimpleUI-Updater/2.0\",\
            [\"Accept\"]     = \"application/vnd.github.v3+json\",\
        },\
        sink     = ltn12.sink.table(chunks),\
        redirect = true,\
    }))\
\
    if ok_su then socketutil:reset_timeout() end\
\
    if ok_su and (\
        code == socketutil.TIMEOUT_CODE or\
        code == socketutil.SSL_HANDSHAKE_CODE or\
        code == socketutil.SINK_TIMEOUT_CODE\
    ) then\
        return nil, \"timeout (\" .. tostring(code) .. \")\"\
    end\
\
    if headers == nil then\
        return nil, \"network error (\" .. tostring(code or status) .. \")\"\
    end\
\
    if code == 200 then return table.concat(chunks) end\
    return nil, string.format(\"HTTP %s\", tostring(code))\
end\
\
local function _httpGetToFile(url, dest_path)\
    local ok_su, socketutil = pcall(require, \"socketutil\")\
    local http   = require(\"socket/http\")\
    local ltn12  = require(\"ltn12\")\
    local socket = require(\"socket\")\
\
    local fh, err_open = io.open(dest_path, \"wb\")\
    if not fh then return nil, \"cannot create file: \" .. tostring(err_open) end\
\
    if ok_su then\
        socketutil:set_timeout(\
            socketutil.FILE_BLOCK_TIMEOUT,\
            socketutil.FILE_TOTAL_TIMEOUT\
        )\
    end\
\
    local code, headers, status = socket.skip(1, http.request({\
        url     = url,\
        method  = \"GET\",\
        headers = { [\"User-Agent\"] = \"KOReader-SimpleUI-Updater/2.0\" },\
        sink    = ltn12.sink.file(fh),   -- stream directly to disk\
        redirect = true,\
    }))\
\
    if ok_su then socketutil:reset_timeout() end\
    -- ltn12.sink.file closes fh automatically.\
\
    if ok_su and (\
        code == socketutil.TIMEOUT_CODE or\
        code == socketutil.SSL_HANDSHAKE_CODE or\
        code == socketutil.SINK_TIMEOUT_CODE\
    ) then\
        pcall(os.remove, dest_path)\
        return nil, \"timeout (\" .. tostring(code) .. \")\"\
    end\
\
    if headers == nil then\
        pcall(os.remove, dest_path)\
        return nil, \"network error (\" .. tostring(code or status) .. \")\"\
    end\
\
    if code == 200 then return true end\
    pcall(os.remove, dest_path)\
    return nil, string.format(\"HTTP %s\", tostring(code))\
end\
\
-- ---------------------------------------------------------------------------\
-- GitHub API response parsing\
-- ---------------------------------------------------------------------------\
\
local function _parseRelease(body)\
    local ok_j, json = pcall(require, \"json\")\
\
    if not ok_j then\
        -- Regex fallback for KOReader builds that lack the json module.\
        logger.warn(\"simpleui updater: json module unavailable, using regex fallback\")\
        local function jsonStr(key)\
            return body:match('\"' .. key .. '\"%s*:%s*\"([^\"]*)\"')\
        end\
        local tag = jsonStr(\"tag_name\")\
        if not tag then return nil, \"could not parse tag_name\" end\
        local asset_pat = '\"browser_download_url\"%s*:%s*\"([^\"]*'\
            .. ASSET_NAME:gsub(\"%.\", \"%%.\") .. '[^\"]*)\"'\
        local download_url = body:match(asset_pat)\
        local notes = body:match('\"body\"%s*:%s*\"(.-)\"%s*[,}]')\
        if notes then\
            notes = notes:gsub(\"\\\\n\", \"\\n\"):gsub(\"\\\\r\", \"\")\
                        :gsub('\\\\\"', '\"'):gsub(\"\\\\\\\\\", \"\\\\\")\
        end\
        return {\
            version      = tag:match(\"v?(.*)\"),\
            download_url = download_url,\
            notes        = (notes and notes ~= \"\") and notes or nil,\
        }\
    end\
\
    local ok_d, data = pcall(json.decode, body)\
    if not ok_d or type(data) ~= \"table\" then\
        return nil, \"JSON parse error: \" .. tostring(data)\
    end\
\
    local tag = data.tag_name\
    if not tag then return nil, \"tag_name missing from API response\" end\
\
    local download_url\
    for _, asset in ipairs(data.assets or {}) do\
        if asset.name == ASSET_NAME then\
            download_url = asset.browser_download_url\
            break\
        end\
    end\
\
    local notes = data.body\
    if notes and notes ~= \"\" then\
        notes = notes:gsub(\"#+%s*\", \"\")           -- headings markdown\
        notes = notes:gsub(\"%*%*(.-)%*%*\", \"%1\")  -- bold **\
        notes = notes:gsub(\"`(.-)`\", \"%1\")         -- code inline\
        notes = notes:gsub(\"\\r\\n\", \"\\n\"):gsub(\"\\r\", \"\\n\")\
        notes = Text.truncate(notes, 600)\
        notes = util.trim(notes)\
    end\
\
    return {\
        version      = tag:match(\"v?(.*)\"),\
        download_url = download_url,\
        notes        = (notes and notes ~= \"\") and notes or nil,\
        html_url     = data.html_url,\
    }\
end\
\
local function _parseBranchHead(body)\
    local ok_j, json = pcall(require, \"json\")\
    if ok_j then\
        local ok_d, commits = pcall(json.decode, body)\
        if ok_d and type(commits) == \"table\" and type(commits[1]) == \"table\"\
                and type(commits[1].sha) == \"string\" and commits[1].sha ~= \"\" then\
            return commits[1].sha\
        end\
    end\
    local sha = body:match('\"sha\"%s*:%s*\"([0-9a-fA-F]+)\"')\
    if sha and sha ~= \"\" then return sha end\
    return nil, \"could not parse branch head\"\
end\
\
-- ---------------------------------------------------------------------------\
-- Unzip\
-- ---------------------------------------------------------------------------\
\
-- Extract the update ZIP using KOReader's built-in archive reader\
-- (ffi/archiver, exposed via Device:unpackArchive). This is the same\
-- mechanism KOReader itself uses for its own OTA self-update, so it works\
-- on every platform without shelling out to a system \"unzip\" binary.\
-- Some platforms (notably Android, where KOReader runs sandboxed with no\
-- command-line tools available to the process) have no \"unzip\" executable\
-- at all, which made the previous os.execute()-based approach fail with\
-- exit 127 (\"command not found\").\
--\
-- with_stripped_root = false: the release ZIP already contains a top-level\
-- \"simpleui.koplugin/\" directory, and dest_dir is the *parent* of the\
-- plugin directory, so the archive's own root must be preserved.\
local function _unzip(zip_path, dest_dir)\
    local ok_dev, Device = pcall(require, \"device\")\
    if ok_dev and Device and Device.unpackArchive then\
        local ok, err = Device:unpackArchive(zip_path, dest_dir, false)\
        if not ok then\
            return nil, tostring(err or \"unpackArchive failed\")\
        end\
        return true\
    end\
\
    -- Fallback for the unlikely case that ffi/archiver is unavailable\
    -- (e.g. an unusual custom build). Only useful on desktop-like targets\
    -- where a system \"unzip\" is actually on PATH.\
    logger.warn(\"simpleui updater: ffi/archiver unavailable, falling back to system unzip\")\
    local ret = os.execute(string.format(\"unzip -o -q %q -d %q\", zip_path, dest_dir))\
    if ret ~= 0 and ret ~= true then\
        return nil, \"unzip failed (exit \" .. tostring(ret) .. \")\"\
    end\
    return true\
end\
\
local function _unzipStripRoot(zip_path, dest_dir)\
    local ok_req, Archiver = pcall(require, \"ffi/archiver\")\
    if not (ok_req and Archiver and Archiver.Reader) then\
        return nil, \"archive extractor unavailable\"\
    end\
    local arc = Archiver.Reader:new()\
    if not arc:open(zip_path) then\
        local err = arc.err\
        arc:close()\
        return nil, err or \"could not open archive\"\
    end\
    local extract_err\
    for entry in arc:iterate() do\
        local rel = entry.path and entry.path:match(\"^[^/]+/(.+)$\")\
        if rel and rel ~= \"\" and not arc:extractToPath(entry.path, dest_dir .. \"/\" .. rel) then\
            extract_err = arc.err or \"extract failed\"\
            break\
        end\
    end\
    arc:close()\
    if extract_err then return nil, extract_err end\
    return true\
end\
\
-- ---------------------------------------------------------------------------\
-- Temporary path for the update ZIP\
-- ---------------------------------------------------------------------------\
\
local function _tmpZipPath()\
    -- Candidate paths in preference order.\
    -- Each is probed with \"wb\" (binary write) — the same mode used by the\
    -- actual download — so a successful probe guarantees the download will\
    -- also succeed.  Using \"w\" (text) for the probe masked failures on some\
    -- devices where text-mode open succeeded but binary-mode open did not.\
    local candidates = {}\
\
    local ok, DS = pcall(require, \"datastorage\")\
    if ok and DS then\
        local dir = DS:getSettingsDir()\
        if dir then candidates[#candidates + 1] = dir .. \"/simpleui_update.zip\" end\
    end\
    candidates[#candidates + 1] = \"/tmp/simpleui_update.zip\"\
    candidates[#candidates + 1] = _plugin_dir .. \"/simpleui_update.zip\"\
\
    for _, path in ipairs(candidates) do\
        local fh = io.open(path, \"wb\")\
        if fh then fh:close(); os.remove(path); return path end\
    end\
\
    -- Last-resort fallback: return the plugin dir path even without a\
    -- successful probe (the download will fail with a clear error if it\
    -- really is not writable, rather than returning nil here).\
    return _plugin_dir .. \"/simpleui_update.zip\"\
end\
\
-- ---------------------------------------------------------------------------\
-- UI helpers\
-- ---------------------------------------------------------------------------\
\
local function _closeWidget(w)\
    if w then UIManager:close(w) end\
end\
\
-- ---------------------------------------------------------------------------\
-- Pure fetch — intended to run inside a subprocess\
-- ---------------------------------------------------------------------------\
\
local function _doFetch()\
    local body, err = _httpGet(_API_URL)\
    if not body then return { error = err } end\
    local release, parse_err = _parseRelease(body)\
    if not release then return { error = \"parse error: \" .. tostring(parse_err) } end\
    return release\
end\
\
local function _doBranchFetch(branch)\
    local url = API_REPO_BASE .. \"/commits?sha=\"\
        .. _encodeQueryValue(branch) .. \"&per_page=1\"\
    local body, err = _httpGet(url)\
    if not body then return { error = err } end\
    local sha, parse_err = _parseBranchHead(body)\
    if not sha then return { error = \"parse error: \" .. tostring(parse_err) } end\
    return { branch = branch, sha = sha }\
end\
\
-- ---------------------------------------------------------------------------\
-- Download and installation\
-- ---------------------------------------------------------------------------\
\
local function _applyUpdate(download_url, new_version, opts)\
    opts = opts or {}\
    local tmp_zip    = _tmpZipPath()\
    local parent_dir = _plugin_dir:match(\"^(.+)/[^/]+$\") or _plugin_dir\
\
    local progress_msg = UI.Notify.toast(string.format(_(\"Downloading Simple UI %s…\"), new_version), 120)\
\
    local ok_tr, Trapper = pcall(require, \"ui/trapper\")\
\
    local function doDownloadAndInstall()\
        local dl_ok, dl_err = _httpGetToFile(download_url, tmp_zip)\
        if not dl_ok then\
            return { success = false, stage = \"download\", err = dl_err }\
        end\
        local uz_ok, uz_err\
        if opts.strip_root then\
            uz_ok, uz_err = _unzipStripRoot(tmp_zip, _plugin_dir)\
        else\
            uz_ok, uz_err = _unzip(tmp_zip, parent_dir)\
        end\
        os.remove(tmp_zip)\
        if not uz_ok then\
            return { success = false, stage = \"unzip\", err = uz_err }\
        end\
        return { success = true }\
    end\
\
    local function handleInstallResult(result)\
        _closeWidget(progress_msg)\
        if not result or not result.success then\
            local stage = result and result.stage or \"unknown\"\
            local err   = result and result.err   or \"unknown error\"\
            logger.err(\"simpleui updater: failed in\", stage, \"-\", err)\
            UI.Notify.toast(stage == \"download\"\
                    and (_(\"Download error: \") .. tostring(err))\
                    or  (_(\"Extraction error: \") .. tostring(err)), 4)\
            return\
        end\
        _clear_update_state()\
        if opts.on_success then pcall(opts.on_success) end\
        Dialogs().askRestart{\
            text = string.format(\
                _(\"Simple UI %s installed.\\n\\nRestart KOReader to apply the update?\"),\
                new_version\
            ),\
        }\
    end\
\
    if ok_tr and Trapper and Trapper.dismissableRunInSubprocess then\
        local completed, result = Trapper:dismissableRunInSubprocess(\
            doDownloadAndInstall,\
            progress_msg,\
            function(res) handleInstallResult(res) end\
        )\
        if completed and result then\
            UIManager:scheduleIn(0.2, function() handleInstallResult(result) end)\
        elseif completed == false then\
            _closeWidget(progress_msg)\
            pcall(os.remove, tmp_zip)\
            UI.Notify.toast(_(\"Update cancelled.\"), 4)\
        end\
    else\
        -- Synchronous fallback (no Trapper): avoids blocking the UI via scheduleIn.\
        UIManager:scheduleIn(0.3, function()\
            handleInstallResult(doDownloadAndInstall())\
        end)\
    end\
end\
\
-- ---------------------------------------------------------------------------\
-- Confirmation dialog with release notes\
-- ---------------------------------------------------------------------------\
\
local function _showUpdateDialog(release, current, force_switch)\
    local latest       = release.version\
    local download_url = release.download_url\
    local notes        = release.notes\
\
    if not force_switch and not _versionGt(latest, current) then\
        logger.info(\"simpleui updater: already up to date (\" .. current .. \")\")\
        UI.Notify.toast(string.format(_(\"Simple UI is up to date (%s).\"), current), 4)\
        return\
    end\
\
    logger.info(\"simpleui updater: new version available:\", latest)\
\
    local header = force_switch\
        and string.format(_(\"Switch to stable Simple UI %s?\\nYou have %s.\"), latest, current)\
        or string.format(_(\"Simple UI %s is available!\\nYou have %s.\"), latest, current)\
    local notes_block = notes and (\"\\n\\n\" .. _(\"What's new:\") .. \"\\n\" .. notes) or \"\"\
\
    if not download_url then\
        Dialogs().confirm{\
            text        = header .. notes_block\
                       .. \"\\n\\n\" .. _(\"No download file found.\\n\\nOpen the releases page?\"),\
            ok_text     = _(\"Open in browser\"),\
            cancel_text = _(\"Cancel\"),\
            ok_callback = function()\
                local Device = require(\"device\")\
                if Device:canOpenLink() then\
                    Device:openLink(string.format(\
                        \"https://github.com/%s/%s/releases/latest\",\
                        GITHUB_OWNER, GITHUB_REPO\
                    ))\
                end\
            end,\
        }\
        return\
    end\
\
    Dialogs().confirm{\
        text        = header .. notes_block .. \"\\n\\n\" .. _(\"Download and install now?\"),\
        ok_text     = _(\"Download and install\"),\
        cancel_text = _(\"Cancel\"),\
        ok_callback = function()\
            _applyUpdate(download_url, latest, {\
                on_success = function()\
                    local gs = _gs()\
                    if not gs then return end\
                    gs:saveSetting(GS_SOURCE, \"release\")\
                    gs:saveSetting(GS_COMMIT, \"\")\
                    pcall(gs.flush, gs)\
                end,\
            })\
        end,\
    }\
end\
\
-- ---------------------------------------------------------------------------\
-- Network check with result persistence\
-- ---------------------------------------------------------------------------\
\
local function _doNetworkCheck()\
    local release = _doFetch()\
    if release.error then\
        logger.warn(\"simpleui updater: check error:\", release.error)\
        return false, release.error\
    end\
\
    local current = _currentVersion()\
    _latest_ver   = release.version\
    _dl_url       = _isValidAssetUrl(release.download_url) and release.download_url or nil\
    _has_update   = _versionGt(_latest_ver, current)\
\
    logger.info(string.format(\
        \"simpleui updater: current=%s latest=%s has_update=%s\",\
        current, _latest_ver or \"?\", tostring(_has_update)\
    ))\
\
    _persist_state(os.time())\
    return true, release\
end\
\
-- ---------------------------------------------------------------------------\
-- Public API\
-- ---------------------------------------------------------------------------\
\
--- Returns true when a newer version has been detected.\
--- Uses the in-memory cache (no I/O after the first call).\
function M.hasUpdate()\
    _load_persisted_state()\
    return _has_update\
end\
\
--- Returns the latest detected version string (without \"v\" prefix), or nil.\
function M.latestVersion()\
    _load_persisted_state()\
    return _latest_ver\
end\
\
--- Selected update channel. An empty string means stable GitHub releases.\
function M.selectedBranch()\
    local gs = _gs()\
    local branch = gs and gs:readSetting(GS_BRANCH) or \"\"\
    return type(branch) == \"string\" and branch or \"\"\
end\
\
--- Select an update channel without installing anything.\
function M.setSelectedBranch(branch)\
    branch = tostring(branch or \"\"):match(\"^%s*(.-)%s*$\") or \"\"\
    local gs = _gs()\
    if gs then\
        gs:saveSetting(GS_BRANCH, branch)\
        pcall(gs.flush, gs)\
    end\
    return branch\
end\
\
function M.installedSource()\
    local gs = _gs()\
    local source = gs and gs:readSetting(GS_SOURCE) or nil\
    return type(source) == \"string\" and source ~= \"\" and source or \"release\"\
end\
\
function M.installedCommit()\
    local gs = _gs()\
    local commit = gs and gs:readSetting(GS_COMMIT) or nil\
    return type(commit) == \"string\" and commit or \"\"\
end\
\
--- Silent automatic check — called once on plugin startup.\
---\
--- • Always loads persisted state so hasUpdate() is correct immediately.\
--- • Only hits the network if more than AUTO_CHECK_INTERVAL seconds have\
---   elapsed since the last successful check.\
--- • Never shows any UI — the result is written to G_reader_settings;\
---   the banner is built by build_update_banner_item() when the menu opens.\
function M.scheduleAutoCheck()\
    -- Opt-in only: skip silently if the user has not enabled auto-check.\
    -- SUISettings:isTrue() returns false for missing keys → disabled by default.\
    local ok_s, SUISettings = pcall(require, \"infra/sui_store\")\
    if not ok_s or not SUISettings then return end\
    if not SUISettings:isTrue(\"simpleui_updater_auto_check\") then\
        logger.dbg(\"simpleui updater: auto-check disabled — skipping\")\
        return\
    end\
\
    -- Branch channels are deliberately manual. This avoids an experimental\
    -- build being replaced in the background while KOReader is starting.\
    if M.selectedBranch() ~= \"\" then\
        logger.dbg(\"simpleui updater: branch channel selected - manual checks only\")\
        return\
    end\
\
    _load_persisted_state()\
\
    local gs   = _gs()\
    local now  = os.time()\
    local last = (gs and gs:readSetting(GS_LAST_CHECK)) or 0\
    if type(last) ~= \"number\" then last = 0 end\
\
    if (now - last) < AUTO_CHECK_INTERVAL then\
        logger.dbg(\"simpleui updater: auto-check within throttle — skip\")\
        return\
    end\
\
    -- Network call: runs 5 s after startup to avoid delaying the first paint.\
    -- IMPORTANT: for the silent auto-check we must NEVER prompt the user to\
    -- connect Wi-Fi. runWhenOnline calls beforeWifiAction when offline, which\
    -- shows a dialog or turns Wi-Fi on automatically — both are unacceptable\
    -- for a background check the user did not explicitly trigger.\
    -- Instead: only proceed if the network is already online. If it is not,\
    -- skip silently. The 24-hour throttle ensures we try again on the next\
    -- startup where the device happens to be connected already.\
    UIManager:scheduleIn(5, function()\
        local ok_nm, NetworkMgr = pcall(require, \"ui/network/manager\")\
        local already_online = ok_nm and NetworkMgr\
            and (NetworkMgr.isOnline and NetworkMgr:isOnline()\
                or (NetworkMgr.isConnected and NetworkMgr:isConnected()))\
        if not already_online then\
            logger.dbg(\"simpleui updater: auto-check skip — network not online\")\
            return\
        end\
        _doNetworkCheck()\
    end)\
\
end\
\
--- Manual check — triggered by the \"Check for Updates\" menu item.\
--- Always hits the network (ignores throttle) and shows UI with the result.\
function M.checkForUpdates()\
    local current = _currentVersion()\
    local branch = M.selectedBranch()\
    local ok_nm, NetworkMgr = pcall(require, \"ui/network/manager\")\
    if ok_nm and NetworkMgr and NetworkMgr.runWhenOnline then\
        NetworkMgr:runWhenOnline(function()\
            if branch ~= \"\" then\
                M._doManualBranchCheck(branch, current)\
            else\
                M._doManualCheck(current)\
            end\
        end)\
        return\
    end\
    if branch ~= \"\" then\
        M._doManualBranchCheck(branch, current)\
    else\
        M._doManualCheck(current)\
    end\
end\
\
--- Internal logic for the manual check (kept separate to keep checkForUpdates\
--- clean and to allow direct calls in tests).\
function M._doManualCheck(current)\
    local ok_tr, Trapper = pcall(require, \"ui/trapper\")\
    local checking_msg   = UI.Notify.toast(_(\"Checking for updates…\"), 15)\
\
    local function handleCheckResult(release)\
        _closeWidget(checking_msg)\
        if not release then\
            UI.Notify.toast(_(\"Error checking for updates.\"), 4)\
            return\
        end\
        if release.error then\
            logger.err(\"simpleui updater:\", release.error)\
            UI.Notify.toast(_(\"Error checking for updates: \") .. tostring(release.error), 4)\
            return\
        end\
        -- Persist the result so the next startup can show the banner\
        -- without needing a network request.\
        _latest_ver = release.version\
        _dl_url     = _isValidAssetUrl(release.download_url) and release.download_url or nil\
        _has_update = _versionGt(_latest_ver, current)\
        _persist_state(os.time())\
\
        _showUpdateDialog(release, current, M.installedSource() ~= \"release\")\
    end\
\
    if ok_tr and Trapper and Trapper.dismissableRunInSubprocess then\
        local completed, result = Trapper:dismissableRunInSubprocess(\
            _doFetch,\
            checking_msg,\
            function(res) handleCheckResult(res) end\
        )\
        if completed and result then\
            UIManager:scheduleIn(0.2, function() handleCheckResult(result) end)\
        elseif completed == false then\
            _closeWidget(checking_msg)\
            UI.Notify.toast(_(\"Update check cancelled.\"), 4)\
        end\
    else\
        UIManager:scheduleIn(0.3, function()\
            handleCheckResult(_doFetch())\
        end)\
    end\
end\
\
\
--- Check the selected branch head, then offer an install only when switching\
--- channels or when that branch has a newer commit than the installed one.\
function M._doManualBranchCheck(branch, current)\
    local ok_tr, Trapper = pcall(require, \"ui/trapper\")\
    local checking_msg = UI.Notify.toast(_(\"Checking for updates…\"), 15)\
\
    local function handleCheckResult(result)\
        _closeWidget(checking_msg)\
        if not result or result.error then\
            local err = result and result.error or _(\"unknown error\")\
            logger.err(\"simpleui updater branch check:\", err)\
            UI.Notify.toast(_(\"Error checking for updates: \") .. tostring(err), 4)\
            return\
        end\
\
        local head_sha = result.sha\
        local source = M.installedSource()\
        local installed_commit = M.installedCommit()\
        local expected_source = \"branch:\" .. branch\
        if source == expected_source and installed_commit == head_sha then\
            UI.Notify.toast(string.format(\
                _(\"Simple UI is up to date.\\n\\nBranch: %s\\nCommit: %s\"),\
                branch, _shortSha(head_sha)), 4)\
            return\
        end\
\
        local switching = source ~= expected_source\
        local prompt\
        if switching then\
            prompt = string.format(\
                _(\"The selected update channel is not currently installed.\\n\\nSwitch to branch: %s?\"),\
                branch)\
        elseif installed_commit == \"\" then\
            prompt = string.format(\
                _(\"Record and install the current revision of branch %s?\\n\\nCommit: %s\"),\
                branch, _shortSha(head_sha))\
        else\
            prompt = string.format(\
                _(\"A new branch revision is available.\\n\\nBranch: %s\\n%s → %s\"),\
                branch, _shortSha(installed_commit), _shortSha(head_sha))\
        end\
\
        UIManager:show(ConfirmBox:new{\
            text = prompt,\
            ok_text = switching and _(\"Switch\") or _(\"Update and restart\"),\
            cancel_text = _(\"Cancel\"),\
            ok_callback = function()\
                _applyUpdate(\
                    _branchArchiveUrl(branch),\
                    branch .. \" @ \" .. _shortSha(head_sha),\
                    {\
                        strip_root = true,\
                        on_success = function()\
                            local gs = _gs()\
                            if not gs then return end\
                            gs:saveSetting(GS_SOURCE, expected_source)\
                            gs:saveSetting(GS_COMMIT, head_sha)\
                            pcall(gs.flush, gs)\
                        end,\
                    })\
            end,\
        })\
    end\
\
    local function fetch()\
        return _doBranchFetch(branch)\
    end\
    if ok_tr and Trapper and Trapper.dismissableRunInSubprocess then\
        local completed, result = Trapper:dismissableRunInSubprocess(\
            fetch,\
            checking_msg,\
            function(res) handleCheckResult(res) end\
        )\
        if completed and result then\
            UIManager:scheduleIn(0.2, function() handleCheckResult(result) end)\
        elseif completed == false then\
            _closeWidget(checking_msg)\
            UI.Notify.toast(_(\"Update check cancelled.\"), 4)\
        end\
    else\
        UIManager:scheduleIn(0.3, function()\
            handleCheckResult(fetch())\
        end)\
    end\
end\
\
--- Returns a menu item when an update is available; nil otherwise.\
--- Called when building the About menu — uses in-memory cache (zero I/O).\
function M.build_update_banner_item()\
    _load_persisted_state()\
    if not _has_update then return nil end\
    local label = _latest_ver and (\"v\" .. _latest_ver) or _(\"latest\")\
    return {\
        text           = string.format(_(\"⬆ Update available: %s\"), label),\
        keep_menu_open = true,\
        callback       = function()\
            M.checkForUpdates()\
        end,\
    }\
end\
\
return M\
",
