-- sRGB equivalents of the BookOrbit light-theme metal and progress colours.\
local metal = {\
    common = { shadow = \"#5a564e\", body = \"#aaa498\", light = \"#ebe7de\", ring = \"#8f897d\" },\
    rare = { shadow = \"#2d5a7e\", body = \"#74a8d4\", light = \"#d9ecfa\", ring = \"#4f8cc0\" },\
    epic = { shadow = \"#583c83\", body = \"#967dda\", light = \"#e6d4f7\", ring = \"#8063c8\" },\
    legendary = { shadow = \"#8a6911\", body = \"#e8c25a\", light = \"#fff4c6\", ring = \"#c9a130\" },\
}\
\
local M = {}\
local function point(radius, angle)\
    return 50 + radius * math.sin(angle), 50 - radius * math.cos(angle)\
end\
\
local function rosette(lobes, radius, tip)\
    local path = {}\
    for i = 1, lobes do\
        local step = 2 * math.pi / lobes\
        if i == 1 then path[1] = string.format(\"M%.2f %.2f\", point(radius, 0)) end\
        local cx, cy = point(tip, (i - .5) * step)\
        local x, y = point(radius, i * step)\
        path[#path + 1] = string.format(\"Q%.2f %.2f %.2f %.2f\", cx, cy, x, y)\
    end\
    return '<path d=\"' .. table.concat(path) .. 'Z\"/>'\
end\
\
local rims = {\
    common = '<circle cx=\"50\" cy=\"50\" r=\"46\"/>',\
    rare = '<circle cx=\"50\" cy=\"50\" r=\"46.5\"/>',\
    epic = rosette(8, 41.2, 53.2), legendary = rosette(24, 43, 50.6),\
}\
local beads = {}\
for i = 1, 36 do\
    local x, y = point(42.6, i * math.pi / 18)\
    beads[i] = string.format('<circle cx=\"%.2f\" cy=\"%.2f\" r=\"1.25\"/>', x, y)\
end\
local bead_ring = table.concat(beads)\
local function symbol(shape, colour, stroke, offset, scale)\
    return string.format('<g transform=\"translate(%.2f %.2f) scale(%.4f)\" fill=\"none\" stroke=\"%s\" stroke-width=\"%.1f\" stroke-linecap=\"round\" stroke-linejoin=\"round\">%s</g>',\
        (100 - 24 * scale) / 2, (100 - 24 * scale) / 2 + offset, scale, colour, stroke, shape)\
end\
\
-- Compose from packaged shapes only. An API value can select a glyph but\
-- cannot supply SVG markup, a path on the device or an external resource.\
function M.svg(item, background)\
    local rarity = not item.secret and metal[item.rarity] and item.rarity or \"common\"\
    local c = metal[rarity]\
    local glyph = glyphs[item.icon] or glyphs[\"help-circle\"]\
    local parts = { '<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"108\" height=\"108\" viewBox=\"-4 -4 108 108\">' }\
    if background then\
        -- Some in-memory SVG renderers flatten transparent pixels to white.\
        -- ImageWidget preserves original image colours at night, so use the\
        -- visible card colour here, before KOReader's display inversion.\
        local fill = require(\"infra/sui_accent\").toHex(background)\
        parts[#parts + 1] = string.format('<rect x=\"-4\" y=\"-4\" width=\"108\" height=\"108\" fill=\"%s\"/>', fill)\
    end\
    if item.earned and not item.secret then\
        parts[#parts + 1] = string.format([[<defs>\
<linearGradient id=\"rim\" x1=\"0\" y1=\"0\" x2=\".92\" y2=\"1\">\
<stop stop-color=\"%s\"/><stop offset=\".3\" stop-color=\"%s\"/><stop offset=\".47\" stop-color=\"%s\"/>\
<stop offset=\".64\" stop-color=\"%s\"/><stop offset=\"1\" stop-color=\"%s\"/></linearGradient>\
<radialGradient id=\"face\" gradientUnits=\"userSpaceOnUse\" cx=\"40\" cy=\"34\" r=\"46\">\
<stop stop-color=\"%s\"/><stop offset=\".42\" stop-color=\"%s\"/><stop offset=\"1\" stop-color=\"%s\"/></radialGradient></defs>]],\
            c.shadow, c.body, c.light, c.body, c.shadow, c.light, c.body, c.shadow)\
        parts[#parts + 1] = '<g fill=\"url(#rim)\">' .. rims[rarity] .. '</g>'\
        if rarity == \"rare\" then parts[#parts + 1] = '<g fill=\"' .. c.light .. '\" opacity=\".55\">' .. bead_ring .. '</g>' end\
        parts[#parts + 1] = string.format([[<circle cx=\"50\" cy=\"50\" r=\"35.5\" fill=\"url(#face)\" stroke=\"%s\" stroke-width=\"1.4\"/>\
<circle cx=\"50\" cy=\"50\" r=\"32.4\" fill=\"none\" stroke=\"%s\" stroke-width=\".7\" opacity=\".5\"/>]], c.shadow, c.light)\
        parts[#parts + 1] = symbol(glyph, c.light, 2.1, .55, 38 / 24)\
        parts[#parts + 1] = symbol(glyph, c.shadow, 2.1, 0, 38 / 24)\
    else\
        parts[#parts + 1] = '<g fill=\"#ededed\" stroke=\"#c5c5c5\" stroke-width=\"1.2\">' .. rims[rarity] .. '</g>'\
        if rarity == \"rare\" then parts[#parts + 1] = '<g fill=\"#c5c5c5\">' .. bead_ring .. '</g>' end\
        parts[#parts + 1] = [[<defs><radialGradient id=\"blank\" cx=\".5\" cy=\".7\" r=\".65\"><stop stop-color=\"#f5f5f5\"/>\
<stop offset=\"1\" stop-color=\"#e4e4e4\"/></radialGradient></defs>\
<circle cx=\"50\" cy=\"50\" r=\"35.5\" fill=\"url(#blank)\" stroke=\"#c5c5c5\"/>]]\
        if item.secret then\
