    ["screens/sui_bluetooth"] = "-- Read-only Bluetooth state per platform (Kindle, Kobo, PocketBook) for the topbar.\
\
local Device = require(\"device\")\
\
local M = {}\
\
local KINDLE_SERVICE = \"com.lab126.btfd\"\
local BLUEZ_SERVICE  = \"org.bluez\"\
local MTK_SERVICE    = \"com.kobo.mtk.bluedroid\"\
local KOBO_PROVIDER  = \"kobo_plugin\"\
local STATE_TTL      = 5\
\
local _backend    = nil -- \"kindle\" | \"kobo\" | \"pocketbook\" | false\
local _kobo_dest  = nil -- D-Bus destination of the Kobo stack, or false\
local _state      = nil\
local _state_time = 0\
\
local function isPlatform(method)\
    local ok, v = pcall(function() return Device[method](Device) end)\
    return ok and v == true\
end\
\
-- Kindle: integer BTstate via LIPC, or nil if unavailable.\
local function readKindle()\
    local value\
    local ok_lipc, lipc = pcall(require, \"liblipclua\")\
    if ok_lipc and lipc then\
        local handle = lipc.init(\"com.github.koreader.simpleui.bluetooth\")\
        if handle then\
            local ok, state = pcall(handle.get_int_property, handle, KINDLE_SERVICE, \"BTstate\")\
            pcall(handle.close, handle)\
            if ok and type(state) == \"number\" then value = state end\
        end\
    end\
    if value == nil then\
        local out = io.popen(\"lipc-get-prop -i \" .. KINDLE_SERVICE .. \" BTstate 2>/dev/null\", \"r\")\
        if out then\
            value = out:read(\"*n\")\
            out:close()\
        end\
    end\
    if type(value) ~= \"number\" then return nil end\
    return value ~= 0\
end\
\
-- PocketBook: parses `netagent bt status`; nil when BT is not reported.\
local function readPocketBook()\
    local out = io.popen(\"netagent bt status 2>/dev/null\", \"r\")\
    if not out then return nil end\
    local text = out:read(\"*a\") or \"\"\
    out:close()\
    if text:find(\"BT_STATE_OFF\", 1, true) then return false end\
    if text:find(\"BT_STATE_\", 1, true) then return true end\
    return nil\
end\
\
-- Kobo: Bluetooth controller exposed by a third-party provider, if any.\
local function koboProvider()\
    local ok, PluginLoader = pcall(require, \"pluginloader\")\
    if not ok or not PluginLoader then return nil end\
    local provider = PluginLoader:getPluginInstance(KOBO_PROVIDER)\
    local bt = provider and provider.kobo_bluetooth\
    if type(bt) ~= \"table\" or type(bt.isBluetoothEnabled) ~= \"function\" then return nil end\
    local ok_s, supported = pcall(bt.isDeviceSupported, bt)\
    return ok_s and supported and bt or nil\
end\
\
-- Kobo: D-Bus destination for models with a Bluetooth stack, or false.\
local function koboDestination()\
    local model = Device.model\
    if model == \"Kobo_io\" or model == \"Kobo_goldfinch\" or model == \"Kobo_cadmus\" then\
        return BLUEZ_SERVICE\
    end\
    if isPlatform(\"isMTK\") then\
        local f = io.open(\"/usr/share/dbus-1/system-services/\" .. MTK_SERVICE .. \".service\", \"r\")\
        if f then\
            f:close()\
            return MTK_SERVICE\
        end\
    end\
    return false\
end\
\
local function dbusBool(dest, path, args)\
    local out = io.popen(\"dbus-send --system --print-reply --reply-timeout=1500 --dest=\"\
        .. dest .. \" \" .. path .. \" \" .. args .. \" 2>/dev/null\", \"r\")\
    if not out then return nil end\
    local text = out:read(\"*a\") or \"\"\
    out:close()\
    if text:find(\"boolean true\", 1, true) then return true end\
    if text:find(\"boolean false\", 1, true) then return false end\
    return nil\
end\
\
-- Kobo: adapter is on only when its service runs and reports Powered.\
local function readKobo()\
    local bt = koboProvider()\
    if bt then\
        local ok, v = pcall(bt.isBluetoothEnabled, bt)\
        return ok and v == true\
    end\
    if not _kobo_dest then return false end\
    if dbusBool(\"org.freedesktop.DBus\", \"/org/freedesktop/DBus\",\
            \"org.freedesktop.DBus.NameHasOwner string:\" .. _kobo_dest) ~= true then\
        return false\
    end\
    return dbusBool(_kobo_dest, \"/org/bluez/hci0\",\
        \"org.freedesktop.DBus.Properties.Get string:org.bluez.Adapter1 string:Powered\") == true\
end\
\
local function backend()\
    if _backend ~= nil then return _backend end\
    -- Preserve the native Device API, notably on Android/Boox/Bigme.\
    if isPlatform(\"hasBluetoothToggle\") and type(Device.isBluetoothOn) == \"function\" then\
        _backend = \"device\"\
    elseif isPlatform(\"isKindle\") then\
        _backend = readKindle() ~= nil and \"kindle\" or false\
    elseif isPlatform(\"isKobo\") then\
        _kobo_dest = koboDestination()\
        _backend = (_kobo_dest or koboProvider()) and \"kobo\" or false\
    elseif isPlatform(\"isPocketBook\") then\
        _backend = readPocketBook() ~= nil and \"pocketbook\"\
    else\
        _backend = false\
    end\
    return _backend\
end\
\
-- True when this device can report Bluetooth state.\
function M.isAvailable()\
    return backend() ~= false\
end\
\
-- Current Bluetooth state, cached for STATE_TTL seconds.\
function M.isOn()\
    local b = backend()\
    if not b then return false end\
    local now = os.time()\
    if _state ~= nil and now - _state_time < STATE_TTL then return _state end\
    local v\
    if b == \"device\" then\
        local ok, state = pcall(Device.isBluetoothOn, Device)\
        v = ok and state == true\
    elseif b == \"kindle\" then\
        v = readKindle()\
    elseif b == \"kobo\" then\
        v = readKobo()\
    else\
        v = readPocketBook()\
    end\
    _state, _state_time = v == true, now\
    return _state\
end\
\
-- Stores a state reported by an event; nil forces a fresh read.\
function M.setState(on)\
    if on == nil then\
        _state, _state_time = nil, 0\
    else\
        _state, _state_time = on == true, os.time()\
    end\
end\
\
-- Forgets the detected backend and cached state.\
function M.reset()\
    _backend, _kobo_dest = nil, nil\
    _state, _state_time = nil, 0\
end\
\
return M\
",
    ["features/library/sui_rule_collections"] = "-- sui_rule_collections.lua — Simple UI\
-- Collections connected to a metadata rule instead of a real folder: the\
-- books under a base folder that match an author/series/tags trail (a\
-- virtual library leaf, a facet group or an in-folder series group).\
--\
-- The rule lives in the collection settings, next to KOReader's connected\
-- folders, and is rescanned whenever KOReader rescans those folders. A rescan\
-- mirrors the rule: matching books are added (honouring the collection's\
-- \"add\" filter) and books that no longer match are removed, except books\
-- that belong to a real folder connected to the same collection.\
--\
-- Rule (coll_settings[name][RuleCollections.KEY]):\
--   base_dir      folder whose books are matched\
--   trail         { {dimension=, value=}, ... }, as in FilterState\
--   subfolders    match the whole subtree (true) or base_dir only (false)\
--   scan_on_show  rescan when the collection is opened\
--\
-- Public API\
-- ----------\
--   RuleCollections.KEY\
--   RuleCollections.new(base_dir, trail, subfolders) -> rule\
--   RuleCollections.get(coll_name)                   -> rule | nil\
--   RuleCollections.sync(rc, coll_name, is_showing)  -> added, removed\
--   RuleCollections.syncAll(rc)                      -- rescans and saves every rule\
--   RuleCollections.label(rule)                      -> text for folder lists\
--   RuleCollections.flags(rule)                      -> subfolders/scan markers | nil\
--   RuleCollections.open(rule, ui)                   -- shows the rule's books\
\
local ffiUtil = require(\"ffi/util\")\
local lfs     = require(\"libs/libkoreader-lfs\")\
local util    = require(\"util\")\
\
local Config         = require(\"infra/sui_config\")\
local FilterState    = require(\"features/library/sui_filter_state\")\
local MetadataSource = require(\"features/library/sui_metadata_source\")\
local VirtualPath    = require(\"features/library/sui_virtual_path\")\
\
local RuleCollections = {}\
\
RuleCollections.KEY = \"simpleui_rule\"\
\
local function stripSlash(path)\
    return (path:gsub(\"(.)/+$\", \"%1\"))\
end\
\
function RuleCollections.new(base_dir, trail, subfolders)\
    local copy = {}\
    for i, entry in ipairs(trail) do\
        copy[i] = { dimension = entry.dimension, value = entry.value }\
    end\
    return {\
        base_dir     = stripSlash(base_dir),\
        trail        = copy,\
        subfolders   = subfolders and true or false,\
        scan_on_show = true,\
    }\
end\
\
function RuleCollections.get(coll_name)\
    local settings = require(\"readcollection\").coll_settings[coll_name]\
    return settings and settings[RuleCollections.KEY]\
end\
\
-- File types and statuses of the collection's \"add\" filter.\
local function addFilter(settings)\
    local filter = util.tableGetValue(settings, \"filter\", \"add\")\
    if not filter then return nil, nil end\
    local types\
    if filter.filetype then\
        types = {}\
        for filetype in util.gsplit(filter.filetype, \",\") do\
            types[util.trim(filetype)] = true\
        end\
    end\
    return types, filter.status\
end\
\
local function passesAddFilter(file, filename, types, statuses)\
    if filename:sub(1, 2) == \"._\" then return false end\
    if types then\
        local _name, ext = require(\"apps/filemanager/filemanagerutil\").splitFileNameType(filename)\
        if not types[ext] then return false end\
    elseif not require(\"document/documentregistry\"):hasProvider(filename) then\
        return false\
    end\
    if statuses then\
        return statuses[require(\"ui/widget/booklist\").getBookStatus(file)] and true or false\
    end\
    return true\
end\
\
-- True when `file` lies in a real folder connected to the collection.\
local function inConnectedFolder(file, folders)\
    if not folders then return false end\
    for folder, folder_settings in pairs(folders) do\
        local prefix = stripSlash(ffiUtil.realpath(folder) or folder) .. \"/\"\
        if file:sub(1, #prefix) == prefix\
                and (folder_settings.subfolders or not file:find(\"/\", #prefix + 1, true)) then\
            return true\
        end\
    end\
    return false\
end\
\
-- Books matching the rule, in display order, as { {file, filename}, ... }\
-- keyed by real path too. nil when the rule cannot be evaluated (folder\
-- missing, metadata unavailable or not indexed): the collection is then left\
-- untouched rather than emptied.\
local function matchedBooks(rule)\
    local base_dir = rule.base_dir\
    if not (base_dir and lfs.attributes(base_dir, \"mode\") == \"directory\") then return nil end\
    local ok_bim, bim = pcall(require, \"bookinfomanager\")\
    if not (ok_bim and bim) then return nil end\
    local all, complete = MetadataSource.getMatchingFiles(bim, base_dir, nil)\
    if complete == false or #all == 0 then return nil end\
\
    local state = FilterState.new(base_dir)\
    for _i, entry in ipairs(rule.trail) do\
        FilterState.addFilter(state, entry.dimension, entry.value)\
    end\
    local rows, matched_complete = MetadataSource.getMatchingFiles(bim, base_dir, state)\
    if matched_complete == false then return nil end\
    local last = rule.trail[#rule.trail]\
    MetadataSource.sortFiles(rows, last and last.dimension)\
\
    local books = {}\
    for _i, row in ipairs(rows) do\
        local path = row[1]\
        if (rule.subfolders or path:match(\"^(.*)/[^/]+$\") == base_dir)\
                and lfs.attributes(path, \"mode\") == \"file\" then\
            local file = ffiUtil.realpath(path) or path\
            if not books[file] then\
                books[file] = true\
                books[#books + 1] = { file, row[2] }\
            end\
        end\
    end\
    return books\
end\
\
-- Rescans the rule of `coll_name` into rc.coll, without saving.\
function RuleCollections.sync(rc, coll_name, is_showing)\
    local settings = rc.coll_settings[coll_name]\
    local rule = settings and settings[RuleCollections.KEY]\
    local coll = rc.coll[coll_name]\
    if not (rule and coll) or (is_showing and not rule.scan_on_show) then return 0, 0 end\
    local books = matchedBooks(rule)\
    if not books then return 0, 0 end\
\
    local types, statuses = addFilter(settings)\
    local added, removed = 0, 0\
    for _i, book in ipairs(books) do\
        local file = book[1]\
        if not coll[file] and passesAddFilter(file, book[2], types, statuses) then\
            rc:addItem(file, coll_name)\
            added = added + 1\
        end\
    end\
    for file in pairs(coll) do\
        if not books[file] and not inConnectedFolder(file, settings.folders) then\
            rc:removeItem(file, coll_name, true)\
            removed = removed + 1\
        end\
    end\
    return added, removed\
end\
\
function RuleCollections.syncAll(rc)\
    local changed\
    for coll_name, settings in pairs(rc.coll_settings) do\
        if settings[RuleCollections.KEY] then\
            local added, removed = RuleCollections.sync(rc, coll_name)\
            if added + removed > 0 then\
                changed = changed or {}\
                changed[coll_name] = true\
            end\
        end\
    end\
    if changed then rc:write(changed) end\
end\
\
function RuleCollections.label(rule)\
    local Browse = require(\"features/library/sui_library_browse\")\
    local parts = { rule.base_dir }\
    for _i, entry in ipairs(rule.trail) do\
        parts[#parts + 1] = Browse.getModeLabel(entry.dimension) or entry.dimension\
        parts[#parts + 1] = VirtualPath.displayValue(entry.value)\
    end\
    return table.concat(parts, \" › \")\
end\
\
-- Same markers KOReader shows for connected folders.\
function RuleCollections.flags(rule)\
    local marks = {}\
    if rule.scan_on_show then marks[#marks + 1] = Config.nerdIconChar(\"nerd:F441\") end\
    if rule.subfolders then marks[#marks + 1] = Config.nerdIconChar(\"nerd:F114\") end\
    return marks[1] and table.concat(marks, \" \") or nil\
end\
\
-- Opens the rule's books: the library leaf when the library browser is on,\
-- otherwise the base folder.\
function RuleCollections.open(rule, ui)\
    local fc = ui and ui.file_chooser\
    if not fc then\
        ui:onClose()\
        ui:showFileManager(rule.base_dir .. \"/\")\
        return\
    end\
    local Browse = require(\"features/library/sui_library_browse\")\
    local last = rule.trail[#rule.trail]\
    if rule.subfolders and last and last.value ~= false and Browse.isEnabled() then\
        local prefix = FilterState.new(rule.base_dir)\
        for i = 1, #rule.trail - 1 do\
            FilterState.addFilter(prefix, rule.trail[i].dimension, rule.trail[i].value)\
        end\
        Browse.navigateToLeaf(ui, last.dimension, last.value, {\
            base_dir     = rule.base_dir,\
            filter_state = prefix,\
        })\
    else\
        fc:changeToPath(rule.base_dir)\
    end\
end\
\
return RuleCollections\
",
    ["features/library/sui_sort_sheet"] = "-- sui_sort_sheet.lua — Simple UI\
-- View and sort options of a library tab, shown on a long press of the tab.\
--\
-- The Library tab reads and writes KOReader's own settings (collate,\
-- reverse_collate, collate_mixed) through the file manager's handlers, so the\
-- file browser and the books of every group share one sort order, and the\
-- CoverBrowser's display mode. Under the rows the sheet toggles the flat view\
-- (Library) and the grouping of series books. The Authors / Series / Tags\
-- tabs keep a view and a sort of their own for their list (see\
-- sui_tab_views), and, listed as a list, their own items per page.\
--\
-- It also registers the \"number of books\" collate in FileChooser.collates:\
-- metadata folders (Authors/Series/Tags) are sorted by the number of books\
-- they hold; everything else falls back to the name.\
--\
--   SortSheet.install() / SortSheet.uninstall()  — register / remove the collate\
--   SortSheet.show(fm, mode)                     — show the sheet for a browse mode\
--   SortSheet.sortsFacetFolders(id)              — whether a collate orders metadata folders\
--   SortSheet.viewOptions(fm, mode)              — { { id, text }, … } views a tab offers\
--   SortSheet.getView / setView(fm, mode, id)    — current view of a tab and its change\
--   SortSheet.sortGroups(fc, mode)               — groups of { id, label } collates a tab offers\
--   SortSheet.getSort / setSort(fm, mode, id)    — current collate of a tab and its change\
--   SortSheet.isReverse / setReverse(fm, mode, on)\
--   SortSheet.getPerPage / setPerPage(fm, mode, n) — list items per page of a metadata tab and its change\
\
local ffiUtil     = require(\"ffi/util\")\
local T           = ffiUtil.template\
local _           = require(\"infra/sui_i18n\").translate\
local ActionSheet = require(\"engines/sui_action_sheet\")\
local TabViews    = require(\"features/library/sui_tab_views\")\
\
local M = {}\
\
local COUNT_ID = \"sui_count\"\
\
-- Collates that sort the metadata folders of the Authors/Series/Tags tabs.\
local FACET_COLLATES = { \"strcoll\", \"natural\", COUNT_ID }\
\
local COUNT_COLLATE = {\
    text              = _(\"number of books\"),\
    menu_order        = 150,\
    can_collate_mixed = true,\
    init_sort_func    = function()\
        return function(a, b)\
            local ca, cb = a.nb_sub_files, b.nb_sub_files\
            if ca ~= cb then\
                if not ca then return false end\
                if not cb then return true end\
                return ca > cb\
            end\
            return ffiUtil.strcoll(a.text, b.text)\
        end\
    end,\
}\
\
function M.install()\
    local FileChooser = require(\"ui/widget/filechooser\")\
    FileChooser.collates[COUNT_ID] = COUNT_COLLATE\
end\
\
-- A saved \"sui_count\" left behind falls back to the name in getCollate().\
function M.uninstall()\
    local FileChooser = require(\"ui/widget/filechooser\")\
    if FileChooser.collates[COUNT_ID] == COUNT_COLLATE then\
        FileChooser.collates[COUNT_ID] = nil\
    end\
end\
\
-- True when the collate `id` can sort metadata folders: their attributes are\
-- placeholders, so date, access and size collates would leave them unordered.\
function M.sortsFacetFolders(id)\
    for _i, facet_id in ipairs(FACET_COLLATES) do\
        if facet_id == id then return true end\
    end\
    return false\
end\
\
-- Most buttons on one segments row; longer groups wrap onto further rows.\
local ROW_MAX = 3\
\
-- Groups of the file-browser collates, each with the short button label of\
-- its collates. The sheet title shows the full name of the current one.\
local function _libraryGroups()\
    return {\
        { title = _(\"Name\"), collates = {\
            { \"strcoll\", _(\"Alphabetical\") }, { \"natural\", _(\"Natural\") } } },\
        { title = _(\"Date\"), collates = {\
            { \"access\", _(\"Last read\") }, { \"date\", _(\"Modified\") } } },\
        { title = _(\"Progress\"), collates = {\
            { \"percent_unopened_first\", _(\"Unopened first\") },\
            { \"percent_unopened_last\",  _(\"Unopened last\") },\
            { \"percent_natural\",        _(\"Finished last\") } } },\
        { title = _(\"File\"), collates = {\
            { \"size\", _(\"Size\") }, { \"type\", _(\"Type\") } } },\
        { title = _(\"Metadata\"), collates = {\
            { \"title\", _(\"Title\") }, { \"authors\", _(\"Authors\") }, { \"series\", _(\"Series\") },\
            { \"keywords\", _(\"Keywords\") }, { \"rating\", _(\"Rating\") } } },\
    }\
end\
\
-- The collates of a metadata tab, as one untitled group.\
local function _facetGroups()\
    return { { collates = {\
        { \"strcoll\", _(\"Alphabetical\") }, { \"natural\", _(\"Natural\") }, { COUNT_ID, _(\"Book count\") } } } }\
end\
\
-- Groups offered for `mode`, keeping only the collates that exist. Collates\
-- of the file browser that no group names are listed under \"Other\" with their\
-- own name; the book count only orders metadata folders, so it is left out.\
function M.sortGroups(fc, mode)\
    local groups, out, named = mode == \"normal\" and _libraryGroups() or _facetGroups(), {}, {}\
    for _i, group in ipairs(groups) do\
        local present = {}\
        for _j, c in ipairs(group.collates) do\
            named[c[1]] = true\
            if fc.collates[c[1]] then present[#present + 1] = c end\
        end\
        if #present > 0 then\
            out[#out + 1] = { title = group.title, collates = present }\
        end\
    end\
    if mode == \"normal\" then\
        local other = {}\
        for _i, id in ipairs((require(\"apps/filemanager/filemanager\").getSortByActions())) do\
            if not named[id] and id ~= COUNT_ID then\
                other[#other + 1] = { id, fc.collates[id].text }\
            end\
        end\
        if #other > 0 then out[#out + 1] = { title = _(\"Other\"), collates = other } end\
    end\
    return out\
end\
\
-- Re-draws the list when `mode` is the tab on screen.\
local function _refresh(fm, mode)\
    local fc = fm.file_chooser\
    if fc and TabViews.rootMode(fc.path) == mode then fc:refreshPath() end\
end\
\
-- ---------------------------------------------------------------------------\
-- View\
-- ---------------------------------------------------------------------------\
\
local CLASSIC = \"classic\"\
\
function M.viewOptions(fm, mode)\
    local options = {}\
    local cb = fm.coverbrowser\
    for _i, entry in ipairs(cb and cb.modes or {}) do\
        -- The classic view has no id; the tabs leave it out.\
        if entry[2] or mode == \"normal\" then\
            options[#options + 1] = { id = entry[2] or CLASSIC, text = entry[1] }\
        end\
    end\
    return options\
end\
\
function M.getView(_fm, mode)\
    if mode == \"normal\" then return TabViews.libraryMode() or CLASSIC end\
    return TabViews.getView(mode)\
end\
\
function M.setView(fm, mode, id)\
    if mode == \"normal\" then\
        local cb = fm.coverbrowser\
        if not cb then return end\
        cb:setDisplayMode(id ~= CLASSIC and id or nil)\
    else\
        TabViews.setView(mode, id)\
        _refresh(fm, mode)\
    end\
end\
\
local function _viewLabel(fm, mode)\
    local current = M.getView(fm, mode)\
    for _i, option in ipairs(M.viewOptions(fm, mode)) do\
        if option.id == current then return option.text end\
    end\
    return \"\"\
end\
\
-- Portrait items per page of a metadata tab listed as a list.\
function M.getPerPage(_fm, mode)\
    return TabViews.getPerPage(mode)\
end\
\
function M.setPerPage(fm, mode, n)\
    TabViews.setPerPage(mode, n)\
    _refresh(fm, mode)\
end\
\
-- ---------------------------------------------------------------------------\
-- Library size: the file browser's own settings, shared with its menu\
-- ---------------------------------------------------------------------------\
\
M.GRID_MIN, M.GRID_MAX = 2, 8\
M.LIST_PAGE_MIN, M.LIST_PAGE_MAX, M.LIST_PAGE_DEFAULT = 4, 20, 10\
local GRID_DEFAULTS = {\
    nb_cols_portrait = 3, nb_rows_portrait = 3,\
    nb_cols_landscape = 4, nb_rows_landscape = 2,\
}\
\
-- \"mosaic\", \"list\", or nil for the classic view, of the Library on screen.\
function M.libraryLayout(fm)\
    local view = M.getView(fm, \"normal\")\
    if view:sub(1, 7) == \"mosaic_\" then return \"mosaic\" end\
    if TabViews.isListView(view) then return \"list\" end\
    return nil\
end\
\
-- Stores size settings (key → value), in the file browser and in the settings\
-- it reads at start, and redraws the list once.\
local function _setLibrarySize(fc, values)\
    local changed = false\
    for key, n in pairs(values) do\
        if fc[key] ~= n then\
            changed = true\
            fc[key] = n\
            require(\"bookinfomanager\"):saveSetting(key, n)\
            require(\"ui/widget/filechooser\")[key] = n\
        end\
    end\
    if changed then fc:updateItems() end\
end\
\
local function _portrait()\
    local Screen = require(\"device\").screen\
    return Screen:getWidth() <= Screen:getHeight()\
end\
\
-- `what` is \"cols\" or \"rows\"; the mosaic of the orientation on screen.\
local function _gridKey(what)\
    return \"nb_\" .. what .. (_portrait() and \"_portrait\" or \"_landscape\")\
end\
\
function M.getGrid(fm, what)\
    local fc = fm.file_chooser\
    return fc[_gridKey(what)] or GRID_DEFAULTS[_gridKey(what)]\
end\
\
function M.setGrid(fm, cols, rows)\
    _setLibrarySize(fm.file_chooser, { [_gridKey(\"cols\")] = cols, [_gridKey(\"rows\")] = rows })\
end\
\
function M.getLibraryPerPage(fm)\
    return fm.file_chooser.files_per_page or M.LIST_PAGE_DEFAULT\
end\
\
function M.setLibraryPerPage(fm, n)\
    _setLibrarySize(fm.file_chooser, { files_per_page = n })\
end\
\
-- ---------------------------------------------------------------------------\
-- Sort\
-- ---------------------------------------------------------------------------\
\
function M.getSort(fm, mode)\
    if mode == \"normal\" then return (select(2, fm.file_chooser:getCollate())) end\
    return TabViews.getSort(mode)\
end\
\
function M.setSort(fm, mode, id)\
    if mode == \"normal\" then\
        fm:onSetSortBy(id)\
    else\
        TabViews.setSort(mode, id)\
        _refresh(fm, mode)\
    end\
end\
\
function M.isReverse(_fm, mode)\
    if mode == \"normal\" then return G_reader_settings:isTrue(\"reverse_collate\") end\
    return TabViews.isReverse(mode)\
end\
\
function M.setReverse(fm, mode, on)\
    if mode == \"normal\" then\
        fm:onSetReverseSorting(on)\
    else\
        TabViews.setReverse(mode, on)\
        _refresh(fm, mode)\
    end\
end\
\
local function _sortLabel(fm, mode)\
    local fc = fm.file_chooser\
    local collate = fc.collates[M.getSort(fm, mode)] or fc.collates.strcoll\
    return collate.text\
end\
\
-- ---------------------------------------------------------------------------\
-- Sheet\
-- ---------------------------------------------------------------------------\
\
function M.show(fm, mode)\
    local fc = fm and fm.file_chooser\
    if not fc then return end\
\
    local win, rootSections\
\
    -- Rows of the sheet; their values follow every change made on a page.\
    local view_row     = { text = _(\"View\"), chevron = true, keep_open = true }\
    local per_page_row = { text = _(\"Items per page\"), keep_open = true }\
    local grid_row     = { text = _(\"Items per page\"), keep_open = true }\
    local sort_row     = { text = _(\"Sort\"), chevron = true, keep_open = true }\
    local function refreshRows()\
        view_row.value = _viewLabel(fm, mode)\
        if mode ~= \"normal\" then\
            per_page_row.value = tostring(M.getPerPage(fm, mode))\
        elseif M.libraryLayout(fm) == \"mosaic\" then\
            grid_row.value = T(_(\"%1 × %2\"), M.getGrid(fm, \"cols\"), M.getGrid(fm, \"rows\"))\
        elseif M.libraryLayout(fm) == \"list\" then\
            per_page_row.value = tostring(M.getLibraryPerPage(fm))\
        end\
        sort_row.value = _sortLabel(fm, mode)\
    end\
\
    -- Options of how the list is built, shown under the rows: the flat view\
    -- (Library only) and the grouping of series books.\
    local function viewToggles()\
        local BM = require(\"features/library/sui_library_browse\")\
        local toggles = {}\
        if mode == \"normal\" and BM.isEnabled() then\
            local flat = BM.isFlatEnabled()\
            toggles[#toggles + 1] = {\
                text     = _(\"Flat view\"),\
                toggle   = flat,\
                callback = function()\
                    BM.setFlat(fm, not flat)\
                    win:update{ sections = rootSections() }\
                end,\
            }\
        end\
        for _i, grouped_mode in ipairs(BM.SERIES_GROUPING_MODES) do\
            if grouped_mode == mode then\
                local FolderCovers = require(\"features/library/sui_foldercovers\")\
                local grouped = FolderCovers.getSeriesGrouping(mode)\
                toggles[#toggles + 1] = {\
                    text     = _(\"Group by Series\"),\
                    toggle   = grouped,\
                    callback = function()\
                        FolderCovers.setSeriesGrouping(mode, not grouped)\
                        FolderCovers.invalidateCache()\
                        fm._navbar_suppress_path_change = true\
                        fc:refreshPath()\
                        fm._navbar_suppress_path_change = nil\
                        win:update{ sections = rootSections() }\
                    end,\
                }\
            end\
        end\
        return toggles\
    end\
\
    -- The page size follows the view: the grid of a mosaic, the items\
    -- per page of a list, nothing for the classic view.\
    function rootSections()\
        local rows = { view_row }\
        if mode ~= \"normal\" then\
            if TabViews.isListView(TabViews.getView(mode)) then rows[#rows + 1] = per_page_row end\
        elseif M.libraryLayout(fm) == \"mosaic\" then\
            rows[#rows + 1] = grid_row\
        elseif M.libraryLayout(fm) == \"list\" then\
            rows[#rows + 1] = per_page_row\
        end\
        rows[#rows + 1] = sort_row\
        local sections = { ActionSheet.list(rows) }\
        local toggles  = viewToggles()\
        if #toggles > 0 then sections[#sections + 1] = ActionSheet.list(toggles) end\
        return sections\
    end\
\
    local function sortSections()\
        local sections = {}\
        local current = M.getSort(fm, mode)\
        for _i, group in ipairs(M.sortGroups(fc, mode)) do\
            if group.title then\
                sections[#sections + 1] = { type = \"note\", text = group.title }\
            end\
            local row\
            for j, c in ipairs(group.collates) do\
                if (j - 1) % ROW_MAX == 0 then\
                    row = { type = \"segments\", items = {} }\
                    sections[#sections + 1] = row\
                end\
                local id = c[1]\
                row.items[#row.items + 1] = {\
                    text     = c[2],\
                    selected = id == current,\
                    callback = function()\
                        if id ~= current then M.setSort(fm, mode, id) end\
                        refreshRows()\
                        win:update{ title = T(_(\"Sort by: %1\"), _sortLabel(fm, mode)), sections = sortSections() }\
                    end,\
                }\
            end\
        end\
\
        local reverse = M.isReverse(fm, mode)\
        local toggles = { {\
            text     = _(\"Reverse sorting\"),\
            toggle   = reverse,\
            callback = function()\
                M.setReverse(fm, mode, not reverse)\
                win:update{ sections = sortSections() }\
            end,\
        } }\
        if mode == \"normal\" then\
            local collate = fc:getCollate()\
            local mixed = G_reader_settings:isTrue(\"collate_mixed\")\
            toggles[#toggles + 1] = {\
                text     = _(\"Folders and files mixed\"),\
                enabled  = collate.can_collate_mixed or false,\
                toggle   = collate.can_collate_mixed and mixed or false,\
                callback = function()\
                    fm:onSetMixedSorting(not mixed)\
                    win:update{ sections = sortSections() }\
                end,\
            }\
        end\
\
        sections[#sections + 1] = ActionSheet.list(toggles)\
        return sections\
    end\
\
    view_row.callback = function()\
        local current, items = M.getView(fm, mode), {}\
        for _i, option in ipairs(M.viewOptions(fm, mode)) do\
            items[#items + 1] = {\
                text     = option.text,\
                checked  = option.id == current,\
                callback = function()\
                    if option.id ~= current then M.setView(fm, mode, option.id) end\
                    refreshRows()\
                    win:update{ sections = rootSections() }\
                end,\
            }\
        end\
        ActionSheet.pick{ parent = win, title = _(\"View\"), icon = \"list\", items = items }\
    end\
\
    local function spin(opts)\
        opts.on_apply = function(n)\
            opts.apply(n)\
            refreshRows()\
            if win:isOpen() then win:update{} end\
        end\
        require(\"features/dialogs/sui_dialogs\").spin(opts)\
    end\
\
    per_page_row.callback = function()\
        if mode == \"normal\" then\
            spin{\
                title   = _(\"Items per page\"),\
                info    = _(\"Portrait list mode\"),\
                value   = M.getLibraryPerPage(fm),\
                min     = M.LIST_PAGE_MIN,\
                max     = M.LIST_PAGE_MAX,\
                default = M.LIST_PAGE_DEFAULT,\
                apply   = function(n) M.setLibraryPerPage(fm, n) end,\
            }\
            return\
        end\
        spin{\
            title   = _(\"Items per page\"),\
            info    = _(\"Portrait list mode\"),\
            value   = M.getPerPage(fm, mode),\
            min     = TabViews.PER_PAGE_MIN,\
            max     = TabViews.PER_PAGE_MAX,\
            default = TabViews.defaultPerPage(mode),\
            apply   = function(n) M.setPerPage(fm, mode, n) end,\
        }\
    end\
\
    grid_row.callback = function()\
        local portrait = _portrait()\
        local function axis(text, what, default)\
            return { text = text, value = M.getGrid(fm, what), min = M.GRID_MIN, max = M.GRID_MAX,\
                default = default }\
        end\
        require(\"features/dialogs/sui_dialogs\").spin2{\
            title    = portrait and _(\"Portrait mosaic mode\") or _(\"Landscape mosaic mode\"),\
            left     = axis(_(\"Columns\"), \"cols\", GRID_DEFAULTS[_gridKey(\"cols\")]),\
            right    = axis(_(\"Rows\"), \"rows\", GRID_DEFAULTS[_gridKey(\"rows\")]),\
            on_apply = function(cols, rows)\
                M.setGrid(fm, cols, rows)\
                refreshRows()\
                if win:isOpen() then win:update{} end\
            end,\
        }\
    end\
\
    sort_row.callback = function()\
        win:showPage{\
            title    = T(_(\"Sort by: %1\"), _sortLabel(fm, mode)),\
            icon     = \"sort\",\
            sections = sortSections(),\
        }\
    end\
\
    refreshRows()\
    win = ActionSheet.show{\
        name     = \"sui_win_sort\",\
        title    = _(\"View and sort\"),\
        icon     = \"sort\",\
        flow     = true,\
        sections = rootSections(),\
    }\
end\
\
return M\
",
    ["features/library/sui_book_rows"] = "-- sui_book_rows.lua — Simple UI\
-- Book rows of the detailed list views: cover, title over series and authors,\
-- and the reading progress over the file info on the right.\
--\
-- Public API:\
--   BookRows.progressText(book_info, pages, settings)   -- \"4 %\", \"Finished – 3 pages\", nil\
--   BookRows.barFraction(book_info)                     -- 0..1 reading fraction\
--   BookRows.barText(book_info, pages, settings)        -- \"10%\", \"On hold\", \"Finished\", ...\
--   BookRows.dotsFilled(fraction, count)                -- read dots of a dotted bar\
--   BookRows.fileInfoText(filetype, size, annotated, no_provider)\
--   BookRows.seriesLine(series, index)                  -- \"NAME - 2\"\
--   BookRows.authorsLine(authors)                       -- authors on one line\
--   BookRows.build(item, dimen, opts)                   -- the row widget, or nil to keep the native row\
\
local _ = require(\"infra/sui_i18n\").translate\
local N_ = require(\"infra/sui_i18n\").ngettext\
local T = require(\"ffi/util\").template\
\
local M = {}\
\
local function _round(x) return math.floor(x + 0.5) end\
\
-- Dots of a dotted progress bar.\
M.DOT_COUNT = 16\
\
-- Reading fraction of a book, clamped to 0..1: a finished book is full and\
-- one never opened is empty.\
function M.barFraction(book_info)\
    if book_info.status == \"complete\" then return 1 end\
    return math.max(0, math.min(1, book_info.percent_finished or 0))\
end\
\
-- Short progress text shown next to the bar: \"10%\" (also \"0%\" for a book never\
-- opened), \"On hold\" or \"Finished\". `settings` ({ pages_read, pages_left },\
-- optional) follows the file browser: pages read (\"50/503\") replace the\
-- percentage and follow \"On hold\" (\"On hold · 50/503\"); pages left\
-- (\", 453 to read\") are appended.\
function M.barText(book_info, pages, settings)\
    local status = book_info.status\
    if status == \"complete\" then return _(\"Finished\") end\
    settings = settings or {}\
    local fraction = M.barFraction(book_info)\
    local read = pages and _round(fraction * pages)\
    local position = pages and (read .. \"/\" .. pages)\
    local held = status == \"abandoned\"\
    local text = held and _(\"On hold\") or string.format(\"%d%%\", math.floor(fraction * 100 + 0.5))\
    if settings.pages_read and position then\
        text = held and (text .. \" · \" .. position) or position\
    end\
    if pages and settings.pages_left then text = T(_(\"%1, %2 to read\"), text, pages - read) end\
    return text\
end\
\
-- Number of read dots out of `count` for `fraction`.\
function M.dotsFilled(fraction, count)\
    return math.max(0, math.min(count, math.floor(fraction * count)))\
end\
\
-- Same texts as the file browser's detailed list. `settings`:\
-- { pages_read = bool, pages_left = bool }.\
function M.progressText(book_info, pages, settings)\
    local status, percent = book_info.status, book_info.percent_finished\
    if status == \"complete\" or status == \"abandoned\" then\
        local done = status == \"complete\"\
        if not pages then return done and _(\"Finished\") or _(\"On hold\") end\
        if done then return T(N_(\"Finished – 1 page\", \"Finished – %1 pages\", pages), pages) end\
        return T(N_(\"On hold – 1 page\", \"On hold – %1 pages\", pages), pages)\
    end\
    if percent then\
        if not pages then return string.format(\"%d %%\", math.floor(100 * percent)) end\
        local text\
        if settings.pages_read then\
            text = T(_(\"Page %1 of %2\"), _round(percent * pages), pages)\
        else\
            text = T(N_(\"%1 % of 1 page\", \"%1 % of %2 pages\", pages), math.floor(100 * percent), pages)\
        end\
        if settings.pages_left then\
            text = T(_(\"%1, %2 to read\"), text, _round(pages - percent * pages))\
        end\
        return text\
    end\
    if pages then return T(N_(\"1 page\", \"%1 pages\", pages), pages) end\
    return nil\
end\
\
-- Dotted bar: `filled` large dots followed by small ones, `pitch` apart and\
-- centred on the widget height. Created on first use.\
local _Dots\
local function _dotsBar(w, h, filled, big, pitch)\
    if not _Dots then\
        local Widget = require(\"ui/widget/widget\")\
        _Dots = Widget:extend{}\
        function _Dots:paintTo(bb, x, y)\
            local AAPaint  = require(\"infra/sui_aa_paint\")\
            local SUIStyle = require(\"features/sui_style\")\
            self.dimen.x, self.dimen.y = x, y\
            local small = math.max(1, math.floor(self.big / 2))\
            local ink = SUIStyle.COLOR.text_primary\
            local read, unread = SUIStyle.accent(ink), ink\
            for i = 1, M.DOT_COUNT do\
                local d = i <= self.filled and self.big or small\
                AAPaint.fillPill(bb, x + (i - 1) * self.pitch + math.floor((self.big - d) / 2),\
                    y + math.floor((self.dimen.h - d) / 2), d, d,\
                    i <= self.filled and read or unread, 255)\
            end\
        end\
    end\
    local Geom = require(\"ui/geometry\")\
    return _Dots:new{ dimen = Geom:new{ w = w, h = h }, filled = filled, big = big, pitch = pitch }\
end\
\
-- \"EPUB  4.5 MB\", with a shade mark for a book that has annotations.\
function M.fileInfoText(filetype, size, annotated, no_provider)\
    if no_provider then return size end\
    local text = (annotated and \"\\u{2592}  \" or \"\") .. filetype\
    return size and (text .. \"  \" .. size) or text\
end\
\
function M.seriesLine(series, index)\
    local text = series:upper()\
    if index then\
        local n = tonumber(index)\
        text = text .. \" - \" .. ((n and n == math.floor(n)) and tostring(math.floor(n)) or tostring(index))\
    end\
    return text\
end\
\
function M.authorsLine(authors)\
    if not authors or authors == \"\" then return nil end\
    return (authors:gsub(\"\\n\", \", \"))\
end\
\
-- Row of a known book. `opts`:\
--   book_info   the file browser's per-book info (status, percent, annotations)\
--   bookinfo    the cached metadata (title, authors, series, pages, cover)\
--   cover_slot  function(bookinfo, dimen) -> widget, slot width; nil without covers\
--   font_size   function(nominal, max) -> size scaled with the row height\
--   settings    { hide_page_info, pages_read, pages_left, hide_file_info, series_mode,\
--                 progress_bar (\"style\" | \"dots\" | nil) }\
--   fileinfo    file type and size text, already isolated for bidi\
function M.build(item, dimen, opts)\
    local Font            = require(\"ui/font\")\
    local Geom            = require(\"ui/geometry\")\
    local HorizontalGroup = require(\"ui/widget/horizontalgroup\")\
    local HorizontalSpan  = require(\"ui/widget/horizontalspan\")\
    local LeftContainer   = require(\"ui/widget/container/leftcontainer\")\
    local OverlapGroup    = require(\"ui/widget/overlapgroup\")\
    local RightContainer  = require(\"ui/widget/container/rightcontainer\")\
    local Screen          = require(\"device\").screen\
    local VerticalGroup   = require(\"ui/widget/verticalgroup\")\
    local VerticalSpan    = require(\"ui/widget/verticalspan\")\
    local BD              = require(\"ui/bidi\")\
    local SUIStyle        = require(\"features/sui_style\")\
    local UI              = require(\"infra/sui_core\")\
\
    local bookinfo, book_info, settings = opts.bookinfo, opts.book_info, opts.settings\
    local pad    = Screen:scaleBySize(10)\
    local gap    = math.max(1, Screen:scaleBySize(2))\
    local color  = SUIStyle.COLOR.text\
    local title_size = math.min(SUIStyle.FS_BODY, opts.font_size(20, 24))\
    local info_size  = math.max(10, math.min(SUIStyle.FS_DETAIL, title_size - 3))\
    local function textHeight(size)\
        return require(\"features/library/sui_list_rows\").lineHeight(Font:getFace(SUIStyle.FACE_REGULAR, size))\
    end\
    local function line(text, size, max_width)\
        return UI.makeColoredText{\
            text      = text,\
            face      = Font:getFace(SUIStyle.FACE_REGULAR, size),\
            fgcolor   = color,\
            max_width = max_width,\
        }\
    end\
\
    -- Right column: progress over file info.\
    local wright, right_w = nil, 0\
    local pages = book_info.pages or bookinfo.pages\
    local right = VerticalGroup:new{ align = \"right\" }\
    local progress = not settings.hide_page_info and M.progressText(book_info, pages, settings)\
\
    -- With the progress bar on, the progress goes under the title and author\
    -- when the row has room for one more line; otherwise it stays on the right.\
    local bar_line = false\
    if settings.progress_bar and not settings.hide_page_info then\
        local heights = {}\
        if settings.series_mode and bookinfo.series then\
            heights[#heights + 1] = textHeight(math.max(9, info_size - 2))\
        end\
        if M.authorsLine(bookinfo.authors) then heights[#heights + 1] = textHeight(info_size) end\
        heights[#heights + 1] = textHeight(info_size)\
        bar_line = require(\"features/library/sui_list_rows\").fitLines(\
            dimen.h - 2 * Screen:scaleBySize(4), textHeight(title_size), heights, gap) == #heights\
    end\
    if progress and not bar_line then right[#right + 1] = line(progress, info_size) end\
    if not settings.hide_file_info and opts.fileinfo then\
        if #right > 0 then right[#right + 1] = VerticalSpan:new{ width = gap } end\
        right[#right + 1] = line(opts.fileinfo, math.max(10, info_size - 1))\
    end\
    if #right > 0 then\
        right_w = right:getSize().w\
        wright = right\
    end\
\
    local wleft, slot_w = nil, 0\
    if opts.cover_slot then wleft, slot_w = opts.cover_slot(bookinfo, dimen) end\
\
    local text_x = slot_w + pad\
    local main_w = dimen.w - text_x - pad - (wright and (right_w + pad) or 0)\
\
    -- Title on one line, cut with an ellipsis.\
    local series = settings.series_mode and bookinfo.series\
        and line(M.seriesLine(bookinfo.series, bookinfo.series_index), math.max(9, info_size - 2), main_w)\
    local authors = M.authorsLine(bookinfo.authors)\
    local wauthors = authors and line(BD.auto(authors), info_size, main_w)\
    local wtitle = UI.makeColoredText{\
        text      = BD.auto(bookinfo.title or item.text or \"\"),\
        lang      = bookinfo.language,\
        face      = Font:getFace(SUIStyle.FACE_REGULAR, title_size),\
        fgcolor   = color,\
        max_width = main_w,\
    }\
    local wmain = VerticalGroup:new{ align = \"left\", wtitle }\
    if series then\
        wmain[#wmain + 1] = VerticalSpan:new{ width = gap }\
        wmain[#wmain + 1] = series\
    end\
    if wauthors then\
        wmain[#wmain + 1] = VerticalSpan:new{ width = gap }\
        wmain[#wmain + 1] = wauthors\
    end\
\
    if bar_line then\
        local fraction = M.barFraction(book_info)\
        local info_h = textHeight(info_size)\
        -- The bar fills the title's width left by the text beside it.\
        local wbar_text = line(M.barText(book_info, pages, settings), info_size, math.floor(main_w / 2))\
        local bar_w = main_w - pad - wbar_text:getSize().w\
        local bar\
        if settings.progress_bar == \"dots\" then\
            local big = math.max(2, math.floor(info_h * 0.4))\
            local pitch = math.max(1, math.min(math.floor(big * 1.6),\
                math.floor((bar_w - big) / (M.DOT_COUNT - 1))))\
            bar_w = (M.DOT_COUNT - 1) * pitch + big\
            bar = _dotsBar(bar_w, info_h, M.dotsFilled(fraction, M.DOT_COUNT), big, pitch)\
        else\
            bar = UI.progressBar(bar_w, fraction, math.max(2, math.floor(info_h / 3)))\
        end\
        local progress_row = HorizontalGroup:new{ align = \"center\", bar }\
        progress_row[2] = HorizontalSpan:new{ width = pad }\
        progress_row[3] = wbar_text\
        wmain[#wmain + 1] = VerticalSpan:new{ width = gap }\
        wmain[#wmain + 1] = progress_row\
    end\
\
    -- The cover slot stays the first child: the native description hint is\
    -- drawn on the border of row[1][1].\
    local row = OverlapGroup:new{ dimen = dimen:copy() }\
    if wleft then row[#row + 1] = wleft end\
    row[#row + 1] = LeftContainer:new{\
        dimen = dimen:copy(),\
        HorizontalGroup:new{ HorizontalSpan:new{ width = text_x }, wmain },\
    }\
    if wright then\
        row[#row + 1] = RightContainer:new{\
            dimen = Geom:new{ w = dimen.w, h = dimen.h },\
            wright,\
        }\
    end\
    return row\
end\
\
return M\
",
    ["features/library/sui_collection_rows"] = "-- sui_collection_rows.lua — Simple UI\
-- Rows of the collections list in the style of the folder rows of the detailed\
-- list: name over an info line (markers and book count), with a chevron, or a\
-- checkbox in select mode.\
--\
-- Public API:\
--   CollectionRows.infoText(marker, count)   -- \"★ · 12 books\", \"12 books\"\
--   CollectionRows.isActive()                -- true while the Library list rows are SimpleUI's\
--   CollectionRows.getPerPage() / setPerPage(n) -- portrait rows per page of the list; redraws an open list\
--   CollectionRows.PER_PAGE_DEFAULT          -- portrait rows per page the list starts with\
--   CollectionRows.perPage(menu)             -- rows per page, as the detailed list gets\
--   CollectionRows.updateItems(menu, ...)    -- Menu.updateItems, then restyles the rows\
\
local _ = require(\"infra/sui_i18n\").translate\
local T = require(\"ffi/util\").template\
local ListRows = require(\"features/library/sui_list_rows\")\
\
local M = {}\
\
function M.infoText(marker, count)\
    local text = ListRows.countText(count, 0)\
    return marker and T(_(\"%1 · %2\"), marker, text) or text\
end\
\
function M.isActive()\
    local FolderCovers = package.loaded[\"features/library/sui_foldercovers\"]\
    return FolderCovers ~= nil and FolderCovers.isEnabled()\
end\
\
-- Range of the native portrait list setting.\
M.PER_PAGE_MIN, M.PER_PAGE_MAX = 4, 20\
M.PER_PAGE_DEFAULT = 7\
local PER_PAGE_KEY = \"simpleui_lib_per_page_collections\"\
\
function M.getPerPage()\
    local n = tonumber(require(\"infra/sui_store\"):readSetting(PER_PAGE_KEY))\
    if n and n >= M.PER_PAGE_MIN and n <= M.PER_PAGE_MAX then return math.floor(n) end\
    return M.PER_PAGE_DEFAULT\
end\
\
-- Redraws the collections list of every open file manager or reader that\
-- uses these rows.\
local function _refreshOpen()\
    for _i, name in ipairs{ \"apps/filemanager/filemanager\", \"apps/reader/readerui\" } do\
        local app = package.loaded[name]\
        local manager = app and app.instance and app.instance.collections\
        local list = manager and manager.coll_list\
        if list and rawget(list, \"updateItems\") == M.updateItems then list:updateItems(1) end\
    end\
end\
\
-- The default value is not stored.\
function M.setPerPage(n)\
    local SUISettings = require(\"infra/sui_store\")\
    if n and n ~= M.PER_PAGE_DEFAULT then\
        SUISettings:saveSetting(PER_PAGE_KEY, n)\
    else\
        SUISettings:delSetting(PER_PAGE_KEY)\
    end\
    _refreshOpen()\
end\
\
-- The list's items per page in portrait, adjusted in landscape so the rows\
-- keep the portrait height, as the detailed list does.\
function M.perPage(menu)\
    local Math   = require(\"optmath\")\
    local Screen = require(\"device\").screen\
    local Size   = require(\"ui/size\")\
    local avail  = menu.available_height\
    local per_page = M.getPerPage()\
    if Screen:getWidth() > Screen:getHeight() then\
        local others = menu.inner_dimen.h - avail\
        local portrait_avail = Screen:getWidth() - others - Size.line.thin\
        local portrait_h = math.floor(portrait_avail / per_page) - Size.line.thin\
        per_page = Math.round(avail / portrait_h)\
    end\
    return math.max(1, per_page)\
end\
\
-- Hides the resting line of a row; a focused row keeps its focus underline.\
function M.hideLine(item, uc, hidden, focus_color)\
    item.line_color = hidden\
    if not (uc.color == focus_color) then uc.color = hidden end\
end\
\
-- Replaces the content of every row of the page with the list folder row.\
-- A row without the expected layout keeps the native look.\
local function decorate(menu)\
    local Blitbuffer  = require(\"ffi/blitbuffer\")\
    local Geom        = require(\"ui/geometry\")\
    local Size        = require(\"ui/size\")\
    local BD          = require(\"ui/bidi\")\
    local util        = require(\"util\")\
    local SUIStyle    = require(\"features/sui_style\")\
    local FMColl      = require(\"apps/filemanager/filemanagercollection\")\
    local ReadCollection = require(\"readcollection\")\
\
    local manager = menu._manager\
    local selecting = manager and manager.selected_collections ~= nil\
    local group = menu.item_group\
    local last = #group\
    for i, item in ipairs(group) do\
        local uc, entry = item._underline_container, item.entry\
        if uc and entry and entry.name then\
            local info = M.infoText(FMColl.getCollMarker(entry.name),\
                util.tableSize(ReadCollection.coll[entry.name] or {}))\
            local glyph = selecting\
                and SUIStyle.selectionIcon(false, entry.mandatory == manager.checkmark)\
                or SUIStyle.icon(\"chevron\")\
            uc.linesize = Size.line.thin\
            item.underline_h = 0\
            local dimen = Geom:new{ w = uc.dimen.w, h = item.dimen.h - uc.linesize }\
            ListRows.setContent(item, ListRows.trailingRow(dimen, glyph, function(main_w)\
                return ListRows.lines(BD.auto(entry.text), info, dimen, main_w)\
            end))\
            -- The line under the last row is hidden: lines only divide rows.\
            if i == last then\
                M.hideLine(item, uc, SUIStyle.COLOR.surface, Blitbuffer.COLOR_BLACK)\
            end\
        end\
    end\
end\
\
function M.updateItems(menu, ...)\
    local Menu = require(\"ui/widget/menu\")\
    if not menu.available_height then menu:_recalculateDimen() end\
    menu.items_per_page = M.perPage(menu)\
    local result = Menu.updateItems(menu, ...)\
    decorate(menu)\
    return result\
end\
\
return M\
",
    ["features/library/sui_folder_fan"] = "-- sui_folder_fan.lua — Simple UI\
-- Fan of member covers on a folder row of the list with covers.\
--\
-- Public API:\
--   FolderFan.MAX, FolderFan.STEP, FolderFan.ART_SHARE -- cards in a fan, card offset (fraction of a card), max row share\
--   FolderFan.getMode() / setMode(v)       -- \"fan\" (default) or \"single\"\
--   FolderFan.geometry(row_w, row_h, o)    -- card size and offsets, or nil when the row is too short\
--   FolderFan.width(g, n)                  -- width of a fan of n cards\
--   FolderFan.build(cards, g)              -- the fan widget; cards[1] is the front card\
\
local M = {}\
\
M.MAX       = 4\
M.STEP      = 0.28\
M.ART_SHARE = 0.5\
\
local MODE_KEY = \"simpleui_fc_list_folder_covers\"\
\
function M.getMode()\
    return require(\"infra/sui_config\").readChoice(MODE_KEY, { \"fan\", \"single\" }, \"fan\")\
end\
\
-- The default mode is not stored.\
function M.setMode(v)\
    local SUISettings = require(\"infra/sui_store\")\
    if v == \"fan\" then\
        SUISettings:delSetting(MODE_KEY)\
    else\
        SUISettings:saveSetting(MODE_KEY, v)\
    end\
end\
\
-- Card geometry for a row of row_w × row_h. `o`: margin (above and below the\
-- fan), shadow (px a card gives up on its right and bottom), border, min_h\
-- (smallest card height), uniform (covers fill a 2:3 card). The card is the same for any number of covers; the\
-- fan of MAX cards takes at most ART_SHARE of the row. Nil below min_h.\
function M.geometry(row_w, row_h, o)\
    local box_h  = row_h - 2 * o.margin\
    local card_h = box_h - o.shadow\
    local card_w = math.floor(card_h / 1.5)\
    local span   = 1 + (M.MAX - 1) * M.STEP\
    local budget = math.floor(row_w * M.ART_SHARE)\
    if card_w * span + o.shadow > budget then\
        card_w = math.floor((budget - o.shadow) / span)\
        card_h = math.floor(card_w * 1.5)\
    end\
    if card_h < o.min_h then return nil end\
    return {\
        card_w = card_w,\
        card_h = card_h,\
        step   = math.max(1, 2 * o.shadow, math.floor(card_w * M.STEP)),\
        shadow = o.shadow,\
        border = o.border,\
        uniform = o.uniform,\
        top    = o.margin + math.floor((box_h - o.shadow - card_h) / 2),\
    }\
end\
\
function M.width(g, n)\
    n = math.max(1, math.min(n, M.MAX))\
    return g.card_w + (n - 1) * g.step + g.shadow\
end\
\
-- Framed card of one cover: `card.bb` (cover buffer of card.w × card.h;\
-- `card.shared` marks one that belongs to BookInfoManager and must outlive the\
-- widget) or the generated cover for `card.title`.\
local function _card(card, g)\
    local FrameContainer = require(\"ui/widget/container/framecontainer\")\
    local max_w, max_h = g.card_w - 2 * g.border, g.card_h - 2 * g.border\
    local inner, inner_w, inner_h\
    if card.bb then\
        inner = require(\"features/library/sui_cover_widgets\").fitCover(\
            card.bb, card.w, card.h, max_w, max_h, g.uniform, not card.shared)\
        local size = inner:getSize()\
        inner_w, inner_h = size.w, size.h\
    else\
        local Placeholder = require(\"engines/sui_cover_placeholder\")\
        inner_w, inner_h = Placeholder.fitSize(max_w, max_h)\
        inner = Placeholder.build(inner_w, inner_h, card.title)\
    end\
    return FrameContainer:new{\
        width      = inner_w + 2 * g.border,\
        height     = inner_h + 2 * g.border,\
        margin     = 0,\
        padding    = 0,\
        bordersize = g.border,\
        inner,\
    }\
end\
\
-- Outline of the cards together, as columns (see engines/sui_cover_shadow):\
-- every card stands on the fan's bottom edge.\
local function _outline(frames, g)\
    local w = 0\
    for _i, f in ipairs(frames) do w = math.max(w, f.x + f.w) end\
    local tops, heights, key = {}, {}, { \"fan\" }\
    for x = 1, w do tops[x], heights[x] = g.card_h, 0 end\
    for _i, f in ipairs(frames) do\
        local top = g.card_h - f.h\
        for x = f.x + 1, f.x + f.w do\
            if top < tops[x] then tops[x], heights[x] = top, f.h end\
        end\
        key[#key + 1] = f.x .. \",\" .. f.w .. \",\" .. f.h\
    end\
    return { key = table.concat(key, \"|\"), w = w, tops = tops, heights = heights }\
end\
\
-- Cards from the back to the front, each a step to the right of the one in\
-- front, over one shadow cast by the whole fan.\
function M.build(cards, g)\
    local Geom         = require(\"ui/geometry\")\
    local OverlapGroup = require(\"ui/widget/overlapgroup\")\
    local Shadow       = require(\"engines/sui_cover_shadow\")\
    local n = math.min(#cards, M.MAX)\
    local frames = {}\
    for i = 1, n do\
        local frame = _card(cards[i], g)\
        local size = frame:getSize()\
        frames[i] = { widget = frame, x = (i - 1) * g.step, w = size.w, h = size.h }\
    end\
    local group = OverlapGroup:new{\
        dimen = Geom:new{ w = M.width(g, n), h = g.card_h + g.shadow },\
        allow_mirroring = false,\
    }\
    local outline = _outline(frames, g)\
    local shadow = Shadow.buildWidget(outline.w, g.card_h, g.shadow, outline)\
    if shadow then\
        shadow.overlap_offset = { 0, 0 }\
        group[1] = shadow\
    end\
    for i = n, 1, -1 do\
        local f = frames[i]\
        f.widget.overlap_offset = { f.x, g.card_h - f.h }\
        group[#group + 1] = f.widget\
    end\
    return group\
end\
\
return M\
",
    ["features/library/sui_list_rows"] = "-- sui_list_rows.lua — Simple UI\
-- Text rows of the detailed list views: a name over an info line, with an\
-- optional trailing glyph. Shared by the folder rows and the collection rows.\
--\
-- Public API:\
--   ListRows.fontSize(dimen_h, nominal, max)            -- font size scaled with the row height\
--   ListRows.fitLines(avail_h, name_h, line_hs, gap)    -- how many secondary lines fit under the name\
--   ListRows.countText(books, dirs)                     -- \"12 books\", \"3 folders · 12 books\"\
--   ListRows.lines(name, info, dimen, main_w, opts)     -- name and info line stacked in main_w\
--   ListRows.glyphWidget(dimen, glyph)                  -- trailing glyph and the width it reserves\
--   ListRows.trailingRow(dimen, glyph, build)           -- lines from build(main_w) plus a trailing glyph\
--   ListRows.setContent(item, widget)                   -- swaps the content of a list row\
\
local _ = require(\"infra/sui_i18n\").translate\
local N_ = require(\"infra/sui_i18n\").ngettext\
local T = require(\"ffi/util\").template\
\
local M = {}\
\
local line_heights = setmetatable({}, { __mode = \"k\" })\
\
function M.lineHeight(face)\
    local height = line_heights[face]\
    if not height then\
        local probe = require(\"ui/widget/textwidget\"):new{ text = \"Ag\", face = face }\
        height = probe:getSize().h\
        probe:free()\
        line_heights[face] = height\
    end\
    return height\
end\
\
-- Gap between the lines and side padding of a row, in scaled px.\
local function _gap() return math.max(1, require(\"device\").screen:scaleBySize(1)) * 2 end\
local function _pad() return require(\"device\").screen:scaleBySize(10) end\
\
-- Same ratio the stock list uses to convert a nominal (64px-reference) font\
-- size into a scaled one, so row text matches the book rows.\
function M.fontSize(dimen_h, nominal, max)\
    local scale = require(\"device\").screen:scaleBySize(1000000) * (1/1000000)\
    local font_size = math.floor(nominal * dimen_h * (1/64) / scale)\
    if max and font_size >= max then return max end\
    return font_size\
end\
\
-- Number of secondary lines (`line_hs`, in display order) that fit under a\
-- name of height `name_h` in `avail_h`; the last ones are dropped first.\
function M.fitLines(avail_h, name_h, line_hs, gap)\
    local used, fit = name_h, 0\
    for i, h in ipairs(line_hs) do\
        used = used + gap + h\
        if used > avail_h then break end\
        fit = i\
    end\
    return fit\
end\
\
function M.countText(books, dirs)\
    local text = T(N_(\"%1 book\", \"%1 books\", books), books)\
    if dirs > 0 then\
        text = T(_(\"%1 · %2\"), T(N_(\"%1 folder\", \"%1 folders\", dirs), dirs), text)\
    end\
    return text\
end\
\
-- Name and info line stacked and left aligned in `main_w`, in fixed font\
-- sizes. The lines that do not fit the row are dropped, the info first and\
-- then the author; the name takes the room the others leave and is cut with\
-- an ellipsis. `info` is a string, or nil to show `opts.fallback` in the mono\
-- face. `opts`: author (line under the name), fallback.\
function M.lines(name, info, dimen, main_w, opts)\
    opts = opts or {}\
    local Font            = require(\"ui/font\")\
    local Geom            = require(\"ui/geometry\")\
    local LeftContainer   = require(\"ui/widget/container/leftcontainer\")\
    local TextBoxWidget   = require(\"ui/widget/textboxwidget\")\
    local TextWidget      = require(\"ui/widget/textwidget\")\
    local VerticalGroup   = require(\"ui/widget/verticalgroup\")\
    local VerticalSpan    = require(\"ui/widget/verticalspan\")\
    local UI              = require(\"infra/sui_core\")\
    local SUIStyle        = require(\"features/sui_style\")\
\
    local title_face = Font:getFace(SUIStyle.FACE_REGULAR, SUIStyle.FS_BODY)\
    local info_face  = Font:getFace(SUIStyle.FACE_REGULAR, SUIStyle.FS_DETAIL)\
    local function infoLine(text)\
        return UI.makeColoredText{\
            text      = text,\
            face      = info_face,\
            fgcolor   = SUIStyle.COLOR.text,\
            max_width = main_w,\
        }\
    end\
\
    local winfo = info and infoLine(info) or TextWidget:new{\
        text = opts.fallback or \"\",\
        face = Font:getFace(SUIStyle.FACE_MONO, SUIStyle.FS_DETAIL),\
    }\
    local wauthor = opts.author and infoLine(opts.author)\
\
    local gap  = _gap()\
    local line_h = M.lineHeight(title_face)\
\
    -- Secondary lines in display order; the ones past `fit` are dropped.\
    local extras, heights = {}, {}\
    if wauthor then extras[#extras + 1] = wauthor end\
    extras[#extras + 1] = winfo\
    for i, w in ipairs(extras) do heights[i] = w:getSize().h end\
    local avail = dimen.h\
    local fit = M.fitLines(avail, line_h, heights, gap)\
    local kept_h = 0\
    for i = #extras, fit + 1, -1 do extras[i]:free() end\
    for i = 1, fit do kept_h = kept_h + gap + heights[i] end\
    local show_author = wauthor and fit >= 1\
    local show_info   = fit == #extras\
\
    local wname = TextBoxWidget:new{\
        text                          = name,\
        face                          = title_face,\
        width                         = main_w,\
        alignment                     = \"left\",\
        height                        = math.max(line_h, avail - kept_h),\
        height_adjust                 = true,\
        height_overflow_show_ellipsis = true,\
    }\
\
    local lines = VerticalGroup:new{ align = \"left\", wname }\
    if show_author then\
        lines[#lines + 1] = VerticalSpan:new{ width = gap }\
        lines[#lines + 1] = wauthor\
    end\
    if show_info then\
        lines[#lines + 1] = VerticalSpan:new{ width = gap }\
        lines[#lines + 1] = winfo\
    end\
    return LeftContainer:new{ dimen = Geom:new{ w = main_w, h = dimen.h }, lines }\
end\
\
-- Trailing glyph of a row of `dimen`, and the width it takes from the text\
-- (glyph plus the gap before it).\
function M.glyphWidget(dimen, glyph)\
    local UI       = require(\"infra/sui_core\")\
    local SUIStyle = require(\"features/sui_style\")\
    local wglyph = UI.makeColoredText{\
        text    = glyph,\
        face    = SUIStyle.glyphFace(math.floor(dimen.h * 0.3)),\
        fgcolor = SUIStyle.COLOR.text,\
    }\
    return wglyph, wglyph:getSize().w + _pad()\
end\
\
-- Row of `build(main_w)` followed by a trailing `glyph` at the end of the row.\
function M.trailingRow(dimen, glyph, build)\
    local HorizontalGroup = require(\"ui/widget/horizontalgroup\")\
    local HorizontalSpan  = require(\"ui/widget/horizontalspan\")\
\
    local wglyph, reserved = M.glyphWidget(dimen, glyph)\
    return HorizontalGroup:new{\
        align = \"center\",\
        build(dimen.w - reserved),\
        HorizontalSpan:new{ width = _pad() },\
        wglyph,\
    }\
end\
\
-- Puts `widget` inside the row's underline container, below its top line.\
function M.setContent(item, widget)\
    local VerticalGroup = require(\"ui/widget/verticalgroup\")\
    local VerticalSpan  = require(\"ui/widget/verticalspan\")\
    local underline_h = item.underline_h or 1\
    if item._underline_container[1] then item._underline_container[1]:free() end\
    item._underline_container[1] = VerticalGroup:new{\
        VerticalSpan:new{ width = underline_h },\
        widget,\
    }\
end\
\
return M\
",
    ["features/library/sui_tab_views"] = "-- sui_tab_views.lua — Simple UI\
-- View and sort of each metadata tab (Authors / Series / Tags) of the library.\
--\
-- Every tab keeps its own view and sort for its root list. The books inside a\
-- group follow the Library tab, i.e. KOReader's own settings.\
--\
--   TabViews.getView(mode) / setView(mode, view)      a CoverBrowser display mode id of VIEWS\
--   TabViews.getSort(mode) / setSort(mode, id)        a collate id of SORTS\
--   TabViews.isReverse(mode) / setReverse(mode, on)\
--   TabViews.getPerPage(mode) / setPerPage(mode, n)   portrait items per page of a tab listed as a list\
--   TabViews.defaultPerPage(mode)                     items per page a tab starts with\
--   TabViews.isListView(view)                         whether a view is a list\
--   TabViews.pagePerPage(path)                        items per page a tab root forces, else nil\
--   TabViews.cbMode(view)                             CoverBrowser display mode of a view (the view itself)\
--   TabViews.rootMode(path)                           tab whose root list `path` is, else nil\
--   TabViews.isCoverRoot(path)                        whether `path` is a tab root listed with covers\
--   TabViews.dirSorter(fc, mode)                      sort function of a tab's root list\
--   TabViews.libraryMode()                            display mode the Library tab uses\
--   TabViews.effectiveMode(path)                      display mode `path` is shown in\
--   TabViews.apply(fc, path)                          switch the file browser to that mode\
--   TabViews.install() / uninstall()                  apply it before every refresh of the list\
--\
-- The CoverBrowser's \"Display mode\" menu also lists the view of each tab.\
\
local Config      = require(\"infra/sui_config\")\
local SUISettings = require(\"infra/sui_store\")\
local _           = require(\"infra/sui_i18n\").translate\
\
local M = {}\
\
M.META_MODES = { \"author\", \"series\", \"tags\" }\
M.VIEWS      = { \"mosaic_image\", \"mosaic_text\", \"list_image_meta\", \"list_only_meta\", \"list_image_filename\" }\
M.SORTS      = { \"strcoll\", \"natural\", \"sui_count\" }\
\
local DEFAULT_VIEW = { author = \"list_only_meta\", series = \"list_image_meta\", tags = \"list_only_meta\" }\
\
-- Views saved when they were named after their look.\
local LEGACY_VIEW = { mosaic = \"mosaic_image\", list = \"list_only_meta\", list_covers = \"list_image_meta\" }\
\
local function _key(kind, mode) return \"simpleui_lib_\" .. kind .. \"_\" .. mode end\
\
function M.getView(mode)\
    local stored = SUISettings:readSetting(_key(\"view\", mode))\
    return Config.resolveChoice(LEGACY_VIEW[stored] or stored, M.VIEWS, DEFAULT_VIEW[mode] or \"list_only_meta\")\
end\
\
function M.setView(mode, view)\
    SUISettings:saveSetting(_key(\"view\", mode), view)\
end\
\
-- Without a saved choice a tab starts from the file browser's collate, when it\
-- can order metadata folders.\
function M.getSort(mode)\
    local SortSheet = require(\"features/library/sui_sort_sheet\")\
    local global    = G_reader_settings:readSetting(\"collate\")\
    local default   = SortSheet.sortsFacetFolders(global) and global or \"strcoll\"\
    return Config.readChoice(_key(\"sort\", mode), M.SORTS, default)\
end\
\
function M.setSort(mode, id)\
    SUISettings:saveSetting(_key(\"sort\", mode), id)\
end\
\
function M.isReverse(mode)\
    local stored = SUISettings:readSetting(_key(\"reverse\", mode))\
    if stored == nil then return G_reader_settings:isTrue(\"reverse_collate\") end\
    return stored == true\
end\
\
function M.setReverse(mode, on)\
    SUISettings:saveSetting(_key(\"reverse\", mode), on and true or false)\
end\
\
-- Range of items per page of a tab listed as a list; a stored value above it is capped.\
M.PER_PAGE_MIN, M.PER_PAGE_MAX = 4, 12\
local PER_PAGE_DEFAULTS = { author = 6, series = 6, tags = 6 }\
\
function M.isListView(view)\
    return view:sub(1, 5) == \"list_\"\
end\
\
function M.defaultPerPage(mode)\
    return PER_PAGE_DEFAULTS[mode]\
end\
\
function M.getPerPage(mode)\
    local n = tonumber(SUISettings:readSetting(_key(\"per_page\", mode)))\
    if n and n >= M.PER_PAGE_MIN then return math.min(math.floor(n), M.PER_PAGE_MAX) end\
    return PER_PAGE_DEFAULTS[mode]\
end\
\
-- The default value is not stored.\
function M.setPerPage(mode, n)\
    if n and n ~= PER_PAGE_DEFAULTS[mode] then\
        SUISettings:saveSetting(_key(\"per_page\", mode), n)\
    else\
        SUISettings:delSetting(_key(\"per_page\", mode))\
    end\
end\
\
function M.cbMode(view)\
    return view\
end\
\
-- The tab (`author`/`series`/`tags`) whose top-level list `path` is. A list\
-- narrowed by an earlier filter is not a tab root.\
function M.rootMode(path)\
    local _base, state, dimension, level = require(\"features/library/sui_virtual_path\").parse(path)\
    if level ~= \"dim_list\" or not (state and #state.trail == 0) then return nil end\
    for _i, mode in ipairs(M.META_MODES) do\
        if mode == dimension then return mode end\
    end\
    return nil\
end\
\
function M.isCoverRoot(path)\
    local mode = M.rootMode(path)\
    return mode ~= nil and M.getView(mode) == \"list_image_meta\"\
end\
\
function M.pagePerPage(path)\
    local mode = M.rootMode(path)\
    if mode and M.isListView(M.getView(mode)) then return M.getPerPage(mode) end\
    return nil\
end\
\
function M.dirSorter(fc, mode)\
    return fc:getSortingFunction(fc.collates[M.getSort(mode)] or fc.collates.strcoll, M.isReverse(mode))\
end\
\
-- ---------------------------------------------------------------------------\
-- Display mode per path\
-- ---------------------------------------------------------------------------\
\
-- The file browser has one display mode at a time, set on the CoverBrowser. A\
-- tab root switches it without saving it, so the saved mode stays the\
-- Library's and every other path shows that one.\
local _applied            -- mode the CoverBrowser is in\
local _seen_library = false -- saved mode at the last apply; false before the first\
\
local function _bookInfo()\
    local ok, bim = pcall(require, \"bookinfomanager\")\
    return ok and bim or nil\
end\
\
-- The CoverBrowser of the chooser's file manager, which exists before\
-- FileManager.instance does when a new file manager lists its first folder.\
local function _coverBrowser(fc)\
    local FM = package.loaded[\"apps/filemanager/filemanager\"]\
    local fm = FM and FM.instance\
    local cb = fc and fc.ui and fc.ui.coverbrowser or fm and fm.coverbrowser\
    return cb, fm\
end\
\
function M.libraryMode()\
    local bim = _bookInfo()\
    return bim and bim:getSetting(\"filemanager_display_mode\") or nil\
end\
\
function M.effectiveMode(path)\
    local mode = M.rootMode(path)\
    if mode then return M.cbMode(M.getView(mode)) end\
    return M.libraryMode()\
end\
\
-- Sets the CoverBrowser's mode without saving it and without its own refresh.\
local function _switch(cb, mode)\
    local bim = _bookInfo()\
    if not (cb and bim) then return false end\
    local orig_save    = bim.saveSetting\
    local own_refresh  = rawget(cb, \"refreshFileManagerInstance\")\
    bim.saveSetting = function(self, key, value)\
        if key == \"filemanager_display_mode\" then return end\
        return orig_save(self, key, value)\
    end\
    cb.refreshFileManagerInstance = function() end\
    local ok = pcall(cb.setupFileManagerDisplayMode, cb, mode)\
    bim.saveSetting = orig_save\
    cb.refreshFileManagerInstance = own_refresh\
    return ok\
end\
\
-- A mode saved since the last call was chosen in the native menu, which puts\
-- the CoverBrowser in it.\
local function _sync()\
    local library = M.libraryMode()\
    if library ~= _seen_library then\
        _seen_library = library\
        _applied = library\
    end\
    return library\
end\
\
local function _isView(mode)\
    for _i, view in ipairs(M.VIEWS) do\
        if view == mode then return true end\
    end\
    return false\
end\
\
-- The display mode chosen in the CoverBrowser's menu at a tab root is the\
-- tab's view; anywhere else, or the classic mode, it is the Library's. The\
-- CoverBrowser ignores a choice equal to the mode it is in, which at a tab root\
-- is the tab's; so it is put back in the Library's mode first. A classic mode\
-- chosen at a tab root then redraws the list once, in the tab's view.\
local _wrapped_cb\
\
local function _wrapSetDisplayMode(cb)\
    if rawget(cb, \"setDisplayMode\") then return end\
    local orig = cb.setDisplayMode\
    cb.setDisplayMode = function(self, mode)\
        local fc = self.ui and self.ui.file_chooser\
        local root = fc and M.rootMode(fc.path)\
        if root and _isView(mode) then\
            M.setView(root, mode)\
            return fc:refreshPath()\
        end\
        local library = _sync()\
        if _applied ~= library and _switch(self, library) then _applied = library end\
        if not root then return orig(self, mode) end\
        local own_refresh = rawget(self, \"refreshFileManagerInstance\")\
        self.refreshFileManagerInstance = function() end\
        local ok, err = pcall(orig, self, mode)\
        self.refreshFileManagerInstance = own_refresh\
        if not ok then error(err, 0) end\
        fc:refreshPath()\
    end\
    _wrapped_cb = cb\
end\
\
-- Items added to the file manager's \"Display mode\" menu, and its relabelled\
-- \"Use this mode everywhere\" item, kept to be taken out on uninstall.\
local _menu_patch\
\
local TAB_MENU_LABELS = {\
    author = _(\"Authors display mode\"),\
    series = _(\"Series display mode\"),\
    tags   = _(\"Tags display mode\"),\
}\
\
local function _tabMenuItem(fm, mode)\
    local SortSheet = require(\"features/library/sui_sort_sheet\")\
    local sub = {}\
    for i, option in ipairs(SortSheet.viewOptions(fm, mode)) do\
        sub[i] = {\
            text         = option.text,\
            radio        = true,\
            checked_func = function() return SortSheet.getView(fm, mode) == option.id end,\
            callback     = function() SortSheet.setView(fm, mode, option.id) end,\
        }\
    end\
    return { text = TAB_MENU_LABELS[mode], sub_item_table = sub }\
end\
\
local function _unpatchMenu()\
    local patch = _menu_patch\
    if not patch then return end\
    _menu_patch = nil\
    local sub = patch.sub\
    for i = #sub, 1, -1 do\
        for _j, item in ipairs(patch.items) do\
            if sub[i] == item then table.remove(sub, i); break end\
        end\
    end\
    if patch.label_item then patch.label_item.text = patch.label_text end\
end\
\
-- Extends the \"Display mode\" menu of the file manager's own menu only, not of\
-- the copies other menus build to read its items.\
local function _patchMenu(cb, menu_items)\
    local fm = cb.ui\
    local entry = menu_items.filemanager_display_mode\
    if not (fm and fm.menu and fm.menu.menu_items == menu_items\
            and type(entry) == \"table\" and type(entry.sub_item_table) == \"table\") then\
        return\
    end\
    _unpatchMenu()\
    local sub = entry.sub_item_table\
    local patch = { sub = sub, items = {} }\
    local everywhere = require(\"gettext\")(\"Use this mode everywhere\")\
    for _i, item in ipairs(sub) do\
        if item.text == everywhere then\
            patch.label_item, patch.label_text = item, item.text\
            item.text = _(\"Also use this mode in History and Collections\")\
            break\
        end\
    end\
    for _i, mode in ipairs(M.META_MODES) do\
        local item = _tabMenuItem(fm, mode)\
        sub[#sub + 1] = item\
        patch.items[#patch.items + 1] = item\
    end\
    _menu_patch = patch\
end\
\
local function _wrapAddToMainMenu(cb)\
    if rawget(cb, \"addToMainMenu\") then return end\
    local orig = cb.addToMainMenu\
    cb.addToMainMenu = function(self, menu_items)\
        orig(self, menu_items)\
        _patchMenu(self, menu_items)\
    end\
end\
\
-- A tab root with items per page of its own lends them to the chooser only\
-- while its dimensions are computed, so every setting keeps reading the\
-- Library's. The chooser's own instance layout, if any, still runs.\
local function _recalcWithPerPage(self, ...)\
    local own = rawget(self, \"files_per_page\")\
    self.files_per_page = self._sui_tv_per_page\
    local layout = self._sui_tv_own_recalc or require(\"ui/widget/filechooser\")._recalculateDimen\
    local ok, err = pcall(layout, self, ...)\
    self.files_per_page = own\
    if not ok then error(err, 0) end\
end\
\
-- Returns true when the items per page of `fc` changed. The instance layout\
-- the chooser had is kept aside while lent and put back after.\
local function _setPerPage(fc, n)\
    if fc._sui_tv_per_page == n then return false end\
    if n and not fc._sui_tv_per_page then\
        fc._sui_tv_own_recalc = rawget(fc, \"_recalculateDimen\")\
        fc._recalculateDimen = _recalcWithPerPage\
    elseif not n then\
        fc._recalculateDimen = fc._sui_tv_own_recalc\
        fc._sui_tv_own_recalc = nil\
    end\
    fc._sui_tv_per_page = n\
    return true\
end\
\
function M.apply(fc, path)\
    _sync()\
    local cb = _coverBrowser(fc)\
    if cb then\
        _wrapSetDisplayMode(cb)\
        _wrapAddToMainMenu(cb)\
    end\
    local resized = fc and _setPerPage(fc, M.pagePerPage(path))\
    local want = M.effectiveMode(path)\
    local switched = want ~= _applied and _switch(cb, want)\
    if switched then _applied = want end\
    if (switched or resized) and fc and fc._recalculateDimen then fc:_recalculateDimen() end\
end\
\
function M.install()\
    local FileChooser = require(\"ui/widget/filechooser\")\
    if FileChooser._sui_tv_orig_refreshPath then return end\
    local orig = FileChooser.refreshPath\
    FileChooser._sui_tv_orig_refreshPath = orig\
    FileChooser.refreshPath = function(fc, ...)\
        if fc.name == \"filemanager\" then M.apply(fc, fc.path) end\
        return orig(fc, ...)\
    end\
end\
\
function M.uninstall()\
    local FileChooser = require(\"ui/widget/filechooser\")\
    local orig = FileChooser._sui_tv_orig_refreshPath\
    if orig then\
        FileChooser.refreshPath = orig\
        FileChooser._sui_tv_orig_refreshPath = nil\
    end\
    local known = _wrapped_cb\
    if known then\
        known.setDisplayMode = nil\
        known.addToMainMenu = nil\
        _wrapped_cb = nil\
    end\
    _unpatchMenu()\
    local live, fm = _coverBrowser()\
    local cb = known or live\
    local library = _sync()\
    local fc = fm and fm.file_chooser\
    local resized = fc and _setPerPage(fc, nil)\
    local switched = _applied ~= library and _switch(cb, library)\
    if (switched or resized) and fc and fc._recalculateDimen then fc:_recalculateDimen() end\
    _applied, _seen_library = nil, false\
end\
\
return M\
",
    ["features/library/cover_editor/sui_cover_net"] = "-- sui_cover_net.lua — Simple UI\
-- Blocking HTTP GET helpers for the online cover search. Requests use\
-- KOReader's socket timeouts and stop reading past a size cap, so a slow or\
-- misbehaving server cannot hang the reader or fill its memory.\
--\
-- Public API\
--   CoverNet.get(url)      -> body | nil, err\
--   CoverNet.getJson(url)  -> table | nil\
--   CoverNet.resetAnswered()\
--   CoverNet.answered()    -> requests a server answered (any HTTP status)\
--                             since resetAnswered(); 0 means none got through\
\
local logger = require(\"logger\")\
\
local CoverNet = {}\
\
-- Largest response body read into memory (a cover is well below this).\
local MAX_BODY = 8 * 1024 * 1024\
\
local answered = 0\
\
function CoverNet.resetAnswered() answered = 0 end\
function CoverNet.answered() return answered end\
\
-- socketutil.table_sink that aborts once more than MAX_BODY bytes came in.\
local function cappedSink(socketutil, chunks)\
    local sink = socketutil.table_sink(chunks)\
    local received = 0\
    return function(chunk, err)\
        if chunk then\
            received = received + #chunk\
            if received > MAX_BODY then return nil, \"response too large\" end\
        end\
        return sink(chunk, err)\
    end\
end\
\
function CoverNet.get(url)\
    local http       = require(\"socket.http\")\
    local socket     = require(\"socket\")\
    local socketutil = require(\"socketutil\")\
    local chunks = {}\
    socketutil:set_timeout(socketutil.LARGE_BLOCK_TIMEOUT, socketutil.LARGE_TOTAL_TIMEOUT)\
    local ok, code = pcall(function()\
        return socket.skip(1, http.request{\
            url      = url,\
            method   = \"GET\",\
            headers  = { [\"User-Agent\"] = socketutil.USER_AGENT },\
            sink     = cappedSink(socketutil, chunks),\
            redirect = true,\
        })\
    end)\
    socketutil:reset_timeout()\
    -- A numeric code is a server's answer; anything else failed on the way.\
    if ok and type(code) == \"number\" then answered = answered + 1 end\
    if not ok then\
        logger.warn(\"SimpleUI cover search: request failed\", url, code)\
        return nil, tostring(code)\
    end\
    if code ~= 200 then\
        logger.dbg(\"SimpleUI cover search: HTTP\", code, url)\
        return nil, \"http \" .. tostring(code)\
    end\
    return table.concat(chunks)\
end\
\
function CoverNet.getJson(url)\
    local body = CoverNet.get(url)\
    if not body then return nil end\
    local ok, data = pcall(require(\"json\").decode, body)\
    if ok and type(data) == \"table\" then return data end\
end\
\
return CoverNet\
",
    ["features/library/cover_editor/sui_cover_search"] = "-- sui_cover_search.lua — Simple UI\
-- \"Search online\" screen of the cover window: a form with the query\
-- (editable) and the Apple Books opt-in, and a Search button. The query is a\
-- title and author, searched with the book's ISBN when it has one, or an\
-- ISBN, which finds only that edition. The covers\
-- found open in a sheet over the window, as pages of thumbnails with their\
-- source and size; a tap selects a cover and the sheet's button applies it.\
--\
-- The search runs behind KOReader's Wi-Fi prompt and a progress notice that\
-- a tap cancels; the covers found until then are kept. Thumbnails are decoded once per search and\
-- freed when replaced or when the window closes; closing the sheet keeps\
-- them, so the results can be shown again without searching.\
--\
-- Public API\
--   local search = CoverSearch.new{ file, book, apply = function(path) end }\
--     apply runs when the sheet's button is tapped, with the chosen image\
--   search:build(ctx)   -> widgets of the screen\
--   search:footer(ctx)  -> footer widget\
--   search:run(ctx)     -- runs the search, then shows the results\
--   search:free()\
\
local CenterContainer = require(\"ui/widget/container/centercontainer\")\
local Device          = require(\"device\")\
local Font            = require(\"ui/font\")\
local FrameContainer  = require(\"ui/widget/container/framecontainer\")\
local Geom            = require(\"ui/geometry\")\
local HorizontalGroup = require(\"ui/widget/horizontalgroup\")\
local HorizontalSpan  = require(\"ui/widget/horizontalspan\")\
local ImageWidget     = require(\"ui/widget/imagewidget\")\
local Size            = require(\"ui/size\")\
local T               = require(\"ffi/util\").template\
local TextWidget      = require(\"ui/widget/textwidget\")\
local VerticalGroup   = require(\"ui/widget/verticalgroup\")\
local VerticalSpan    = require(\"ui/widget/verticalspan\")\
local I18n            = require(\"infra/sui_i18n\")\
local _               = I18n.translate\
local N_              = I18n.ngettext\
local Screen          = Device.screen\
\
local ActionSheet  = require(\"engines/sui_action_sheet\")\
local PageNav      = require(\"engines/sui_page_nav\")\
local SUIWindow    = require(\"engines/sui_window\")\
local SUIStyle     = require(\"features/sui_style\")\
local SUISettings  = require(\"infra/sui_store\")\
local UI           = require(\"infra/sui_core\")\
local CoverSources = require(\"features/library/cover_editor/sui_cover_sources\")\
\
local CoverSearch = {}\
CoverSearch.__index = CoverSearch\
\
local APPLE_KEY = \"simpleui_cover_search_apple\"\
local COVER_ASPECT = 1.5\
local PAGE_ROWS = 2\
\
-- Columns and cell width of a result grid `inner_w` wide.\
local function gridGeometry(ctx, inner_w)\
    local gap      = ctx.SZ(Screen:scaleBySize(8))\
    local min_cell = ctx.SZ(Screen:scaleBySize(90))\
    local cols     = math.max(2, math.min(4, math.floor((inner_w + gap) / (min_cell + gap))))\
    local cell_w   = math.floor((inner_w - gap * (cols - 1)) / cols)\
    return cols, cell_w, math.floor(cell_w * COVER_ASPECT), gap\
end\
\
local function captionFace(ctx)\
    return Font:getFace(SUIStyle.FACE_REGULAR, ctx.SZ(SUIStyle.FS_CAPTION))\
end\
\
function CoverSearch.new(opts)\
    local self = setmetatable({}, CoverSearch)\
    self.apply = opts.apply\
    local book = opts.book\
    self.query = book.authors ~= \"\" and (book.title .. \" \" .. book.authors) or book.title\
    self.isbn  = CoverSources.isbnOf(opts.file)\
    self.results  = nil   -- nil until a search ran\
    self.selected = nil\
    self.page     = 1\
    return self\
end\
\
function CoverSearch:free()\
    if self.sheet then self.sheet:close() end\
    for _i, c in ipairs(self.results or {}) do\
        if c.thumb then c.thumb:free() end\
    end\
    self.results, self.selected = nil, nil\
    CoverSources.clearCache()\
end\
\
function CoverSearch:run(ctx)\
    -- Thumbnails fit the sheet's cells inside the selection frame, so they\
    -- are drawn at their own size.\
    self.sheet_w = SUIWindow.stackedWidth()\
    local _cols, cell_w, cell_h = gridGeometry(ctx, SUIWindow.innerWidth(self.sheet_w))\
    local frame = 2 * Size.border.thick\
    local function search()\
        local typed_isbn = CoverSources.parseIsbn(self.query)\
        UI.Notify.progress(function(progress)\
            return CoverSources.search{\
                query         = typed_isbn and \"\" or self.query,\
                isbn          = typed_isbn or self.isbn,\
                include_apple = SUISettings:isTrue(APPLE_KEY),\
                thumb_w       = cell_w - frame,\
                thumb_h       = cell_h - frame,\
                on_progress   = progress,\
            }\
        end, function(results, cancelled, offline)\
            -- Frees the previous thumbnails; their files were already cleared.\
            for _i, c in ipairs(self.results or {}) do\
                if c.thumb then c.thumb:free() end\
            end\
            -- A search that found nothing because it was cancelled or reached\
            -- no server leaves the form as it was before the first search.\
            local unfinished = #results == 0 and (cancelled or offline)\
            self.results, self.selected, self.page = not unfinished and results or nil, nil, 1\
            ctx.repaint()\
            if unfinished then\
                UI.Notify.toast(cancelled and _(\"Search cancelled\")\
                    or _(\"Could not reach the cover services. Check your connection.\"))\
            elseif #results > 0 then\
                self:showResults()\
            end\
        end)\
    end\
    local NetworkMgr = require(\"infra/sui_config\").getNetworkMgr()\
    if NetworkMgr then\
        -- Connected is enough: without internet the search reports it.\
        NetworkMgr:runWhenConnected(search)\
    else\
        search()\
    end\
end\
\
-- One result: the thumbnail framed (thick frame when selected), then the\
-- source and the image size. The thumbnail is drawn at its own size; it is\
-- only scaled down when the sheet's cells shrank since the search (rotation).\
function CoverSearch:buildCell(ctx, index, cell_w, cell_h)\
    local c = self.results[index]\
    local selected = self.selected == index\
    local border = selected and Size.border.thick or Size.border.thin\
    local thumb_w, thumb_h = c.thumb:getWidth(), c.thumb:getHeight()\
    local scale = math.min(1, (cell_w - 2 * Size.border.thick) / thumb_w,\
        (cell_h - 2 * Size.border.thick) / thumb_h)\
    local image = ImageWidget:new{\
        image            = c.thumb,\
        image_disposable = false,\
        width            = math.max(1, math.floor(thumb_w * scale)),\
        height           = math.max(1, math.floor(thumb_h * scale)),\
    }\
    local face = captionFace(ctx)\
    local cell = VerticalGroup:new{\
        align = \"center\",\
        CenterContainer:new{\
            dimen = Geom:new{ w = cell_w, h = cell_h },\
            FrameContainer:new{\
                bordersize = border,\
                color      = SUIStyle.COLOR.text_primary,\
                padding    = 0,\
                margin     = 0,\
                image,\
            },\
        },\
        VerticalSpan:new{ width = ctx.SZ(Screen:scaleBySize(4)) },\
        TextWidget:new{\
            text      = c.source,\
            face      = face,\
            bold      = selected,\
            max_width = cell_w,\
        },\
        UI.makeColoredText{\
            text      = string.format(\"%d × %d\", c.width, c.height),\
            face      = face,\
            fgcolor   = SUIStyle.COLOR.text_dim,\
            max_width = cell_w,\
        },\
    }\
    return SUIWindow.Input.tapable(cell, {\
        on_tap = function()\
            self.selected = index\
            self.sheet:update{ footer = self:sheetFooter() }\
        end,\
    }, Geom:new{ w = cell_w, h = cell:getSize().h })\
end\
\
-- Centred page indicator with its chevrons; they are D-pad focus stops.\
function CoverSearch:buildPager(ctx, npages)\
    local face  = PageNav.indicatorFace(UI.getLandscapeFactor())\
    local row_h = PageNav.rowHeight(face)\
    local pager, stops = PageNav.buildPager(self.page, npages, row_h,\
        TextWidget:new{ text = string.format(\"%d/%d\", self.page, npages), face = face },\
        Size.padding.large,\
        function(delta)\
            self.page = self.page + delta\
            self.sheet:repaint()\
        end,\
        true)\
    for _i, stop in ipairs(stops) do\
        local _w, focused = SUIWindow.Input.focusStop(stop.widget,\
            { on_select = stop.widget.onTapPageNav })\
        stop.widget._kb_focused = focused\
    end\
    return CenterContainer:new{\
        dimen = Geom:new{ w = ctx.inner_w, h = row_h },\
        pager,\
    }\
end\
\
-- Current page of the result grid: PAGE_ROWS rows (one when two do not fit\
-- the sheet), every page as tall as a full one, and the pager below.\
function CoverSearch:buildGrid(ctx)\
    local cols, cell_w, cell_h, gap = gridGeometry(ctx, ctx.inner_w)\
    local row_h = cell_h + ctx.SZ(Screen:scaleBySize(4))\
        + 2 * SUIStyle.faceHeight(captionFace(ctx)) + gap\
    local rows = PAGE_ROWS\
    if ctx.page_h and rows * row_h > ctx.page_h then rows = 1 end\
    local per_page = rows * cols\
    local npages = math.ceil(#self.results / per_page)\
    self.page = math.max(1, math.min(self.page, npages))\
\
    local grid = VerticalGroup:new{ align = \"left\" }\
    local first = (self.page - 1) * per_page + 1\
    local last  = math.min(first + per_page - 1, #self.results)\
    for row_first = first, last, cols do\
        local row = HorizontalGroup:new{ align = \"top\" }\
        for i = row_first, math.min(row_first + cols - 1, last) do\
            if i > row_first then row[#row + 1] = HorizontalSpan:new{ width = gap } end\
            row[#row + 1] = self:buildCell(ctx, i, cell_w, cell_h)\
        end\
        grid[#grid + 1] = VerticalGroup:new{\
            align = \"left\",\
            row,\
            VerticalSpan:new{ width = gap },\
        }\
    end\
    if npages > 1 then\
        local missing = rows - math.ceil((last - first + 1) / cols)\
        if missing > 0 then grid[#grid + 1] = VerticalSpan:new{ width = missing * row_h } end\
        grid[#grid + 1] = self:buildPager(ctx, npages)\
    end\
    return grid\
end\
\
function CoverSearch:sheetFooter()\
    local chosen = self.selected and self.results[self.selected]\
    return {\
        {\
            text     = _(\"Cancel\"),\
            callback = function() self.sheet:close() end,\
        },\
        {\
            text     = _(\"Use this cover\"),\
            primary  = true,\
            enabled  = chosen ~= nil,\
            callback = function()\
                self.sheet:close()\
                self.apply(chosen.path)\
            end,\
        },\
    }\
end\
\
-- Opens the sheet of results over the window.\
function CoverSearch:showResults()\
    local n = #self.results\
    self.sheet = ActionSheet.show{\
        name     = \"sui_win_cover_results\",\
        width    = self.sheet_w,\
        title    = T(N_(\"%1 cover found\", \"%1 covers found\", n), n),\
        sections = {\
            { type = \"widget\", build = function(ctx) return self:buildGrid(ctx) end },\
        },\
        footer   = self:sheetFooter(),\
        on_close = function() self.sheet = nil end,\
    }\
end\
\
function CoverSearch:build(ctx)\
    local widgets = {\
        SUIWindow.ListRow{\
            inner_w   = ctx.inner_w,\
            title     = self.query,\
            -- The book's ISBN, used unless the query is an ISBN itself.\
            subtitle  = self.isbn and not CoverSources.parseIsbn(self.query)\
                and T(_(\"ISBN %1\"), self.isbn) or nil,\
            right_icon = \"edit\",\
            on_tap    = function()\
                require(\"features/dialogs/sui_dialogs\").prompt{\
                    title       = _(\"Search covers\"),\
                    description = _(\"Title, author or ISBN\"),\
                    value       = self.query,\
                    ok_text     = _(\"Search\"),\
                    on_submit   = function(query)\
                        self.query = query\
                        self:run(ctx)\
                    end,\
                }\
            end,\
        },\
        SUIWindow.ListRow{\
            inner_w  = ctx.inner_w,\
            title    = _(\"Include Apple Books\"),\
            subtitle = _(\"Artwork is subject to Apple's terms of use\"),\
            checked  = SUISettings:isTrue(APPLE_KEY),\
            on_tap   = function()\
                SUISettings:set(APPLE_KEY, not SUISettings:isTrue(APPLE_KEY))\
                ctx.repaint()\
            end,\
        },\
    }\
    if not self.results then return widgets end\
    local n = #self.results\
    widgets[#widgets + 1] = SUIWindow.ListRow{\
        inner_w   = ctx.inner_w,\
        title     = n == 0 and _(\"No covers found.\")\
            or T(N_(\"Show %1 cover\", \"Show %1 covers\", n), n),\
        enabled   = n > 0,\
        on_tap    = n > 0 and function() self:showResults() end or nil,\
        separator = false,\
    }\
    return widgets\
end\
\
function CoverSearch:footer(ctx)\
    return SUIWindow.CenteredButtonFooter(ctx, {\
        text   = _(\"Search\"),\
        on_tap = function() self:run(ctx) end,\
    })\
end\
\
return CoverSearch\
",
    ["features/library/cover_editor/sui_cover_sources"] = "-- sui_cover_sources.lua — Simple UI\
-- Online cover search: asks Open Library, Google Books and, when enabled,\
-- Apple Books for covers of a book, downloads each one, and returns the\
-- portrait images found, largest first.\
--\
-- Each source is queried by ISBN (the exact edition) when the book has one,\
-- then by free text. A source that fails, is rate limited or finds nothing is\
-- skipped. Downloads are decoded one at a time: the full image only lives\
-- long enough to read its size and scale it to a thumbnail, and the file is\
-- kept in a cache folder (cleared on every search) for when it is applied.\
--\
-- Public API\
--   CoverSources.isbnOf(file)   -> ISBN string | nil\
--   CoverSources.parseIsbn(s)   -> ISBN string | nil (checked)\
--   CoverSources.search(opts)   -> { candidate, ... }, cancelled, offline\
--     offline: no request reached a server (no network or no internet)\
--     opts.query          string    free-text query (title and author)\
--     opts.isbn           string?\
--     opts.include_apple  bool\
--     opts.thumb_w/h      number    thumbnail bounds\
--     opts.on_progress    function(text) -> false to cancel\
--   candidate = { path, width, height, filesize, source, thumb }\
--     thumb is a Blitbuffer owned by the caller\
--   CoverSources.clearCache()\
\
local DataStorage = require(\"datastorage\")\
local T           = require(\"ffi/util\").template\
local lfs         = require(\"libs/libkoreader-lfs\")\
local logger      = require(\"logger\")\
local util        = require(\"util\")\
local _           = require(\"infra/sui_i18n\").translate\
\
local CoverNet = require(\"features/library/cover_editor/sui_cover_net\")\
\
local CoverSources = {}\
\
local MAX_PER_SOURCE = 4\
\
local function cacheDir()\
    return DataStorage:getDataDir() .. \"/cache/simpleui/cover_search\"\
end\
\
function CoverSources.clearCache()\
    local dir = cacheDir()\
    local ok, iter, dir_obj = pcall(lfs.dir, dir)\
    if not ok then return end\
    for name in iter, dir_obj do\
        if name ~= \".\" and name ~= \"..\" then os.remove(dir .. \"/\" .. name) end\
    end\
end\
\
local function encode(s)\
    return (tostring(s):gsub(\"[^%w%-%._~]\", function(c)\
        return string.format(\"%%%02X\", c:byte())\
    end))\
end\
\
-- ---------------------------------------------------------------------------\
-- ISBN\
-- ---------------------------------------------------------------------------\
\
-- The ISBN written in `s` (10 or 13 characters, spaces and hyphens allowed),\
-- as its bare characters, when its check digit is right; else nil.\
function CoverSources.parseIsbn(s)\
    local isbn = s:gsub(\"[%s%-]\", \"\"):upper()\
    local sum = 0\
    if isbn:match(\"^97[89]%d%d%d%d%d%d%d%d%d%d$\") then\
        for i = 1, 13 do\
            sum = sum + tonumber(isbn:sub(i, i)) * (i % 2 == 1 and 1 or 3)\
        end\
        return sum % 10 == 0 and isbn or nil\
    end\
    if isbn:match(\"^%d%d%d%d%d%d%d%d%d[%dX]$\") then\
        for i = 1, 10 do\
            local c = isbn:sub(i, i)\
            sum = sum + (c == \"X\" and 10 or tonumber(c)) * (11 - i)\
        end\
        return sum % 11 == 0 and isbn or nil\
    end\
end\
\
-- First ISBN in a document's identifiers: a labelled one, else any bare\
-- 13-digit ISBN.\
local function isbnFromIdentifiers(identifiers)\
    if type(identifiers) ~= \"string\" or identifiers == \"\" then return nil end\
    for value in identifiers:lower():gmatch(\"isbn[^%dx]*([%dx][%dx%s%-]+)\") do\
        local isbn = CoverSources.parseIsbn(value)\
        if isbn then return isbn end\
    end\
    for value in identifiers:gmatch(\"97[89][%d%-]+\") do\
        local isbn = CoverSources.parseIsbn(value)\
        if isbn then return isbn end\
    end\
end\
\
-- Identifiers stored when the book was opened, else read from the file's\
-- metadata (without rendering it).\
function CoverSources.isbnOf(file)\
    local BookList = require(\"ui/widget/booklist\")\
    local identifiers\
    if BookList.hasBookBeenOpened(file) then\
        local props = BookList.getDocSettings(file):readSetting(\"doc_props\")\
        identifiers = props and props.identifiers\
    end\
    if not identifiers then\
        local DocumentRegistry = require(\"document/documentregistry\")\
        local ok, props = pcall(function()\
            local doc = DocumentRegistry:openDocument(file)\
            if not doc then return nil end\
            local loaded = not doc.loadDocument or doc:loadDocument(false)\
            local result = loaded and doc:getProps() or nil\
            doc:close()\
            return result\
        end)\
        identifiers = ok and props and props.identifiers\
    end\
    return isbnFromIdentifiers(identifiers)\
end\
\
-- ---------------------------------------------------------------------------\
-- Sources: each returns the cover URLs it found, best match first\
-- ---------------------------------------------------------------------------\
\
local function openLibrary(query, isbn)\
    local urls = {}\
    if isbn then\
        -- default=false answers 404 instead of a blank image when there is none.\
        urls[#urls + 1] = \"https://covers.openlibrary.org/b/isbn/\" .. isbn .. \"-L.jpg?default=false\"\
    end\
    if query ~= \"\" then\
        local data = CoverNet.getJson(\"https://openlibrary.org/search.json?q=\" .. encode(query)\
            .. \"&limit=8&fields=cover_i\")\
        for _i, doc in ipairs(data and type(data.docs) == \"table\" and data.docs or {}) do\
            if #urls >= MAX_PER_SOURCE then break end\
            if tonumber(doc.cover_i) then\
                urls[#urls + 1] = \"https://covers.openlibrary.org/b/id/\" .. doc.cover_i .. \"-L.jpg\"\
            end\
        end\
    end\
    return urls\
end\
\
-- Largest image a Google Books imageLinks table offers. The thumbnail link\
-- serves a larger rendition when its zoom cap and page-curl effect are\
-- dropped and a width is requested.\
local function googleImage(links)\
    if type(links) ~= \"table\" then return nil end\
    local url = links.extraLarge or links.large or links.medium\
    if url then\
        return (url:gsub(\"^http:\", \"https:\"):gsub(\"&edge=curl\", \"\"))\
    end\
    url = links.small or links.thumbnail or links.smallThumbnail\
    if type(url) ~= \"string\" then return nil end\
    url = url:gsub(\"^http:\", \"https:\"):gsub(\"&edge=curl\", \"\"):gsub(\"&zoom=%d\", \"\")\
    return url .. \"&fife=w1200\"\
end\
\
local function googleBooks(query, isbn)\
    local queries = {}\
    if isbn then queries[#queries + 1] = \"isbn:\" .. isbn end\
    if query ~= \"\" then queries[#queries + 1] = query end\
    local urls = {}\
    for _i, q in ipairs(queries) do\
        local data = CoverNet.getJson(\"https://www.googleapis.com/books/v1/volumes?q=\"\
            .. encode(q) .. \"&maxResults=8\")\
        for _j, item in ipairs(data and type(data.items) == \"table\" and data.items or {}) do\
            if #urls >= MAX_PER_SOURCE then return urls end\
            local url = googleImage(item.volumeInfo and item.volumeInfo.imageLinks)\
            if url then urls[#urls + 1] = url end\
        end\
    end\
    return urls\
end\
\
-- The artwork link's size segment is rewritten to a large box; the server\
-- answers with the largest size it has, up to that box.\
local function appleBooks(query, isbn)\
    local terms = {}\
    if isbn then terms[#terms + 1] = isbn end\
    if query ~= \"\" then terms[#terms + 1] = query end\
    local urls = {}\
    for _i, term in ipairs(terms) do\
        local data = CoverNet.getJson(\"https://itunes.apple.com/search?media=ebook&limit=8&term=\"\
            .. encode(term))\
        for _j, result in ipairs(data and type(data.results) == \"table\" and data.results or {}) do\
            if #urls >= MAX_PER_SOURCE then return urls end\
            local art = result.artworkUrl100\
            if type(art) == \"string\" then\
                urls[#urls + 1] = (art:gsub(\"/%d+x%d+bb%.\", \"/1200x1200bb.\"))\
            end\
        end\
    end\
    return urls\
end\
\
local SOURCES = {\
    { id = \"openlibrary\", name = \"Open Library\", fetch = openLibrary },\
    { id = \"google\",      name = \"Google Books\", fetch = googleBooks },\
    { id = \"apple\",       name = \"Apple Books\",  fetch = appleBooks, opt_in = true },\
}\
\
-- ---------------------------------------------------------------------------\
-- Downloads\
-- ---------------------------------------------------------------------------\
\
-- File extension of image data, from its signature.\
local function imageExt(data)\
    if data:sub(1, 3) == \"\\xFF\\xD8\\xFF\" then return \"jpg\" end\
    if data:sub(1, 8) == \"\\x89PNG\\r\\n\\26\\n\" then return \"png\" end\
    if data:sub(1, 4) == \"RIFF\" and data:sub(9, 12) == \"WEBP\" then return \"webp\" end\
    if data:sub(1, 3) == \"GIF\" then return \"gif\" end\
end\
\
-- Downloads and decodes one cover; nil when it is not a usable portrait image.\
local function fetchCandidate(url, seq, opts, seen)\
    local data = CoverNet.get(url)\
    local ext = data and imageExt(data)\
    if not ext then return nil end\
    local hash = require(\"ffi/sha2\").md5(data)\
    if seen[hash] then return nil end\
    seen[hash] = true\
\
    local RenderImage = require(\"ui/renderimage\")\
    local ok, bb = pcall(RenderImage.renderImageData, RenderImage, data, #data, false)\
    if not (ok and bb) then return nil end\
    local w, h = bb:getWidth(), bb:getHeight()\
    -- Covers are portrait (or square); wider images are banners or wrong hits.\
    if w > h then\
        bb:free()\
        return nil\
    end\
    local scale = math.min(opts.thumb_w / w, opts.thumb_h / h, 1)\
    local thumb = RenderImage:scaleBlitBuffer(bb,\
        math.max(1, math.floor(w * scale)), math.max(1, math.floor(h * scale)))\
\
    local path = cacheDir() .. \"/\" .. seq .. \".\" .. ext\
    local f = io.open(path, \"wb\")\
    if not (f and f:write(data)) then\
        if f then f:close() end\
        thumb:free()\
        logger.warn(\"SimpleUI cover search: could not write\", path)\
        return nil\
    end\
    f:close()\
    return { path = path, width = w, height = h, filesize = #data, thumb = thumb }\
end\
\
function CoverSources.search(opts)\
    local query = util.trim(opts.query or \"\")\
    local progress = opts.on_progress or function() return true end\
    CoverSources.clearCache()\
    util.makePath(cacheDir())\
    CoverNet.resetAnswered()\
\
    local pending = {}\
    for _i, source in ipairs(SOURCES) do\
        if not source.opt_in or (source.id == \"apple\" and opts.include_apple) then\
            if progress(T(_(\"Searching %1\"), source.name)) == false then return {}, true end\
            local ok, urls = pcall(source.fetch, query, opts.isbn)\
            if ok then\
                for _j, url in ipairs(urls) do\
                    pending[#pending + 1] = { url = url, source = source.name }\
                end\
            else\
                logger.warn(\"SimpleUI cover search:\", source.id, urls)\
            end\
        end\
    end\
\
    local results, seen, seen_url = {}, {}, {}\
    local cancelled = false\
    for i, item in ipairs(pending) do\
        if progress(T(_(\"Downloading covers %1/%2\"), i, #pending)) == false then\
            cancelled = true\
            break\
        end\
        if not seen_url[item.url] then\
            seen_url[item.url] = true\
            local ok, candidate = pcall(fetchCandidate, item.url, i, opts, seen)\
            if ok and candidate then\
                candidate.source = item.source\
                results[#results + 1] = candidate\
            elseif not ok then\
                logger.warn(\"SimpleUI cover search:\", item.url, candidate)\
            end\
        end\
    end\
    table.sort(results, function(a, b) return a.width * a.height > b.width * b.height end)\
    return results, cancelled, CoverNet.answered() == 0\
end\
\
return CoverSources\
",
    ["features/library/cover_editor/sui_cover_store"] = "-- sui_cover_store.lua — Simple UI\
-- Reads and changes a book's cover through KOReader's own custom-cover\
-- mechanism (a `cover.<ext>` file in the book's sidecar folder), so a change\
-- shows everywhere covers are drawn, inside and outside Simple UI.\
--\
-- Every change first saves the cover it replaces in an undo slot, one per\
-- book, so the last change can be undone (and the undo itself undone). The\
-- slot is keyed by the book's partial MD5, so it survives the book being\
-- moved or renamed; it holds either the replaced custom image or a marker\
-- meaning \"the book's own cover\".\
--\
-- Public API\
--   CoverStore.load(file)                -> { bb, custom_path, width, height, filesize }\
--                                           bb is owned by the caller (free it);\
--                                           width/height are the image's own size\
--   CoverStore.apply(file, image_path)   -> ok   use an image as the book's cover\
--   CoverStore.restoreOriginal(file)     -> ok   back to the book's own cover\
--   CoverStore.canUndo(file)             -> bool\
--   CoverStore.undo(file)                -> ok   swap the cover with the undo slot\
\
local DataStorage = require(\"datastorage\")\
local DocSettings = require(\"docsettings\")\
local Event       = require(\"ui/event\")\
local UIManager   = require(\"ui/uimanager\")\
local ffiutil     = require(\"ffi/util\")\
local lfs         = require(\"libs/libkoreader-lfs\")\
local logger      = require(\"logger\")\
local util        = require(\"util\")\
\
local CoverStore = {}\
\
-- Undo slots kept at most; the oldest are dropped beyond this.\
local MAX_UNDO_SLOTS = 50\
local EMBEDDED_MARKER = \"embedded\"\
\
local function undoDir()\
    return DataStorage:getDataDir() .. \"/cache/simpleui/cover_undo\"\
end\
\
local function bookKey(file)\
    return util.partialMD5(file)\
end\
\
-- Path of the undo slot of `key`, or nil. Slots are \"<key>.<ext>\" (one dot\
-- after the key), which keeps the transient \"<key>.swap.<ext>\" out.\
local function findSlot(key)\
    local dir = undoDir()\
    local ok, iter, dir_obj = pcall(lfs.dir, dir)\
    if not ok then return nil end\
    local prefix = key .. \".\"\
    for name in iter, dir_obj do\
        if name:sub(1, #prefix) == prefix and not name:find(\".\", #prefix + 1, true) then\
            return dir .. \"/\" .. name\
        end\
    end\
end\
\
-- Drops the oldest slots beyond MAX_UNDO_SLOTS.\
local function pruneSlots()\
    local dir = undoDir()\
    local ok, iter, dir_obj = pcall(lfs.dir, dir)\
    if not ok then return end\
    local slots = {}\
    for name in iter, dir_obj do\
        if name ~= \".\" and name ~= \"..\" then\
            local path = dir .. \"/\" .. name\
            slots[#slots + 1] = { path = path, mtime = lfs.attributes(path, \"modification\") or 0 }\
        end\
    end\
    if #slots <= MAX_UNDO_SLOTS then return end\
    table.sort(slots, function(a, b) return a.mtime < b.mtime end)\
    for i = 1, #slots - MAX_UNDO_SLOTS do os.remove(slots[i].path) end\
end\
\
-- Saves the book's current cover in its undo slot, replacing any earlier one.\
local function saveUndo(file, key)\
    local old = findSlot(key)\
    if old then os.remove(old) end\
    util.makePath(undoDir())\
    local custom = DocSettings:findCustomCoverFile(file)\
    if custom then\
        local dest = undoDir() .. \"/\" .. key .. \".\" .. util.getFileNameSuffix(custom):lower()\
        if ffiutil.copyFile(custom, dest) ~= nil then\
            logger.warn(\"SimpleUI cover: could not save undo copy of\", custom)\
        end\
    else\
        local f = io.open(undoDir() .. \"/\" .. key .. \".\" .. EMBEDDED_MARKER, \"w\")\
        if f then f:close() end\
    end\
    pruneSlots()\
end\
\
-- Cover columns of a book info row, cleared so the cover is extracted again.\
local BOOKINFO_COVER_RESET = {\
    cover_fetched   = false,\
    has_cover       = false,\
    cover_sizetag   = false,\
    cover_w         = false,\
    cover_h         = false,\
    cover_bb_type   = false,\
    cover_bb_stride = false,\
    cover_bb_data   = false,\
}\
\
-- Tells the open document, the book info cache and every screen that the\
-- cover changed. Only the cover of the book info row is cleared: its title,\
-- authors and series stay known while the cover is extracted again, so lists\
-- grouped or filtered by them keep the book.\
local function notifyChanged(file)\
    local ReaderUI = package.loaded[\"apps/reader/readerui\"]\
    local reader = ReaderUI and ReaderUI.instance\
    if reader and reader.doc_settings and reader.document and reader.document.file == file then\
        reader.doc_settings:getCustomCoverFile(true)\
    end\
    local ok, BookInfoManager = pcall(require, \"bookinfomanager\")\
    if ok and BookInfoManager then\
        BookInfoManager:setBookInfoProperties(file, BOOKINFO_COVER_RESET)\
    end\
    UIManager:broadcastEvent(Event:new(\"BookMetadataChanged\"))\
end\
\
local function writeCustom(file, image_path)\
    local old = DocSettings:findCustomCoverFile(file)\
    if old then os.remove(old) end\
    return DocSettings:flushCustomCover(file, image_path) == true\
end\
\
local function removeCustom(file)\
    local old = DocSettings:findCustomCoverFile(file)\
    if not old then return true end\
    if not os.remove(old) then return false end\
    DocSettings.removeSidecarDir((util.splitFilePathName(old)))\
    return true\
end\
\
-- A custom image is decoded at its own size (opening it as a document would\
-- scale it to the screen); the book's own cover comes from the document.\
function CoverStore.load(file)\
    local custom_path = DocSettings:findCustomCoverFile(file)\
    local ok, bb = pcall(function()\
        if custom_path then\
            return require(\"ui/renderimage\"):renderImageFile(custom_path, false)\
        end\
        local BookInfo = require(\"apps/filemanager/filemanagerbookinfo\")\
        local ReaderUI = package.loaded[\"apps/reader/readerui\"]\
        local reader   = ReaderUI and ReaderUI.instance\
        local document = reader and reader.document\
        if document and document.file ~= file then document = nil end\
        return BookInfo:getCoverImage(document, file, true)\
    end)\
    if not ok then\
        logger.warn(\"SimpleUI cover: could not load cover of\", file, bb)\
        bb = nil\
    end\
    return {\
        bb          = bb,\
        custom_path = custom_path,\
        width       = bb and bb:getWidth(),\
        height      = bb and bb:getHeight(),\
        filesize    = custom_path and lfs.attributes(custom_path, \"size\"),\
    }\
end\
\
function CoverStore.apply(file, image_path)\
    local key = bookKey(file)\
    if key then saveUndo(file, key) end\
    local ok = writeCustom(file, image_path)\
    notifyChanged(file)\
    return ok\
end\
\
function CoverStore.restoreOriginal(file)\
    local key = bookKey(file)\
    if key then saveUndo(file, key) end\
    local ok = removeCustom(file)\
    notifyChanged(file)\
    return ok\
end\
\
function CoverStore.canUndo(file)\
    local key = bookKey(file)\
    return key ~= nil and findSlot(key) ~= nil\
end\
\
function CoverStore.undo(file)\
    local key = bookKey(file)\
    local slot = key and findSlot(key)\
    if not slot then return false end\
    -- Move the slot aside so saving the current cover cannot overwrite it.\
    local ext  = util.getFileNameSuffix(slot)\
    local swap = undoDir() .. \"/\" .. key .. \".swap.\" .. ext\
    if not os.rename(slot, swap) then return false end\
    saveUndo(file, key)\
    local ok\
    if ext == EMBEDDED_MARKER then\
        ok = removeCustom(file)\
    else\
        ok = writeCustom(file, swap)\
    end\
    os.remove(swap)\
    notifyChanged(file)\
    return ok\
end\
\
return CoverStore\
",
    ["features/library/cover_editor/sui_cover_window"] = "-- sui_cover_window.lua — Simple UI\
-- \"Book cover\" window: shows a book's current cover with where it comes from\
-- and its size, and the actions that change it (online search, an image\
-- from the device, undo of the last change, the book's own cover). A tap on\
-- the cover shows it full screen. The online search is a second screen.\
--\
-- The decoded cover is kept for the window's life, shared by the preview and\
-- the full-screen view, and freed when it is replaced or the window closes.\
--\
-- Public API\
--   CoverWindow.show(file, opts)\
--     opts.on_change  function?  called after the cover changed\
\
local CenterContainer  = require(\"ui/widget/container/centercontainer\")\
local Device           = require(\"device\")\
local DocumentRegistry = require(\"document/documentregistry\")\
local Font             = require(\"ui/font\")\
local FrameContainer   = require(\"ui/widget/container/framecontainer\")\
local Geom             = require(\"ui/geometry\")\
local HorizontalGroup  = require(\"ui/widget/horizontalgroup\")\
local HorizontalSpan   = require(\"ui/widget/horizontalspan\")\
local ImageWidget      = require(\"ui/widget/imagewidget\")\
local Size             = require(\"ui/size\")\
local TextWidget       = require(\"ui/widget/textwidget\")\
local UIManager        = require(\"ui/uimanager\")\
local VerticalGroup    = require(\"ui/widget/verticalgroup\")\
local VerticalSpan     = require(\"ui/widget/verticalspan\")\
local util             = require(\"util\")\
local _                = require(\"infra/sui_i18n\").translate\
local Screen           = Device.screen\
\
local CoverPlaceholder = require(\"engines/sui_cover_placeholder\")\
local SUIWindow        = require(\"engines/sui_window\")\
local SUIStyle         = require(\"features/sui_style\")\
local UI               = require(\"infra/sui_core\")\
local CoverSearch      = require(\"features/library/cover_editor/sui_cover_search\")\
local CoverStore       = require(\"features/library/cover_editor/sui_cover_store\")\
\
local CoverWindow = {}\
\
local COVER_ASPECT = 1.5\
local PREVIEW_FRACTION = 0.28  -- of the window's inner width\
\
-- The cover fitted into a w × h box, in a thin frame, centred in a column w\
-- wide and as tall as the framed image.\
local function buildPreview(cover, book, w, h)\
    if not cover.bb then\
        return CoverPlaceholder.build(w, h, book.title, book.authors)\
    end\
    local border = Size.border.thin\
    local scale  = math.min((w - 2 * border) / cover.width, (h - 2 * border) / cover.height)\
    local img_h  = math.max(1, math.floor(cover.height * scale))\
    local image = ImageWidget:new{\
        image            = cover.bb,\
        image_disposable = false,\
        width            = math.max(1, math.floor(cover.width * scale)),\
        height           = img_h,\
    }\
    return CenterContainer:new{\
        dimen = Geom:new{ w = w, h = img_h + 2 * border },\
        FrameContainer:new{\
            bordersize = border,\
            color      = SUIStyle.COLOR.text_primary,\
            padding    = 0,\
            margin     = 0,\
            image,\
        },\
    }\
end\
\
-- One \"label  value\" line of the details column.\
local function detailLine(label, value, face, max_w)\
    local label_w = UI.makeColoredText{\
        text    = label,\
        face    = face,\
        fgcolor = SUIStyle.COLOR.text_dim,\
    }\
    local gap = Size.span.horizontal_default\
    return HorizontalGroup:new{\
        align = \"center\",\
        label_w,\
        HorizontalSpan:new{ width = gap },\
        TextWidget:new{\
            text      = value,\
            face      = face,\
            max_width = math.max(1, max_w - label_w:getSize().w - gap),\
        },\
    }\
end\
\
local function sourceText(cover)\
    if cover.custom_path then return _(\"Custom image\") end\
    if cover.bb then return _(\"Book file\") end\
    return _(\"No cover\")\
end\
\
-- Preview on the left, title, author and cover details on the right. A tap\
-- on the preview (or Press when it has the focus) runs `on_view`.\
local function buildHeader(ctx, cover, book, on_view)\
    local SZ = ctx.SZ\
    local preview_w = math.floor(ctx.inner_w * PREVIEW_FRACTION)\
    local preview_h = math.floor(preview_w * COVER_ASPECT)\
    local gap       = SZ(Screen:scaleBySize(16))\
    local text_w    = math.max(1, ctx.inner_w - preview_w - gap)\
\
    local title_face  = Font:getFace(SUIStyle.FACE_REGULAR, SZ(SUIStyle.FS_BODY))\
    local detail_face = Font:getFace(SUIStyle.FACE_REGULAR, SZ(SUIStyle.FS_DETAIL))\
\
    local info = VerticalGroup:new{ align = \"left\" }\
    info[#info + 1] = TextWidget:new{\
        text      = book.title,\
        face      = title_face,\
        bold      = true,\
        max_width = text_w,\
    }\
    if book.authors and book.authors ~= \"\" then\
        info[#info + 1] = UI.makeColoredText{\
            text      = book.authors,\
            face      = detail_face,\
            fgcolor   = SUIStyle.COLOR.text_dim,\
            max_width = text_w,\
        }\
    end\
    info[#info + 1] = VerticalSpan:new{ width = SZ(Screen:scaleBySize(12)) }\
    info[#info + 1] = detailLine(_(\"Source\"), sourceText(cover), detail_face, text_w)\
    if cover.width and cover.height then\
        info[#info + 1] = detailLine(_(\"Dimensions\"),\
            string.format(\"%d × %d\", cover.width, cover.height), detail_face, text_w)\
    end\
    if cover.filesize then\
        info[#info + 1] = detailLine(_(\"File size\"),\
            util.getFriendlySize(cover.filesize), detail_face, text_w)\
    end\
\
    local preview = buildPreview(cover, book, preview_w, preview_h)\
    if cover.bb then\
        preview = SUIWindow.Input.tapable(preview, { on_tap = on_view },\
            Geom:new{ w = preview_w, h = preview:getSize().h })\
    end\
\
    return VerticalGroup:new{\
        align = \"left\",\
        VerticalSpan:new{ width = SZ(Screen:scaleBySize(12)) },\
        HorizontalGroup:new{\
            align = \"top\",\
            preview,\
            HorizontalSpan:new{ width = gap },\
            info,\
        },\
        VerticalSpan:new{ width = SZ(Screen:scaleBySize(8)) },\
    }\
end\
\
function CoverWindow.show(file, opts)\
    opts = opts or {}\
    local SH   = require(\"modules/module_books_shared\")\
    local book = SH.getBookData(file)\
    local state = {}\
\
    local function reload()\
        if state.cover and state.cover.bb then state.cover.bb:free() end\
        state.cover    = CoverStore.load(file)\
        state.can_undo = CoverStore.canUndo(file)\
    end\
\
    local win\
    -- Runs a cover change, then shows the new cover (back on the main screen\
    -- when `back` is set) and refreshes the caller.\
    local function change(fn, back)\
        if not fn() then\
            UI.Notify.toast(_(\"Could not change the cover.\"))\
        end\
        reload()\
        if back then win:pop() else win:repaint() end\
        if opts.on_change then opts.on_change() end\
    end\
\
    local function searchOnline(ctx)\
        state.search = state.search or CoverSearch.new{\
            file  = file,\
            book  = book,\
            apply = function(path)\
                change(function() return CoverStore.apply(file, path) end, true)\
            end,\
        }\
        ctx.push(\"search\")\
        if not state.search.results then state.search:run(ctx) end\
    end\
\
    local function showFullScreen()\
        local ImageViewer = require(\"ui/widget/imageviewer\")\
        UIManager:show(ImageViewer:new{\
            image            = state.cover.bb,\
            image_disposable = false,\
            with_title_bar   = false,\
            fullscreen       = true,\
        })\
    end\
\
    local function chooseFromDevice()\
        local AssetBrowser = require(\"engines/sui_asset_browser\")\
        UIManager:show(AssetBrowser:new{\
            path       = (util.splitFilePathName(file)),\
            extensions = DocumentRegistry.image_ext,\
            title      = _(\"Choose cover image\"),\
            onConfirm  = function(path)\
                change(function() return CoverStore.apply(file, path) end)\
            end,\
        })\
    end\
\
    local function confirmRestore()\
        require(\"features/dialogs/sui_dialogs\").confirm{\
            text        = _(\"Restore the book's original cover?\"),\
            ok_text     = _(\"Restore\"),\
            ok_callback = function()\
                change(function() return CoverStore.restoreOriginal(file) end)\
            end,\
        }\
    end\
\
    local function buildRoot(ctx)\
        local cover = state.cover\
        return {\
            buildHeader(ctx, cover, book, showFullScreen),\
            SUIWindow.ListRow{\
                inner_w   = ctx.inner_w,\
                title     = _(\"Search online\"),\
                show_chevron = true,\
                on_tap    = function() searchOnline(ctx) end,\
            },\
            SUIWindow.ListRow{\
                inner_w   = ctx.inner_w,\
                title     = _(\"Choose from device\"),\
                on_tap    = chooseFromDevice,\
            },\
            SUIWindow.ListRow{\
                inner_w   = ctx.inner_w,\
                title     = _(\"Undo last change\"),\
                enabled   = state.can_undo,\
                on_tap    = function()\
                    change(function() return CoverStore.undo(file) end)\
                end,\
            },\
            SUIWindow.ListRow{\
                inner_w   = ctx.inner_w,\
                title     = _(\"Restore original cover\"),\
                enabled   = cover.custom_path ~= nil,\
                on_tap    = confirmRestore,\
                separator = false,\
            },\
        }\
    end\
\
    reload()\
    win = SUIWindow:new{\
        name          = \"sui_win_book_cover\",\
        icon          = \"cover\",\
        title         = _(\"Book cover\"),\
        screen_titles = { search = _(\"Search online\") },\
        auto_height_per_screen = true,\
        navpager_mode = require(\"infra/sui_config\").isNavpagerEnabled(),\
        screens       = {\
            __root__ = buildRoot,\
            search   = function(ctx) return state.search:build(ctx) end,\
        },\
        screen_footers = {\
            search = function(ctx) return state.search:footer(ctx) end,\
        },\
        on_close      = function()\
            if state.cover and state.cover.bb then state.cover.bb:free() end\
            if state.search then state.search:free() end\
            state.cover, state.search = nil, nil\
        end,\
    }\
    win:show()\
    return win\
end\
\
return CoverWindow\
",
}
